create view saller.Stock_RawMaterial
  as select p.ItemCode,
    p.ItemName,
    p.ItemType,
    max(p.OpeningStock) as Opn_Stock,
    sum(PD.Quantity) as Total_Purchase,
    sum(mi.Quantity) as Total_Issue,
    max(p.OpeningStock)+sum(PD.Quantity)-sum(mi.Quantity) as cls_stock
    from Saller.ItemInformation as p
      ,Saller.MaterIssueNoteDetail as mi
      ,Saller.PurchaseDetail as pd
    where p.itemCode = mi.ItemCode
    and p.itemCode = pd.ItemCode
    and p.itemType = 'M'
    group by p.itemCode,p.itemName,p.itemType
go

COMMENT TO PRESERVE FORMAT ON VIEW "saller"."Stock_RawMaterial" IS 
{create view saller.Stock_RawMaterial
  as select p.ItemCode,
    p.ItemName,
    p.ItemType,
    max(p.OpeningStock) as Opn_Stock,
    sum(PD.Quantity) as Total_Purchase,
    sum(mi.Quantity) as Total_Issue,
    max(p.OpeningStock)+sum(PD.Quantity)-sum(mi.Quantity) as cls_stock from
    Saller.ItemInformation as p,
    Saller.MaterIssueNoteDetail as mi,
    Saller.PurchaseDetail as pd where
    p.itemCode=mi.ItemCode
    and p.itemCode=pd.ItemCode
    and p.itemType='M'
    group by p.itemCode,p.itemName,p.itemType
}
go

create view saller.stock_Finished as select p.ItemCode,
    p.ItemName,
    p.ItemType,
    max(p.OpeningStock) as opn_Stock,
    sum(DPR.Quantity) as total_production,
    sum(sd.Quantity) as total_Sale,
    max(p.OpeningStock)+sum(Dpr.Quantity)-sum(sd.Quantity) as Cls_Stock
    from Saller.DPRDetail as dpr
      ,Saller.ItemInformation as p
      ,Saller.SaleInvoiceDetail as sd
    where sd.itemCode = p.itemCode
    and dpr.itemCode = p.itemCode
    and p.ItemType = 'F'
    group by p.ItemCode,p.ItemName,
    p.ItemType
go

COMMENT TO PRESERVE FORMAT ON VIEW "saller"."stock_Finished" IS 
{create VIEW saller."stock_Finished"  as select p.ItemCode,
    p.ItemName,
    p.ItemType,
    max(p.OpeningStock) as opn_Stock,
    sum(DPR.Quantity) as total_production,
    sum(sd.Quantity) as total_Sale,
    max(p.OpeningStock)+sum(Dpr.Quantity)-sum(sd.Quantity) as Cls_Stock from
    Saller.DPRDetail as dpr,
    Saller.ItemInformation as p,
    Saller.SaleInvoiceDetail as sd where
    sd.itemCode=p.itemCode
    and dpr.itemCode=p.itemCode
    and p.ItemType='F'
    group by p.ItemCode,p.ItemName,
    p.ItemType
}
