create view saller.View_Inventory_Dept /* view_column_name, ... */
  /* Type the select statement here */
  as select T.SORT,T.DEPTID,T.ITEM_ID,T.ITEMNAME,T.DOCUMENT_DATE,convert(varchar(8),T.DOCUMENT_NO),T.DOCUMENT_NAME,
    T.OPENING_QTY,T.GRN_QTY,T.SR_QTY,
    T.SALE_QTY,T.PR_QTY,T.ISSUE_QTY,T.INWARD_REC_QTY,T.CONSUMED_QTY,T.DPR_QTY,T.UNDPR_QTY
    /* SELECT * FROM PURCHASEHEADER */
    /* SELECT * FROM SRHEADER */
    /* SELECT * FROM INWARDHEADER  ( TYPE "INWARD" AND DEPARTMENT "ISSUE")  */
    /* SELECT * FROM INWARDHEADER  ( TYPE "ISSUE" AND DEPARTMENT "RECEIPT")  */
    /* SELECT * FROM INWARDHEADER  ( TYPE "OUTWARD" AND DEPARTMENT "ISSUE")  */
    /* SELECT * FROM SALEINVOICEHEADER */
    /* SELECT * FROM PRHEADER */
    /* SELECT * FROM SAHEADER */
    from(select SORT=1,DEPTID=S.DEPT_ID,ITEM_ID=I.ITEMCODE,I.ITEMNAME,DOCUMENT_DATE='1900-01-01',
        DOCUMENT_NO=null,DOCUMENT_NAME='OPENING',
        OPENING_QTY=S.OPEN_QTY,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,
        ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.ITEMINFORMATION as I left outer join saller.OPENING_STOCK as S on I.ITEMCODE = S.ITEMCODE union all
      select SORT=2,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.PURCHASEINVOICEDATE,
        DOCUMENT_NO=convert(varchar(8),H.DOCUMENTNO),DOCUMENT_NAME='PURCHASE',
        OPENING_QTY=0,GRN_QTY=D.QUANTITY,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.PURCHASEHEADER as H join saller.PURCHASEDETAIL as D
          on H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE union all
      select SORT=1,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.DPRDATE,
        DOCUMENT_NO=convert(varchar(8),H.DPRCODE),DOCUMENT_NAME='PRODUCTION',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=D.QUANTITY,UNDPR_QTY=0
        from saller.DPRHEADER as H join saller.DPRDETAIL as D
          on H.DPRCODE = D.DPRCODE union all
      select SORT=3,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.SRDATE,
        DOCUMENT_NO=convert(varchar(8),H.DOCUMENTNO),DOCUMENT_NAME='SALE RETURN',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=D.QUANTITY,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.SRHEADER as H join saller.SRDETAIL as D
          on H.SRNO = D.SRNO union all
      select SORT=4,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.MINDATE,
        DOCUMENT_NO=convert(varchar(8),H.MINCODE),DOCUMENT_NAME='MATERIAL ISSUE',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=D.QUANTITY,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.MaterialIssueNoteHeader as H join saller.MaterIssueNoteDetail as D
          on H.MINCODE = D.MINCODE union all
      select SORT=4,H.DEPTID_TO,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.MINDATE,
        DOCUMENT_NO=convert(varchar(8),H.MINCODE),DOCUMENT_NAME='MATERIAL RECEIPT',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=D.QUANTITY,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.MaterialIssueNoteHeader as H join saller.MaterIssueNoteDetail as D
          on H.MINCODE = D.MINCODE union all
      select SORT=6,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.CONSNOTEDATE,
        DOCUMENT_NO=convert(varchar(8),H.CONSNOTECODE),DOCUMENT_NAME='CONSUMPTION',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=D.QUANTITY,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.CONSUMPTIONNOTEHEADER as H join saller.CONSUMPTIONNOTEDETAIL as D
          on H.CONSNOTECODE = D.CONSNOTECODE union all
      select SORT=8,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.INVOICEDATE,
        DOCUMENT_NO=convert(varchar(8),H.DOCUMENTNO),DOCUMENT_NAME='SALE',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=D.QUANTITY,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.SALEINVOICEHEADER as H join saller.SALEINVOICEDETAIL as D
          on H.SALEINVOICECODE = D.SALEINVOICECODE union all
      select SORT=9,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.PRDATE,
        DOCUMENT_NO=convert(varchar(8),H.DOCUMENTNO),DOCUMENT_NAME='PURCHSE RETURN',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=D.QUANTITY,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0
        from saller.PRHEADER as H join saller.PRDETAIL as D
          on H.PRNO = D.PRNO union all
      select SORT=9,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
        DOCUMENT_DATE=H.SADATE,
        DOCUMENT_NO=convert(varchar(8),H.SACODE),DOCUMENT_NAME='STOCK ADJUSTMENT',
        OPENING_QTY=0,GRN_QTY=0,SR_QTY=0,
        SALE_QTY=0,PR_QTY=0,ISSUE_QTY=0,INWARD_REC_QTY=0,CONSUMED_QTY=0,
        OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=D.QUANTITY
        from saller.SAHEADER as H join saller.SADETAIL as D
          on H.SACODE = D.SACODE) as T( SORT,
      DEPTID,ITEM_ID,ITEMNAME,DOCUMENT_DATE,DOCUMENT_NO,DOCUMENT_NAME,OPENING_QTY,GRN_QTY,SR_QTY,SALE_QTY,PR_QTY,ISSUE_QTY,INWARD_REC_QTY,CONSUMED_QTY,
      OUTWARD_REC_QTY,DPR_QTY,UNDPR_QTY ) 
go

COMMENT TO PRESERVE FORMAT ON VIEW "saller"."View_Inventory_Dept" IS 
{create VIEW saller."View_Inventory_Dept" /* view_column_name, ... */
  /* Type the select statement here */
  as select T.SORT,T.DEPTID,T.ITEM_ID,T.ITEMNAME,T.DOCUMENT_DATE,convert(varchar(8),T.DOCUMENT_NO),T.DOCUMENT_NAME,
    T.OPENING_QTY,T.GRN_QTY,T.SR_QTY,
    T.SALE_QTY,T.PR_QTY,T.ISSUE_QTY,T.INWARD_REC_QTY,T.CONSUMED_QTY,T.DPR_QTY,T.UNDPR_QTY from(
    select SORT=1,DEPTID=S.DEPT_ID,ITEM_ID=I.ITEMCODE,I.ITEMNAME,DOCUMENT_DATE='1900-01-01',
      DOCUMENT_NO=null,DOCUMENT_NAME='OPENING',
      OPENING_QTY=S.OPEN_QTY,GRN_QTY=0,SR_QTY=0,
