      OUTWARD_REC_QTY=0,DPR_QTY=0,UNDPR_QTY=0 from
      saller.PURCHASEHEADER as H join saller.PURCHASEDETAIL as D on
      H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE union all
    select SORT=1,H.DEPTID,D.ITEMCODE,D.ITEMNAME,
      DOCUMENT_DATE=H.DPRDATE,
