      saller.SAHEADER as H join saller.SADETAIL as D on
      H.SACODE = D.SACODE) as T( SORT,
    DEPTID,ITEM_ID,ITEMNAME,DOCUMENT_DATE,DOCUMENT_NO,DOCUMENT_NAME,OPENING_QTY,GRN_QTY,SR_QTY,SALE_QTY,PR_QTY,ISSUE_QTY,INWARD_REC_QTY,CONSUMED_QTY,
    OUTWARD_REC_QTY,DPR_QTY,UNDPR_QTY)
