create view saller.VIEW_INVOICES
  as select T.DOCUMENTNAME,T.DOCUMENTNO,T.DOCUMENTDATE,T.ACCOUNTCODE,
    C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,T.NETAMOUNT
    -- PURCHASE ENTRIES 
    -- PURCHASE RETURN 
    -- SALE INVOICES
    -- SALE RETURN INVOICES
    -- CASH RECEIPT ENTRIES
    -- CASH PAYMENT ENTRIES
    -- BANK RECEIPT ENTRIES
    -- BANK PAYMENT ENTRIES
    -- GENERAL JOURNAL ENTRIES 
    from(select DOCUMENTNAME='PU',P.DOCUMENTNO,DOCUMENTDATE=P.PURCHASEINVOICEDATE,ACCOUNTCODE=P.PARTYCODE,ACCOUNTNAME=P.NAME,P.NETAMOUNT
        from saller.PURCHASEHEADER as P union all
      select DOCUMENTNAME='PR',P.DOCUMENTNO,DOCUMENTDATE=P.PRDATE,ACCOUNTCODE=P.PARTYCODE,ACCOUNTNAME=P.NAME,P.NETAMOUNT
        from saller.PRHEADER as P union all
      select DOCUMENTNAME='SL',S.DOCUMENTNO,DOCUMENTDATE=S.INVOICEDATE,ACCOUNTCODE=S.PARTYCODE,ACCOUNTNAME=S.NAME,S.NETAMOUNT
        from saller.SALEINVOICEHEADER as S union all
      select DOCUMENTNAME='SR',S.DOCUMENTNO,DOCUMENTDATE=S.SRDATE,ACCOUNTCODE=S.PARTYCODE,ACCOUNTNAME=S.NAME,S.NETAMOUNT
        from saller.SRHEADER as S union all
      select DOCUMENTNAME=V.VOUCHERTYPE,DOCUMENTNO=V.VOUCHERID,DOCUMENTDATE=V.VOUCHERDATE,V.ACCOUNTCODE,C.ACCOUNTNAME,NETAMOUNT=V.CREDIT
        from saller.VOUCHER as V join saller.CHART as C on C.ACCOUNTCODE = V.ACCOUNTCODE
        where V.VOUCHERTYPE = 'CRV' and V.SEQNO = 1 union all
      select DOCUMENTNAME=V.VOUCHERTYPE,DOCUMENTNO=V.VOUCHERID,DOCUMENTDATE=V.VOUCHERDATE,V.ACCOUNTCODE,C.ACCOUNTNAME,NETAMOUNT=V.DEBIT
        from saller.VOUCHER as V join saller.CHART as C on C.ACCOUNTCODE = V.ACCOUNTCODE
        where V.VOUCHERTYPE = 'CPV' and V.SEQNO = 1 union all
      select DOCUMENTNAME=V.VOUCHERTYPE,DOCUMENTNO=V.VOUCHERID,DOCUMENTDATE=V.VOUCHERDATE,V.ACCOUNTCODE,C.ACCOUNTNAME,NETAMOUNT=V.CREDIT
        from saller.VOUCHER as V join saller.CHART as C on C.ACCOUNTCODE = V.ACCOUNTCODE
        where V.VOUCHERTYPE = 'BRV' and V.SEQNO = 1 union all
      select DOCUMENTNAME=V.VOUCHERTYPE,DOCUMENTNO=V.VOUCHERID,DOCUMENTDATE=V.VOUCHERDATE,V.ACCOUNTCODE,C.ACCOUNTNAME,NETAMOUNT=V.DEBIT
        from saller.VOUCHER as V join saller.CHART as C on C.ACCOUNTCODE = V.ACCOUNTCODE
        where V.VOUCHERTYPE = 'BPV' and V.SEQNO = 1 union all
      select DOCUMENTNAME=V.VOUCHERTYPE,DOCUMENTNO=V.VOUCHERID,DOCUMENTDATE=V.VOUCHERDATE,V.ACCOUNTCODE,C.ACCOUNTNAME,NETAMOUNT=V.DEBIT
        from saller.VOUCHER as V join saller.CHART as C on C.ACCOUNTCODE = V.ACCOUNTCODE
        where V.VOUCHERTYPE = 'JVR' and V.SEQNO = 1 and DOCUMENTNO is null) as T( DOCUMENTNAME,DOCUMENTNO,DOCUMENTDATE,ACCOUNTCODE,ACCOUNTNAME,NETAMOUNT ) 
      left outer join saller.CHART as C on T.ACCOUNTCODE = C.ACCOUNTCODE
    where C.ACCOUNTCATEGORY in( 'S','V','P' )  -- AND LENGTH(C.MOBILENO) > 0

go

COMMENT TO PRESERVE FORMAT ON VIEW "saller"."VIEW_INVOICES" IS 
{create VIEW VIEW_INVOICES 
AS 
SELECT T.DOCUMENTNAME , T.DOCUMENTNO, T.DOCUMENTDATE, T.ACCOUNTCODE, 
       C.ACCOUNTNAME, C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY, T.NETAMOUNT 
FROM   
     ( 
        -- PURCHASE ENTRIES 
        SELECT DOCUMENTNAME = 'PU', P.DOCUMENTNO , DOCUMENTDATE = P.PURCHASEINVOICEDATE, ACCOUNTCODE = P.PARTYCODE, ACCOUNTNAME = P.NAME, P.NETAMOUNT 
        FROM PURCHASEHEADER AS P 
        UNION ALL 
        
        -- PURCHASE RETURN 
        SELECT DOCUMENTNAME = 'PR', P.DOCUMENTNO , DOCUMENTDATE = P.PRDATE, ACCOUNTCODE = P.PARTYCODE, ACCOUNTNAME = P.NAME, P.NETAMOUNT 
        FROM PRHEADER AS P
        UNION ALL

        -- SALE INVOICES
        SELECT DOCUMENTNAME = 'SL', S.DOCUMENTNO , DOCUMENTDATE = S.INVOICEDATE, ACCOUNTCODE = S.PARTYCODE, ACCOUNTNAME = S.NAME, S.NETAMOUNT 
        FROM SALEINVOICEHEADER AS S 
        UNION ALL
        
        -- SALE RETURN INVOICES
        SELECT DOCUMENTNAME = 'SR', S.DOCUMENTNO , DOCUMENTDATE = S.SRDATE, ACCOUNTCODE = S.PARTYCODE, ACCOUNTNAME = S.NAME, S.NETAMOUNT 
        FROM SRHEADER AS S 
        UNION ALL
        
        -- CASH RECEIPT ENTRIES
        SELECT DOCUMENTNAME = V.VOUCHERTYPE, DOCUMENTNO= V.VOUCHERID, DOCUMENTDATE =V.VOUCHERDATE, V.ACCOUNTCODE, C.ACCOUNTNAME, NETAMOUNT = V.CREDIT
        FROM VOUCHER AS V INNER JOIN CHART AS C ON C.ACCOUNTCODE = V.ACCOUNTCODE
        WHERE VOUCHERTYPE = 'CRV' AND SEQNO = 1
        UNION ALL
        
        -- CASH PAYMENT ENTRIES
        SELECT DOCUMENTNAME = V.VOUCHERTYPE, DOCUMENTNO= V.VOUCHERID, DOCUMENTDATE =V.VOUCHERDATE, V.ACCOUNTCODE, C.ACCOUNTNAME, NETAMOUNT = V.DEBIT
        FROM VOUCHER AS V INNER JOIN CHART AS C ON C.ACCOUNTCODE = V.ACCOUNTCODE
        WHERE VOUCHERTYPE = 'CPV' AND SEQNO = 1
        UNION ALL

         -- BANK RECEIPT ENTRIES
        SELECT DOCUMENTNAME = V.VOUCHERTYPE, DOCUMENTNO= V.VOUCHERID, DOCUMENTDATE =V.VOUCHERDATE, V.ACCOUNTCODE, C.ACCOUNTNAME, NETAMOUNT = V.CREDIT
        FROM VOUCHER AS V INNER JOIN CHART AS C ON C.ACCOUNTCODE = V.ACCOUNTCODE
        WHERE VOUCHERTYPE = 'BRV' AND SEQNO = 1
        UNION ALL
        
        -- BANK PAYMENT ENTRIES
        SELECT DOCUMENTNAME = V.VOUCHERTYPE, DOCUMENTNO= V.VOUCHERID, DOCUMENTDATE =V.VOUCHERDATE, V.ACCOUNTCODE, C.ACCOUNTNAME, NETAMOUNT = V.DEBIT
        FROM VOUCHER AS V INNER JOIN CHART AS C ON C.ACCOUNTCODE = V.ACCOUNTCODE
        WHERE VOUCHERTYPE = 'BPV' AND SEQNO = 1
        UNION ALL

        -- GENERAL JOURNAL ENTRIES 
        SELECT DOCUMENTNAME = V.VOUCHERTYPE, DOCUMENTNO= V.VOUCHERID, DOCUMENTDATE =V.VOUCHERDATE, V.ACCOUNTCODE, C.ACCOUNTNAME, NETAMOUNT = V.DEBIT
        FROM VOUCHER AS V INNER JOIN CHART AS C ON C.ACCOUNTCODE = V.ACCOUNTCODE
        WHERE VOUCHERTYPE = 'JVR' AND SEQNO = 1 AND DOCUMENTNO IS NULL 

      ) AS T LEFT OUTER JOIN CHART AS C ON T.ACCOUNTCODE = C.ACCOUNTCODE

WHERE ACCOUNTCATEGORY IN ( 'S', 'V', 'P' ) -- AND LENGTH(C.MOBILENO) > 0
}
go

