create procedure saller.invoice_search( @sort varchar(2),@start_date date,@end_date date ) as
begin
  if @sort = '1'
    select code=documentno,
      pdate=purchaseinvoicedate,
      name=name
      from purchaseheader
      where status = '0' and pdate >= @start_date and pdate <= @end_date
  else
    if @sort = '2'
      select code=documentno,
        pdate=invoicedate,
        name=name
        from saleinvoiceheader
        where status = '0' and pdate >= @start_date and pdate <= @end_date
    else
      if @sort = '3'
        select code=compcode,
          itemcode,
          pdate=compdate,
          name=itemname
          from compositionheader where pdate >= @start_date and pdate <= @end_date
      else
        if @sort = '4'
          select code=mincode,
            pdate=mindate,
            name=mindesc
            from materialissuenoteheader where pdate >= @start_date and pdate <= @end_date
        else
          if @sort = '5'
            select code=dprcode,
              pdate=dprdate,
              name=shiftdesc
              from dprheader
              where status = '1' and pdate >= @start_date and pdate <= @end_date
  if @sort = '6'
    select code=documentno,
      pdate=srdate,
      name=name
      from srheader where approved = '0' and pdate >= @start_date and pdate <= @end_date
  if @sort = '7'
    select code=documentno,
      pdate=prdate,
      name=name
      from prheader where approved = '0' and pdate >= @start_date and pdate <= @end_date
  if @sort = '8'
    select code=documentno,
      pdate=purchaseinvoicedate,
      name=name
      from purchaseheader
      where status = '1' and pdate >= @start_date and pdate <= @end_date
  else
    if @sort = '9'
      select code=documentno,
        pdate=invoicedate,
        name=name
        from saleinvoiceheader
        where status = '1' and pdate >= @start_date and pdate <= @end_date
  if @sort = '10'
    select code=documentno,
      pdate=srdate,
      name=name
      from srheader where approved = '1' and pdate >= @start_date and pdate <= @end_date
  if @sort = '11'
    select code=documentno,
      pdate=prdate,
      name=name
      from prheader where approved = '1' and pdate >= @start_date and pdate <= @end_date
  if @sort = '12'
    select code=accountcode,
      pdate=document_date,
      name=name
      from customer_price_policy where approved = '0' and pdate >= @start_date and pdate <= @end_date
  if @sort = '13' --Select the inward entry.
    select code=documentno,
      pdate=inwarddate,
      name=name
      from inwardheader where pdate >= @start_date --change 20.12.2021
      and pdate <= @end_date
  if @sort = '14' --Select the price Policy entry.
    select code=document_no,
      pdate=document_date,
      name=narration
      from price_policy_header where pdate >= @start_date
      and pdate <= @end_date
end
go

