create procedure saller.item_search( @sort varchar(1) ) as
begin
  if @sort = '1'
    select code=itemcode,
      name=itemname,
      itemtype
      from iteminformation where status = '1'
  else
    if @sort = '2'
      select code=itemcode,
        name=itemname,
        itemtype
        from iteminformation
        where itemtype = 'F'
    else
      if @sort = '3'
        select code=itemcode,
          name=itemname,
          itemtype
          from iteminformation
          where itemtype = 'M'
      else
        if @sort = '4'
          select code=itemcode,
            name=itemname,
            itemtype
            from iteminformation
            where itemtype = 'O'
        else
          if @sort = '5'
            select code=itemcode,
              name=itemname,
              itemtype
              from iteminformation
              where itemtype between 'F' and 'M'
          else
            if @sort = '6'
              select code=itemcode,
                name=itemname,
                itemtype
                from iteminformation
                where itemtype = 'S'
end
go

