create procedure saller.r_saleinvoice( @startcode integer,@endcode integer ) as
begin
  select sih.documentno,sih.invoicedate,sih.partycode,sih.partytype,
    sih.name,sih.address,sih.city,sih.deptid,sih.salestype,sih.remarks,sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,
    sid.amount,sid.discountrate,detaildiscount=sid.discountamount,sih.discountamount,sid.totalamount,sih.saleorderno,i.packingsize,
    sid.measuringunit,previou_balance=saller.uf_getPreviosBalance(sih.saleinvoicecode),sih.despatch,
    sih.saleinvoicecode,sih.price_policy_no
    from saleinvoiceheader as sih,saleinvoicedetail as sid,iteminformation as i
    where sih.saleinvoicecode = sid.saleinvoicecode
    and sid.itemcode = i.itemcode
    and sih.saleinvoicecode between @startcode and @endcode
end
execute r_saleinvoice '10001','10001'
