create procedure saller.sp_post_dpr( @dpr_code numeric(10),@dpr_date date,@status char(1) ) 
as
begin
  declare @shiftcode varchar(11),
  @compcode varchar(11),
  @rm_code varchar(32),
  @rm_name varchar(64),
  @rm_quantity numeric(14,3),
  @rm_wastagerate numeric(14,3),
  @concode integer,
  @wastagequantity numeric(14,3),
  @total_finished tinyint,
  @total_rm tinyint,
  @i tinyint,
  @j tinyint,
  @seqNo tinyint,
  @finished_Code varchar(11),
  @finished_Qty numeric(14,3),
  @deptid varchar(10),
  @user_code varchar(10)
  if @status = 1
    begin
      select @DeptID = deptID from dprheader where dprcode = @dpr_code
      select @concode = isnull(max(consnotecode),0) from consumptionnoteheader
      select @concode = @concode+1
      /*insert the values into consumption note header Table  */
      insert into consumptionnoteheader( consnotecode,
        consnotedate,compcode,dprcode,usercode,doc,status,deptid ) 
        values( @concode,@dpr_date,@compcode,@dpr_code,@user_code,@dpr_date,'1',@deptID ) 
      declare dpr_detail dynamic scroll cursor for select itemCode,Quantity from DPRDetail
          where dprCode = @dpr_Code
      select @total_finished = @@rowCount,@i = 1,@seqNo = 1
      open dpr_detail
      fetch next dpr_detail into @finished_Code,@finished_Qty
      while @@sqlstatus <> 2
        --@i<=@total_finished
        begin
          --- Get the CompositionCode of the Selected Finished Good Item
          select @compCode = CompCode
            from CompositionHeader
            where itemCode = @finished_Code and status = '1'
          ---- Second Cursor for the Composition of Finished Prodouct Just Fetched
          declare composition dynamic scroll cursor for select itemCode,itemName,Quantity,WastageRate from CompositionDetail
              where CompCode = @compCode
          open composition
          fetch next composition into @rm_code,@rm_name,@rm_quantity,@rm_wastagerate
          while @@sqlstatus <> 2
            begin
              --- insert row in the Consumption Detail
              insert into consumptionNoteDetail( ConsNoteCode,
                SeqNo,ItemCode,ItemName,Quantity,WastageRate,WastageQuantity,
                userCode,finishcode ) 
                values( @concode,@seqNo,@rm_code,@rm_name,@rm_quantity*@finished_Qty,
                @rm_wastagerate,@rm_quantity*@finished_qty*@rm_wastagerate/100,@user_code,@finished_Code ) 
              select @seqNo = @seqNo+1
              fetch next composition into @rm_code,@rm_name,@rm_quantity,@rm_wastagerate
            end
          close composition
          deallocate cursor composition
          fetch next dpr_detail into @finished_Code,@finished_Qty
        end
      close dpr_detail
      deallocate cursor dpr_detail
    end
  if @status = '0'
    begin
      -- get the Consumption Code of the Selected Dpr
      select @concode = isnull(consnotecode,0) from consumptionNoteHeader
        where dprCode = @dpr_Code
      if @concode > 0
        begin
          --- Delete All rows from the Consumption Detail Table
          delete from consumptionNoteDetail
            where consNoteCode = @concode
          --- Delete the Header Row from the Consumption Header
          delete from consumptionNoteHeader
            where consNoteCode = @concode
        end
    end
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."sp_post_dpr" IS 
{create PROCEDURE saller."sp_post_dpr"(@dpr_code numeric(10),@dpr_date date,@status char(1))
as
begin
  declare @shiftcode varchar(11),
