create procedure Saller.r_iteminformation( @itemtype varchar(1) )  /* parameters,... */
/* RESULT ( column-name,... ) */
as
begin
  if @itemtype = 'A'
    select itemcode,itemname,itemtype,measuringunit,packingquantity,
      salerate,purchaserate,openingstock,usercode,openingrate,openingamount,batch,packingsize
      from iteminformation where status = '1'
  else
    select itemcode,itemname,itemtype,measuringunit,packingquantity,
      salerate,purchaserate,openingstock,usercode,openingrate,openingamount,batch,packingsize
      from iteminformation where itemtype = @itemtype
      and status = '1'
end
