  select sih.documentno,sih.invoicedate,sih.partycode,
    max(sih.name),sih.address,sih.city,sum(sid.quantity),
    sih.netamount,sih.despatch from
    saleinvoiceheader as sih,saleinvoicedetail as sid where
    sih.saleinvoicecode=sid.saleinvoicecode
