create procedure saller.r_dprsummary( @style varchar(1),@group_code varchar(14),@startcode varchar(20),@endcode varchar(20),@startdate date,@enddate date ) 
/* RESULT ( column-name,... ) */
as
begin
  if @style = '0'
    select dph.dprcode,dph.dprdate,dph.shiftdesc,
      sum(dpd.quantity)
      from dprheader as dph,dprdetail as dpd
      where dph.dprcode = dpd.dprcode
      and dph.dprdate between @startdate and @enddate
      and status = '1' group by dph.dprcode,dph.dprdate,dph.shiftdesc
  if @style = '1'
    select dph.dprcode,dph.dprdate,dph.shiftdesc,
      sum(dpd.quantity)
      from dprheader as dph,dprdetail as dpd
      where dph.dprcode = dpd.dprcode
      and dph.dprdate between @startdate and @enddate
      and dpd.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group_code)
      and status = '1' group by dph.dprcode,dph.dprdate,dph.shiftdesc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_dprsummary" IS 
{create PROCEDURE saller."r_dprsummary"(@style varchar(1),@group_code varchar(14),@startcode varchar(20),@endcode varchar(20),@startdate date,@enddate date)
/* RESULT ( column-name,... ) */
as
begin
if @style='0'
  select dph.dprcode,dph.dprdate,dph.shiftdesc,
    sum(dpd.quantity) from
    dprheader as dph,dprdetail as dpd where
    dph.dprcode=dpd.dprcode
    and dph.dprdate between @startdate and @enddate and 
    status='1' group by dph.dprcode,dph.dprdate,dph.shiftdesc
if @style='1'
    select dph.dprcode,dph.dprdate,dph.shiftdesc,
    sum(dpd.quantity) from
    dprheader as dph,dprdetail as dpd where
    dph.dprcode=dpd.dprcode
    and dph.dprdate between @startdate and @enddate and 
    dpd.itemcode=any(select itemcode from itemgroupdetail where groupcode=@group_code)
    and status='1' group by dph.dprcode,dph.dprdate,dph.shiftdesc

end
}
go

