create procedure Saller.r_return( @startdate date,@enddate date ) as
begin
  select c.name,c.address,c.city,c.saletaxno,
    pamount=(select isnull(sum(ph.netamount),0)
      from purchaseheader as ph
      where ph.purchaseinvoicedate >= @startdate and ph.purchaseinvoicedate <= @enddate),
    pstamount=isnull(sum(ph.saletaxamount),0),
    samount=isnull(sum(ih.netamount),0),
    sstamount=isnull(sum(ih.saletaxamount),0),
    pramount=isnull(sum(prh.saletaxamount),0),
    prstamount=isnull(sum(prh.saletaxamount),0),
    sramount=isnull(sum(srh.netamount),0),
    srstamount=isnull(sum(srh.stamount),0)
    from companyinformation as c
      ,purchaseheader as ph
      ,saleinvoiceheader as ih
      ,prheader as prh
      ,srheader as srh
    where ph.purchaseinvoicedate between @startdate and @enddate
    group by c.name,c.address,c.city,c.saletaxno
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_return" IS 
{create procedure Saller.r_return(@startdate date,@enddate date) as
begin
  select c.name,c.address,c.city,c.saletaxno,
    pamount=(select isnull(sum(ph.netamount),0) from
      purchaseheader as ph where
      ph.purchaseinvoicedate>=@startdate and ph.purchaseinvoicedate<=@enddate),
    pstamount=isnull(sum(ph.saletaxamount),0),
    samount=isnull(sum(ih.netamount),0),
    sstamount=isnull(sum(ih.saletaxamount),0),
    pramount=isnull(sum(prh.saletaxamount),0),
    prstamount=isnull(sum(prh.saletaxamount),0),
    sramount=isnull(sum(srh.netamount),0),
    srstamount=isnull(sum(srh.stamount),0) from
    companyinformation as c,
    purchaseheader as ph,
    saleinvoiceheader as ih,
    prheader as prh,
    srheader as srh where
    ph.purchaseinvoicedate between @startdate and @enddate
    group by c.name,c.address,c.city,c.saletaxno
end
}
go

create procedure Saller.r_itemwise_stock( @startCode varchar(32),@endCode varchar(32),@startdate date,@endDate date ) 
as
begin
  select i.itemcode,i.itemname,t.currdate,t.remarks,
    isnull(sum(t.openingstock),0),sum(t.sale),sum(t.purchase),sum(t.dpr),
    sum(t.salereturn),sum(t.purchasereturn),sum(t.consumption),
    sum(t.adjustment),sum(t.issue)
    from iteminformation as i
      --- calculate opening stock from the product table
      --Calculte Opening Stock from sale
      --Select Openingstock from Purchase
      --Select OpeningStock From DPR
      --Select OpeningStock SaleReturn
      --Select OpeningStock From PurchaseReturn
      --Select OpeningStock From Consumtion
      --Select OpeningStock From Adjustment Header
      --Select OpeningStock From Material Issue Header
      --Detail From Sale
      --Detail from Purchase
      --Detail From DPR
      --Detail From SR
      --Detail From PR
      --Detail From CON
      --Detail From Material issue 
      --Select Detail From Adjustment
      join(select i.itemCode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(i.openingstock,0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from iteminformation as i
        where i.itemCode between @startCode and @endCode union all
      select sd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=-isnull(sum(sd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from saleinvoicedetail as sd join saleinvoiceheader as sh
          on sd.saleinvoicecode = sh.saleinvoicecode
        where sh.invoicedate < @startdate
        and sd.itemcode between @startcode and @endcode
        group by sd.itemcode union all
      select pd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(sum(pd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from purchasedetail as pd join purchaseheader as ph
          on pd.purchaseinvoicecode = ph.purchaseinvoicecode
        where ph.purchaseinvoicedate < @startdate
        and pd.itemcode between @startcode and @endcode
        group by pd.itemcode union all
      select dd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(sum(dd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from dprdetail as dd join dprheader as dh
          on dd.dprcode = dh.dprcode
        where dh.dprdate < @startdate
        and dd.itemcode between @startcode and @endcode
        group by dd.itemcode union all
      select srd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(sum(srd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from srdetail as srd join srheader as srh
          on srd.srno = srh.srno
        where srh.srdate < @startdate
        and srd.itemcode between @startcode and @endcode
        group by srd.itemcode union all
      select prd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=-isnull(sum(prd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from prdetail as prd join prheader as prh
          on prd.prno = prh.prno
        where prh.prdate < @startdate
        and prd.itemcode between @startcode and @endcode
        group by prd.itemcode union all
      select cd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=-isnull(sum(cd.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from ConsumptionNotedetail as cd join ConsumptionNoteheader as ch
          on cd.consnotecode = ch.consnotecode
        where ch.consnotedate < @startdate
        and cd.itemcode between @startcode and @endcode
        group by cd.itemcode union all
      select ad.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(sum(ad.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from sadetail as ad join saheader as ah
          on ad.sacode = ah.sacode
        where ah.sadate < @startdate
        and ad.itemcode between @startcode and @endcode
        group by ad.itemcode union all
      select md.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
        openingstock=isnull(sum(md.quantity),0),sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from materissuenotedetail as md join materialissuenoteheader as mh
          on md.mincode = mh.mincode
        where mh.mindate < @startdate
        and md.itemcode between @startcode and @endcode
        group by md.itemcode union all
      select sd.itemcode,sh.invoicedate,remarks='SALE INV#'+convert(varchar(32),sh.saleinvoicecode),
        openingstock=0,sale=sd.quantity,
        purchase=0,dpr=0,salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from saleinvoicedetail as sd join saleinvoiceheader as sh
          on sd.saleinvoicecode = sh.saleinvoicecode
        where sh.invoicedate between @startdate and @enddate
        and sd.itemcode between @startcode and @endcode union all
      select pd.itemcode,ph.purchaseinvoicedate,remarks='PUR INV#'+convert(varchar(32),ph.purchaseinvoicecode),
        openingstock=0,sale=0,purchase=pd.quantity,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from purchasedetail as pd join purchaseheader as ph
          on pd.purchaseinvoicecode = ph.purchaseinvoicecode
        where ph.purchaseinvoicedate between @startdate and @enddate
        and pd.itemcode between @startcode and @endcode union all
      select dd.itemcode,dh.dprdate,remarks='DPR#'+convert(varchar(32),dh.dprcode),
        openingstock=0,sale=0,purchase=0,dpr=dd.quantity,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from dprdetail as dd join dprheader as dh
          on dd.dprcode = dh.dprcode
        where dh.dprdate between @startdate and @enddate
        and dd.itemcode between @startcode and @endcode union all
      select srd.itemcode,srh.srdate,remarks='S.R#'+convert(varchar(32),srh.srno),
        openingstock=0,sale=0,purchase=0,dpr=0,
        salereturn=srd.quantity,purchasereturn=0,consumption=0,adjustment=0,issue=0
        from srdetail as srd join srheader as srh
          on srd.srno = srh.srno
        where srh.srdate between @startdate and @enddate
        and srd.itemcode between @startcode and @endcode union all
      select prd.itemcode,prh.prdate,remarks='P.R#'+convert(varchar(32),prh.prno),
        openingstock=0,sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=prd.quantity,consumption=0,adjustment=0,issue=0
        from prdetail as prd join prheader as prh
          on prd.prno = prh.prno
        where prh.prdate between @startdate and @enddate
        and prd.itemcode between @startcode and @endcode union all
      select cd.itemcode,ch.consnotedate,remarks='CON#'+convert(varchar(32),ch.consnotecode),
        openingstock=0,sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=cd.quantity,adjustment=0,issue=0
        from ConsumptionNotedetail as cd join ConsumptionNoteheader as ch
          on cd.consnotecode = ch.consnotecode
        where ch.consnotedate between @startdate and @enddate
        and cd.itemcode between @startcode and @endcode union all
      select md.itemcode,mh.mindate,remarks='MIN#'+convert(varchar(32),mh.mincode),
        openingstock=0,sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=md.quantity
        from materissueNotedetail as md join Materialissuenoteheader as mh
          on md.mincode = mh.mincode
        where mh.mindate between @startdate and @enddate
        and md.itemcode between @startcode and @endcode union all
      select ad.itemcode,ah.sadate,remarks='ADJ#'+convert(varchar(32),ah.sacode),
        openingstock=0,sale=0,purchase=0,dpr=0,
        salereturn=0,purchasereturn=0,consumption=0,adjustment=ad.quantity,issue=0
        from sadetail as ad join saheader as ah
          on ad.sacode = ah.sacode
        where ah.sadate between @startdate and @enddate
        and ad.itemcode between @startcode and @endcode) as t
      on i.itemcode = t.itemcode
    where i.itemcode between @startcode and @endcode
    group by i.itemcode,i.itemname,t.currdate,t.remarks
    order by i.itemcode asc,i.itemname asc,t.currdate asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_itemwise_stock" IS 
{create procedure Saller.r_itemwise_stock(@startCode varchar(32),@endCode varchar(32),@startdate date,@endDate date)
as
begin
  select i.itemcode,i.itemname,t.currdate,t.remarks,
    isnull(sum(t.openingstock),0),sum(t.sale),sum(t.purchase),sum(t.dpr),
    sum(t.salereturn),sum(t.purchasereturn),sum(t.consumption),
    sum(t.adjustment),sum(t.issue) from
    iteminformation as i join(
    --- calculate opening stock from the product table
    select i.itemCode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(i.openingstock,0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      iteminformation as i where
      i.itemCode between @startCode and @endCode union all
    --Calculte Opening Stock from sale
    select sd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=-isnull(sum(sd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      saleinvoicedetail as sd join saleinvoiceheader as sh on
      sd.saleinvoicecode=sh.saleinvoicecode where
      sh.invoicedate<@startdate
      and sd.itemcode between @startcode and @endcode
      group by sd.itemcode union all
    --Select Openingstock from Purchase
    select pd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(sum(pd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      purchasedetail as pd join purchaseheader as ph on
      pd.purchaseinvoicecode=ph.purchaseinvoicecode where
      ph.purchaseinvoicedate<@startdate
      and pd.itemcode between @startcode and @endcode
      group by pd.itemcode union all
    --Select OpeningStock From DPR
    select dd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(sum(dd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      dprdetail as dd join dprheader as dh on
      dd.dprcode=dh.dprcode where
      dh.dprdate<@startdate
      and dd.itemcode between @startcode and @endcode
      group by dd.itemcode union all
    --Select OpeningStock SaleReturn
    select srd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(sum(srd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      srdetail as srd join srheader as srh on
      srd.srno=srh.srno where
      srh.srdate<@startdate
      and srd.itemcode between @startcode and @endcode
      group by srd.itemcode union all
    --Select OpeningStock From PurchaseReturn
    select prd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=-isnull(sum(prd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      prdetail as prd join prheader as prh on
      prd.prno=prh.prno where
      prh.prdate<@startdate
      and prd.itemcode between @startcode and @endcode
      group by prd.itemcode union all
    --Select OpeningStock From Consumtion
    select cd.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=-isnull(sum(cd.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      ConsumptionNotedetail as cd join ConsumptionNoteheader as ch on
      cd.consnotecode=ch.consnotecode where
      ch.consnotedate<@startdate
      and cd.itemcode between @startcode and @endcode
      group by cd.itemcode union all
    --Select OpeningStock From Adjustment Header
    select ad.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(sum(ad.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      sadetail as ad join saheader as ah on
      ad.sacode=ah.sacode where
      ah.sadate<@startdate
      and ad.itemcode between @startcode and @endcode
      group by ad.itemcode union all
    --Select OpeningStock From Material Issue Header
    select md.itemcode,currdate='1900-01-01',remarks=convert(varchar(32),'OpeningStock'),
      openingstock=isnull(sum(md.quantity),0),sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      materissuenotedetail as md join materialissuenoteheader as mh on
      md.mincode=mh.mincode where
      mh.mindate<@startdate
      and md.itemcode between @startcode and @endcode
      group by md.itemcode union all
    --Detail From Sale
    select sd.itemcode,sh.invoicedate,remarks='SALE INV#'+convert(varchar(32),sh.saleinvoicecode),
      openingstock=0,sale=sd.quantity,
      purchase=0,dpr=0,salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      saleinvoicedetail as sd join saleinvoiceheader as sh on
      sd.saleinvoicecode=sh.saleinvoicecode where
      sh.invoicedate between @startdate and @enddate
      and sd.itemcode between @startcode and @endcode union all
    --Detail from Purchase
    select pd.itemcode,ph.purchaseinvoicedate,remarks='PUR INV#'+convert(varchar(32),ph.purchaseinvoicecode),
      openingstock=0,sale=0,purchase=pd.quantity,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      purchasedetail as pd join purchaseheader as ph on
      pd.purchaseinvoicecode=ph.purchaseinvoicecode where
      ph.purchaseinvoicedate between @startdate and @enddate
      and pd.itemcode between @startcode and @endcode union all
    --Detail From DPR
    select dd.itemcode,dh.dprdate,remarks='DPR#'+convert(varchar(32),dh.dprcode),
      openingstock=0,sale=0,purchase=0,dpr=dd.quantity,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      dprdetail as dd join dprheader as dh on
      dd.dprcode=dh.dprcode where
      dh.dprdate between @startdate and @enddate
      and dd.itemcode between @startcode and @endcode union all
    --Detail From SR
    select srd.itemcode,srh.srdate,remarks='S.R#'+convert(varchar(32),srh.srno),
      openingstock=0,sale=0,purchase=0,dpr=0,
      salereturn=srd.quantity,purchasereturn=0,consumption=0,adjustment=0,issue=0 from
      srdetail as srd join srheader as srh on
      srd.srno=srh.srno where
      srh.srdate between @startdate and @enddate
      and srd.itemcode between @startcode and @endcode union all
    --Detail From PR
    select prd.itemcode,prh.prdate,remarks='P.R#'+convert(varchar(32),prh.prno),
      openingstock=0,sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=prd.quantity,consumption=0,adjustment=0,issue=0 from
      prdetail as prd join prheader as prh on
      prd.prno=prh.prno where
      prh.prdate between @startdate and @enddate
      and prd.itemcode between @startcode and @endcode union all
    --Detail From CON
    select cd.itemcode,ch.consnotedate,remarks='CON#'+convert(varchar(32),ch.consnotecode),
      openingstock=0,sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=cd.quantity,adjustment=0,issue=0 from
      ConsumptionNotedetail as cd join ConsumptionNoteheader as ch on
      cd.consnotecode=ch.consnotecode where
      ch.consnotedate between @startdate and @enddate
      and cd.itemcode between @startcode and @endcode union all
    --Detail From Material issue 
    select md.itemcode,mh.mindate,remarks='MIN#'+convert(varchar(32),mh.mincode),
      openingstock=0,sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=0,issue=md.quantity from
      materissueNotedetail as md join Materialissuenoteheader as mh on
      md.mincode=mh.mincode where
      mh.mindate between @startdate and @enddate
      and md.itemcode between @startcode and @endcode union all
    --Select Detail From Adjustment
    select ad.itemcode,ah.sadate,remarks='ADJ#'+convert(varchar(32),ah.sacode),
      openingstock=0,sale=0,purchase=0,dpr=0,
      salereturn=0,purchasereturn=0,consumption=0,adjustment=ad.quantity,issue=0 from
      sadetail as ad join saheader as ah on
      ad.sacode=ah.sacode where
      ah.sadate between @startdate and @enddate
      and ad.itemcode between @startcode and @endcode) as t on
    i.itemcode=t.itemcode where
    i.itemcode between @startcode and @endcode
    group by i.itemcode,i.itemname,t.currdate,t.remarks order by
    i.itemcode asc,i.itemname asc,t.currdate asc
end
}
go

create procedure saller.p_ItemTypeWise_StockValue( @AsOfDate date ) 
/*  Procedure for evaluating stock in hand.
**  Author:  Abdul Sattar Mughal         Date: 2002-04-19
*/
as
begin
  select t2.ItemType,StockValue=sum(t2.ClosingStockValue)
    /* Produced */
    /* Purchased */
    /* Sale Returned */
    /* Sold */
    /* Consumed */
    /* Purchase Returned */
    from(select i.ItemCode,i.ItemType,ClosingStockValue=isNull((isNull(max(i.OpeningStock),0)+sum(t.ProducedQty)+sum(t.PurchasedQty)
        +sum(t.SaleReturnedQty)-sum(t.SoldQty)-sum(t.ConsumedQty)-sum(t.PurchaseReturnedQty)),0)*isNull(max(i.PurchaseRate),0)
        from ItemInformation as i
          ,(select dprd.ItemCode,ProducedQty=sum(dprd.Quantity),
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from DPRHeader as dprh,DPRDetail as dprd
            where dprh.DPRCode = dprd.DPRCode
            and dprh.Status = '1'
            and dprh.DPRDate <= @AsOfDate
            group by dprd.ItemCode union all
          select pd.ItemCode,ProducedQty=0,
            PurchasedQty=sum(pd.Quantity),SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from PurchaseHeader as ph,PurchaseDetail as pd
            where ph.PurchaseInvoiceCode = pd.PurchaseInvoiceCode
            and ph.Status = '1'
            and ph.PurchaseInvoiceDate <= @AsOfDate
            group by pd.ItemCode union all
          select srd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=sum(srd.Quantity),SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from SRHeader as srh,SRDetail as srd
            where srh.SRNo = srd.SRNo
            and srh.Approved = '1'
            and srh.SRDate <= @AsOfDate
            group by srd.ItemCode union all
          select sd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=sum(sd.Quantity),
            ConsumedQty=0,PurchaseReturnedQty=0
            from SaleInvoiceHeader as sh,SaleInvoiceDetail as sd
            where sh.SaleInvoiceCode = sd.SaleInvoiceCode
            and sh.Status = '1'
            and sh.InvoiceDate <= @AsOfDate
            group by sd.ItemCode union all
          select cd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=sum(cd.Quantity),PurchaseReturnedQty=0
            from ConsumptionNoteHeader as ch,ConsumptionNoteDetail as cd
            where ch.ConsNoteCode = cd.ConsNoteCode
            and ch.ConsNoteDate <= @AsOfDate
            group by cd.ItemCode union all
          select prd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=sum(prd.Quantity)
            from PRHeader as prh,PRDetail as prd
            where prh.PRNo = prd.PRNo
            and prh.Approved = '1'
            and prh.PRDate <= @AsOfDate
            group by prd.ItemCode) as t
        where i.ItemCode *= t.ItemCode
        group by i.ItemCode,i.ItemType) as t2
    group by t2.ItemType
end
go

COMMENT ON PROCEDURE "saller"."p_ItemTypeWise_StockValue" IS 
	'Item type wise stock in hand value as of a given date. Procedure uses Sale Rate to evaluate stocks.'
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."p_ItemTypeWise_StockValue" IS 
{create procedure saller.p_ItemTypeWise_StockValue(@AsOfDate date)
/*  Procedure for evaluating stock in hand.
**  Author:  Abdul Sattar Mughal         Date: 2002-04-19
*/
as
begin
  select t2.ItemType,StockValue=sum(t2.ClosingStockValue) from
    (select i.ItemCode,i.ItemType,ClosingStockValue=isNull((isNull(max(i.OpeningStock),0)+sum(t.ProducedQty)+sum(t.PurchasedQty)
      +sum(t.SaleReturnedQty)-sum(t.SoldQty)-sum(t.ConsumedQty)-sum(t.PurchaseReturnedQty)),0)*isNull(max(i.PurchaseRate),0) from
      ItemInformation as i,(
      /* Produced */
      select dprd.ItemCode,ProducedQty=sum(dprd.Quantity),
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        DPRHeader as dprh,DPRDetail as dprd where
        dprh.DPRCode=dprd.DPRCode
        and dprh.Status='1'
        and dprh.DPRDate<=@AsOfDate
        group by dprd.ItemCode union all
      /* Purchased */
      select pd.ItemCode,ProducedQty=0,
        PurchasedQty=sum(pd.Quantity),SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        PurchaseHeader as ph,PurchaseDetail as pd where
        ph.PurchaseInvoiceCode=pd.PurchaseInvoiceCode
        and ph.Status='1'
        and ph.PurchaseInvoiceDate<=@AsOfDate
        group by pd.ItemCode union all
      /* Sale Returned */
      select srd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=sum(srd.Quantity),SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        SRHeader as srh,SRDetail as srd where
        srh.SRNo=srd.SRNo
        and srh.Approved='1'
        and srh.SRDate<=@AsOfDate
        group by srd.ItemCode union all
      /* Sold */
      select sd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=sum(sd.Quantity),
        ConsumedQty=0,PurchaseReturnedQty=0 from
        SaleInvoiceHeader as sh,SaleInvoiceDetail as sd where
        sh.SaleInvoiceCode=sd.SaleInvoiceCode
        and sh.Status='1'
        and sh.InvoiceDate<=@AsOfDate
        group by sd.ItemCode union all
      /* Consumed */
      select cd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=sum(cd.Quantity),PurchaseReturnedQty=0 from
        ConsumptionNoteHeader as ch,ConsumptionNoteDetail as cd where
        ch.ConsNoteCode=cd.ConsNoteCode
        and ch.ConsNoteDate<=@AsOfDate
        group by cd.ItemCode union all
      /* Purchase Returned */
      select prd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=sum(prd.Quantity) from
        PRHeader as prh,PRDetail as prd where
        prh.PRNo=prd.PRNo
        and prh.Approved='1'
        and prh.PRDate<=@AsOfDate
        group by prd.ItemCode) as t where
      i.ItemCode*=t.ItemCode
      group by i.ItemCode,i.ItemType) as t2
    group by t2.ItemType
end
}
go

create procedure saller.r_purchasesummary( @startdate date,@enddate date ) 
/* RESULT ( column-name,... ) */
begin
  select pih.documentno,pih.purchaseinvoicedate,pih.partycode,
    pih.name,pih.address,pih.city,sum(pid.quantity),max(pid.purchaserate),
    pih.netamount,pih.despatch from purchaseheader as pih,purchasedetail as pid
    where pih.purchaseinvoicecode = pid.purchaseinvoicecode
    and pih.purchaseinvoicedate between @startdate and @enddate
    and status = '1' group by pih.documentno,pih.purchaseinvoicedate,pih.partycode,
    pih.name,pih.address,pih.city,pih.netamount,pih.despatch order by pih.purchaseinvoicedate asc,pih.documentno asc
end
go

