  select pih.documentno,pih.purchaseinvoicedate,pih.partycode,
    pih.name,pih.address,pih.city,sum(pid.quantity),max(pid.purchaserate),
    pih.netamount,pih.despatch from purchaseheader as pih,purchasedetail as pid where
    pih.purchaseinvoicecode=pid.purchaseinvoicecode
    and pih.purchaseinvoicedate between @startdate and @enddate
