      -SUM(T.CONSUMED_QTY))
      *isnull(T.PURCHASERATE,0) from
      (select T.ITEM_ID,
        ITEM_INFO=I.ITEMNAME,T.DEPTID,
        OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
        -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
        GRN_QTY=0,
        SR_QTY=0,
        SALE_QTY=0,
        PR_QTY=0,
        ISSUE_QTY=0,
        INWARD_REC_QTY=0,
        DPR_QTY=0,
        CONSUMED_QTY=0,UNDPR_QTY=0,I.PURCHASERATE from /*=isNull(saller.UF_GET_LAST_PURCHASE_RATE(T.ITEM_ID),0)*/
        VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I on
        T.ITEM_ID=I.ITEMCODE where
