create procedure Saller.r_finish_inventory_register( @startCode varchar(32),@endCode varchar(32),@startdate date,@endDate date ) 
as
begin
  select pcode=res.itemcode,
    pdesc=res.itemName,
    sl_rate=res.saleRate,
    pr_rate=res.purchaseRate,
    opening_stk=res.opn_stk,
    current_date=res.curr_date,
    transaction_type=res.transaction_type,
    document_no=res.doc_no,
    total_sale_qty=res.tot_sale,
    total_sale_amount=res.tot_sal_amount,
    total_dpr_qty=res.tot_dpr,
    total_available=res.tot_dpr-res.tot_sale+res.tot_sr+res.tot_purchase-res.tot_pr,
    total_sr_qty=res.tot_sr,
    total_sr_Amount=res.tot_sr_amount,
    total_purchase_qty=res.tot_purchase,
    total_purchase=res.tot_purchase_amount,
    total_pr_qty=res.tot_pr,
    total_pr_amount=res.tot_pr_amount
    from(select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh
            ,SrDetail as sr
          where sr.itemCode = p.ItemCode
          and sr.SrNo = Srh.SrNo
          and srh.SrDate <= @startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph
            ,purchaseDetail as purd
          where purd.itemCode = p.itemCode
          and ph.PurchaseInvoiceCode = purd.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh
            ,PrDetail as prd
          where prd.itemCode = p.ItemCode
          and prh.PrNo = prd.PrNo
          and prh.prDate <= @startDate),0)
        +isnull((select sum(pd.Quantity) from DPRHeader as ph
            ,DPRDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.DPRCode = ph.DPRCode
          and ph.DPRDate <= @startdate),0),
        curr_date=dpr.DPRDate,transaction_type='DPR',
        doc_no=dpr.DPRCode,
        tot_sale=0,
        tot_sal_amount=0,
        tot_dpr=isnull(dpr.tot_pur,0),
        tot_sr=0,
        tot_sr_Amount=0,
        tot_purchase=0,
        tot_purchase_amount=0,
        tot_pr=0,
        tot_pr_Amount=0
        from ItemInformation as p
          ,(select dprh.DPRDate,
            dprh.DPRCode,
            dprd.ItemCode,
            tot_pur=sum(quantity)
            from DPRHeader as dprh
              ,DPRDetail as dprd
            where dprh.DPRCode = dprd.DPRCode
            and dprh.DPRDate >= @startdate
            and dprh.DPRDate <= @enddate
            group by dprh.DPRCode,dprh.DPRDate,dprd.ItemCode) as dpr
        where p.ItemCode = dpr.ItemCode
        and dpr.DPRDate between @startdate and @enddate union all
      select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh
            ,SrDetail as sr
          where sr.itemCode = p.ItemCode
          and sr.SrNo = Srh.SrNo
          and srh.SrDate <= @startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph
            ,purchaseDetail as purd
          where purd.itemCode = p.itemCode
          and ph.PurchaseInvoiceCode = purd.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh
            ,PrDetail as prd
          where prd.itemCode = p.ItemCode
          and prh.PrNo = prd.PrNo
          and prh.prDate <= @startDate),0)
        +isnull((select sum(pd.Quantity) from DPRHeader as ph
            ,DPRDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.DPRCode = ph.DPRCode
          and ph.DPRDate <= @startdate),0),
        curr_date=sinv.invoiceDate,transaction_type='S',
        doc_no=sinv.saleInvoiceCode,
        tot_sale=isnull(sinv.tot_sale,0),
        tot_sal_amount=isnull(sinv.tot_sal_amount,0),
        tot_dpr=0,
        tot_sr=0,
        tot_sr_amount=0,
        tot_purchase=0,
        tot_purchase_amount=0,
        tot_pr=0,
        tot_pr_Amount=0
        from ItemInformation as p
          ,(select inv.invoiceDate,
            inv.saleInvoiceCode,
            invd.ItemCode,
            tot_sale=sum(invd.quantity),
            tot_sal_amount=sum(invd.Amount)
            from saleInvoiceHeader as inv,saleInvoiceDetail as invd
            where inv.saleInvoiceCode = invd.saleInvoiceCode
            group by inv.saleInvoiceCode,inv.invoiceDate,invd.ItemCode) as sinv
        where p.ItemCode *= sinv.ItemCode
        and sinv.invoiceDate between @startdate and @enddate union all
      select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh
            ,SrDetail as sr
          where sr.itemCode = p.ItemCode
          and sr.SrNo = Srh.SrNo
          and srh.SrDate <= @startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph
            ,purchaseDetail as purd
          where purd.itemCode = p.itemCode
          and ph.PurchaseInvoiceCode = purd.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh
            ,PrDetail as prd
          where prd.itemCode = p.ItemCode
          and prh.PrNo = prd.PrNo
          and prh.prDate <= @startDate),0)
        +isnull((select sum(pd.Quantity) from DPRHeader as ph
            ,DPRDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.DPRCode = ph.DPRCode
          and ph.DPRDate <= @startdate),0),
        curr_date=sr.srDate,transaction_type='SR',
        doc_no=sr.srNo,
        tot_sale=0,
        tot_sal_amount=0,
        tot_dpr=0,
        tot_sr=isnull(sr.tot_sr,0),
        tot_sr_Amount=isnull(sr.tot_sr_amount,0),
        tot_purchase=0,
        tot_purchase_amount=0,
        tot_pr=0,
        tot_pr_Amount=0
        from ItemInformation as p
          ,(select sr.srDate,
            sr.srNo,
            srd.ItemCode,
            tot_sr=sum(srd.quantity),
            tot_sr_amount=sum(srd.Amount)
            from srHeader as sr,srDetail as srd
            where sr.SrNo = srd.SrNo
            group by Sr.SrNo,Sr.SrDate,Srd.ItemCode) as sr
        where p.ItemCode *= Sr.ItemCode
        and sr.SrDate between @startdate and @enddate union all
      select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh
            ,SrDetail as sr
          where sr.itemCode = p.ItemCode
          and sr.SrNo = Srh.SrNo
          and srh.SrDate <= @startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph
            ,purchaseDetail as purd
          where purd.itemCode = p.itemCode
          and ph.PurchaseInvoiceCode = purd.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh
            ,PrDetail as prd
          where prd.itemCode = p.ItemCode
          and prh.PrNo = prd.PrNo
          and prh.prDate <= @startDate),0)
        +isnull((select sum(pd.Quantity) from DPRHeader as ph
            ,DPRDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.DPRCode = ph.DPRCode
          and ph.DPRDate <= @startdate),0),
        curr_date=pur_inv.PurchaseInvoiceDate,transaction_type='PU',
        doc_no=pur_inv.PurchaseInvoiceCode,
        tot_sale=0,
        tot_sal_amount=0,
        tot_dpr=0,
        tot_sr=0,
        tot_sr_Amount=0,
        tot_purchase=pur_inv.tot_pur_qty,
        tot_purchase_amount=pur_inv.tot_pur_amount,
        tot_pr=0,
        tot_pr_Amount=0
        from ItemInformation as p
          ,(select ph.PurchaseInvoiceDate,
            ph.PurchaseInvoiceCode,
            prd.ItemCode,
            tot_pur_qty=sum(prd.quantity),
            tot_pur_amount=sum(prd.Amount)
            from PurchaseHeader as ph,PurchaseDetail as prd
            where ph.PurchaseInvoiceCode = prd.PurchaseInvoiceCode
            group by ph.PurchaseInvoiceCode,ph.PurchaseInvoiceDate,prd.ItemCode) as pur_inv
        where p.ItemCode *= pur_inv.ItemCode
        and pur_inv.PurchaseInvoiceDate between @startdate and @enddate union all
      select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh
            ,SrDetail as sr
          where sr.itemCode = p.ItemCode
          and sr.SrNo = Srh.SrNo
          and srh.SrDate <= @startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph
            ,purchaseDetail as purd
          where purd.itemCode = p.itemCode
          and ph.PurchaseInvoiceCode = purd.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh
            ,PrDetail as prd
          where prd.itemCode = p.ItemCode
          and prh.PrNo = prd.PrNo
          and prh.prDate <= @startDate),0)
        +isnull((select sum(pd.Quantity) from DPRHeader as ph
            ,DPRDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.DPRCode = ph.DPRCode
          and ph.DPRDate <= @startdate),0),
        curr_date=pr.prDate,transaction_type='PR',
        doc_no=pr.prNo,
        tot_sale=0,
        tot_sal_amount=0,
        tot_dpr=0,
        tot_sr=0,
        tot_sr_Amount=0,
        tot_purchase=0,
        tot_purchase_amount=0,
        tot_pr=isnull(pr.tot_pr,0),
        tot_pr_Amount=isnull(pr.tot_pr_amount,0)
        from ItemInformation as p
          ,(select pr.prDate,
            pr.prNo,
            prd.ItemCode,
            tot_pr=sum(prd.quantity),
            tot_pr_amount=sum(prd.Amount)
            from prHeader as pr,prDetail as prd
            where pr.PrNo = Prd.PrNo
            group by Pr.PrNo,Pr.PrDate,Prd.ItemCode) as pr
        where p.ItemCode *= pr.ItemCode
        and Pr.PrDate between @startdate and @enddate) as res
    where pcode between @startcode and @endcode
    order by 1 asc,6 asc,7 asc,9 asc
end
