      opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh,
        SaleInvoiceDetail as s where
        s.ItemCode=p.ItemCode
        and s.SaleInvoiceCode=sh.SaleInvoiceCode
        and sh.InvoiceDate<=@startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh,
        SrDetail as sr where
        sr.itemCode=p.ItemCode
        and sr.SrNo=Srh.SrNo
        and srh.SrDate<=@startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph,
        purchaseDetail as purd where
        purd.itemCode=p.itemCode
        and ph.PurchaseInvoiceCode=purd.PurchaseInvoiceCode
        and ph.PurchaseInvoiceDate<=@startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh,
        PrDetail as prd where
        prd.itemCode=p.ItemCode
        and prh.PrNo=prd.PrNo
        and prh.prDate<=@startDate),0)
      +isnull((select sum(pd.Quantity) from DPRHeader as ph,
        DPRDetail as pd where
        pd.ItemCode=p.ItemCode
        and pd.DPRCode=ph.DPRCode
        and ph.DPRDate<=@startdate),0),
      curr_date=pur_inv.PurchaseInvoiceDate,transaction_type='PU',
      doc_no=pur_inv.PurchaseInvoiceCode,
      tot_sale=0,
      tot_sal_amount=0,
      tot_dpr=0,
      tot_sr=0,
      tot_sr_Amount=0,
      tot_purchase=pur_inv.tot_pur_qty,
      tot_purchase_amount=pur_inv.tot_pur_amount,
      tot_pr=0,
      tot_pr_Amount=0 from
      ItemInformation as p,
      (select ph.PurchaseInvoiceDate,
        ph.PurchaseInvoiceCode,
        prd.ItemCode,
        tot_pur_qty=sum(prd.quantity),
        tot_pur_amount=sum(prd.Amount) from
        PurchaseHeader as ph,PurchaseDetail as prd where
        ph.PurchaseInvoiceCode=prd.PurchaseInvoiceCode
        group by ph.PurchaseInvoiceCode,ph.PurchaseInvoiceDate,prd.ItemCode) as pur_inv where
      p.ItemCode*=pur_inv.ItemCode
      and pur_inv.PurchaseInvoiceDate between @startdate and @enddate union all
    select p.itemCode,p.ItemName,
      p.salerate,p.purchaserate,
      opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh,
        SaleInvoiceDetail as s where
        s.ItemCode=p.ItemCode
        and s.SaleInvoiceCode=sh.SaleInvoiceCode
        and sh.InvoiceDate<=@startdate),0)+isnull((select sum(sr.Quantity) from SrHeader as srh,
        SrDetail as sr where
        sr.itemCode=p.ItemCode
        and sr.SrNo=Srh.SrNo
        and srh.SrDate<=@startdate),0)+isnull((select sum(purd.quantity) from PurchaseHeader as ph,
        purchaseDetail as purd where
        purd.itemCode=p.itemCode
        and ph.PurchaseInvoiceCode=purd.PurchaseInvoiceCode
        and ph.PurchaseInvoiceDate<=@startDate),0)-isnull((select sum(prd.Quantity) from PrHeader as prh,
        PrDetail as prd where
        prd.itemCode=p.ItemCode
        and prh.PrNo=prd.PrNo
        and prh.prDate<=@startDate),0)
      +isnull((select sum(pd.Quantity) from DPRHeader as ph,
        DPRDetail as pd where
        pd.ItemCode=p.ItemCode
        and pd.DPRCode=ph.DPRCode
        and ph.DPRDate<=@startdate),0),
      curr_date=pr.prDate,transaction_type='PR',
      doc_no=pr.prNo,
      tot_sale=0,
      tot_sal_amount=0,
      tot_dpr=0,
      tot_sr=0,
      tot_sr_Amount=0,
      tot_purchase=0,
      tot_purchase_amount=0,
      tot_pr=isnull(pr.tot_pr,0),
      tot_pr_Amount=isnull(pr.tot_pr_amount,0) from
      ItemInformation as p,
      (select pr.prDate,
        pr.prNo,
        prd.ItemCode,
        tot_pr=sum(prd.quantity),
        tot_pr_amount=sum(prd.Amount) from
        prHeader as pr,prDetail as prd where
        pr.PrNo=Prd.PrNo
        group by Pr.PrNo,Pr.PrDate,Prd.ItemCode) as pr where
      p.ItemCode*=pr.ItemCode
      and Pr.PrDate between @startdate and @enddate) as res where
    pcode between @startcode and @endcode order by
    1 asc,6 asc,7 asc,9 asc
end
}
go

create procedure Saller.r_rmaterial_inventory_register( @startCode varchar(32),@endCode varchar(32),@startdate date,@endDate date ) 
as
begin
  select pcode=res.itemcode,
    pdesc=res.itemName,
    sl_rate=res.saleRate,
    pr_rate=res.purchaseRate,
    opening_stk=res.opn_stk,
    current_date=res.curr_date,
    transaction_type=res.transaction_type,
    document_no=res.doc_no,
    total_sale_qty=res.tot_sale,
    total_sale_amount=res.tot_sal_amount,
    total_purchase_qty=res.tot_pur,
    total_available=res.tot_pur-res.tot_sale
    from(select p.itemCode,p.ItemName,
        p.salerate,p.purchaserate,
        opn_stk=p.openingstock-isnull((select sum(pd.Quantity) from PurchaseHeader as ph
            ,PurchaseDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.PurchaseInvoiceCode = ph.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startdate),0)
        +isnull((select sum(MINd.Quantity) from consumptionNoteHeader as MINh
            ,consumptionNoteDetail as MINd
          where MINd.ItemCode = p.ItemCode
          and MINd.consnoteCode = MINh.consnotecode
          and MINh.consnoteDate <= @startdate),0),
        curr_date=pinv.consnoteDate,transaction_type='CON',
        doc_no=pinv.consnoteCode,
        tot_sale=0,
        tot_sal_amount=0,
        tot_pur=isnull(pinv.tot_pur,0)
        from ItemInformation as p
          ,(select pinvh.consnoteDate,
            pinvh.consnoteCode,
            pinvd.ItemCode,
            tot_pur=sum(quantity)
            from consumptionNoteHeader as pinvh
              ,consumptionNoteDetail as pinvd
            where pinvh.consnoteCode = pinvd.consnoteCode
            and pinvh.consnoteDate between @startdate and @enddate
            group by pinvh.consnoteCode,pinvh.consnoteDate,pinvd.ItemCode) as pinv
        where p.ItemCode = pinv.ItemCode
        and pinv.consnoteDate between @startdate and @enddate union all
      select p.ItemCode,p.ItemName,
        p.saleRate,p.purchaseRate,
        opn_stk=p.openingStock-isnull((select sum(pd.Quantity) from PurchaseHeader as ph
            ,PurchaseDetail as pd
          where pd.Itemcode = p.Itemcode
          and pd.PurchaseInvoiceCode = ph.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startdate),0)
        +isnull((select sum(MINd.quantity) from consumptionNoteHeader as MINh
            ,consumptionNoteDetail as MINd
          where MINd.ItemCode = p.ItemCode
          and MINd.consnoteCode = MINh.consnoteCode
          and MINh.consnoteDate <= @startdate),0),
        curr_date=pinv.PurchaseInvoiceDate,transaction_type='P',
        doc_no=pinv.PurchaseInvoiceCode,
        tot_sale=isnull(pinv.tot_sale,0),
        tot_sal_amount=isnull(pinv.tot_sal_amount,0),
        tot_pur=0
        from ItemInformation as p
          ,(select inv.purchaseinvoiceDate,
            inv.PurchaseInvoiceCode,
            invd.ItemCode,
            tot_sale=sum(invd.quantity),
            tot_sal_amount=sum(invd.Amount)
            from PurchaseHeader as inv,PurchaseDetail as invd
            where inv.PurchaseInvoiceCode = invd.PurchaseInvoiceCode
            group by inv.PurchaseInvoiceCode,inv.purchaseinvoiceDate,invd.ItemCode) as pinv
        where p.ItemCode *= pinv.ItemCode
        and pinv.PurchaseinvoiceDate between @startdate and @enddate) as res
    where pcode between @startcode and @endcode
    order by 1 asc,6 asc,7 asc,9 asc
end
go

