create procedure saller.account_search( @as_style varchar(2) ) 
/* RESULT ( accountcode,accountname,... ) */
as
begin
  --select all the account 
  if @as_style = '0'
    select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
      from chart
  else if @as_style = '1'
      select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
        from chart where active = '1'
    else --select all the active cash account   
      if @as_style = '2'
        select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
          from chart
          where accountcategory = 'C'
          and active = '1'
      else --select all the active Bank account  
        if @as_style = '3'
          select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
            from chart
            where accountcategory = 'B'
            and active = '1'
        else --select all the active customer account 
          if @as_style = '4'
            select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
              from chart
              where accountcategory = 'S'
              and active = '1'
          else --select all the active Vendor account 
            if @as_style = '5'
              select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                from chart
                where accountcategory = 'V'
                and active = '1'
            else --select all the active customer and vendor account 
              if @as_style = '6'
                select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                  from chart
                  where accountcategory between 'S' and 'V'
                  and active = '1'
              else --select all the active Inventory account 
                if @as_style = '7'
                  select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                    from chart
                    where accountcategory = 'I'
                    and active = '1'
                else --select all the active account without cash accounts
                  if @as_style = '8'
                    select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                      from chart
                      where accountcategory <> 'C'
                      and active = '1'
                  else --select all the active Inventory account 
                    if @as_style = '9'
                      select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                        from chart
                        where accountcategory not in( 'C','V' ) 
                        and active = '1'
                    else --select all the active Inventory account 
                      if @as_style = '10'
                        select code=accountcode,name=accountname,category=accountcategory,type=accounttype,city
                          from chart
                          where accountcategory in( 'P' ) 
                          and active = '1'
end
go

