create procedure saller.r_salestax_return( @startdate date,@enddate date ) as
begin
  select c.Name,c.address,c.city,c.saleTaxNo,sd.strate,str.regRate,
    str.unRegRate,str.retRate,str.otherRate,
    --Sales
    --sales tax amount and netamount if rate is registered
    rnetamount=(select isnull(sum(sh.netAmount),0)
      from SaleInvoiceHeader as sh
      where sd.strate = str.regRate and str.status = '1'),
    --sales tax amount if rate is registered
    rstAmount=(select isnull(sum(sh.saleTaxAmount),0)
      from SaleInvoiceHeader as sh
        ,SaleInvoiceDetail as sd
      where sd.strate = str.regRate and str.status = '1'),
    --sales tax amount and netamount if rate is unregistered
    urnetamount=(select isnull(sum(sh.netAmount),0)
      from SaleInvoiceHeader as sh
        ,SaleInvoiceDetail as sd
      where sd.strate = str.unRegRate and str.status = '1'),
    --sales tax amount if rate is unregistered
    urstAmount=(select isnull(sum(sh.saleTaxAmount),0)
      from SaleInvoiceHeader as sh
        ,SaleInvoiceDetail as sd
      where sd.strate = str.unRegRate and str.status = '1'),
    --Exempted sales 
    exemptsales=(select isnull(sum(sh.netamount),0)
      from SaleInvoiceHeader as sh
      where sh.saleTaxAmount = 0),
    --netamount if rate is registered
    rpnetamount=(select isnull(sum(ph.netAmount),0)
      from PurchaseHeader as ph
        ,PurchaseDetail as pd
      where pd.strate = str.regRate and str.status = '1'),
    --input tax amount if rate is registered
    rpstAmount=(select isnull(sum(ph.saleTaxAmount),0)
      from PurchaseHeader as ph
        ,PurchaseDetail as pd
      where pd.strate = str.regRate and str.status = '1'),
    --netamount if rate is unregistered
    urpnetamount=(select isnull(sum(sh.netAmount),0)
      from PurchaseHeader as ph
        ,PurchaseDetail as pd
      where pd.strate = str.unRegRate and str.status = '1'),
    --input tax amount if rate is unregistered
    urpstAmount=(select isnull(sum(ph.saleTaxAmount),0)
      from PurchaseHeader as ph
        ,PurchaseDetail as pd
      where pd.strate = str.unRegRate and str.status = '1'),
    --Exempted purchases
    exemptpurchases=(select isnull(sum(ph.netamount),0)
      from PurchaseHeader as ph
      where ph.saleTaxAmount = 0)
    from PurchaseHeader as ph
      ,PurchaseDetail as pd
      ,SaleInvoiceHeader as sh
      ,SaleInvoiceDetail as sd
      ,CompanyInformation as c
      ,SalesTaxRate as str
    where sh.invoiceDate between @startdate and @enddate
end
go

