create procedure saller.p_statement( @Date date,@Statement varchar(2) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @Date between startdate and enddate
  select t.GroupCode,GroupName=max(t.GroupName),Balance=abs(sum(t.OpeningBalance+t.CurrentBalance))
    /*Select all groups for statement. */
    /* Select the opening balances of groups, also include	 accounts which have no transactions at all.*/
    /*Select the current balances of groups as of given date*/
    from(select g.GroupCode,GroupName=max(g.GroupName),OpeningBalance=0,CurrentBalance=0
        from Groups as g
        where g.Type = 'S'
        and g.Statement = @Statement
        group by g.GroupCode union all
      select g.GroupCode,g.GroupName,
        OpeningBalance=sum(isNull(op.OpeningDr,0)-isnull(op.OpeningCr,0)),CurrentBalance=0
        from Groups as g,ChartGroup as cg,openingbalances as op
        where g.GroupCode = cg.GroupCode
        and op.AccountCode = cg.AccountCode
        and op.periodid = @periodid
        and g.Type = 'S'
        and g.Statement = @Statement
        group by g.GroupCode,g.GroupName union all
      select g.GroupCode,g.GroupName,
        OpeningBalance=0,CurrentBalance=sum(isnull(v.Debit,0)-isnull(v.Credit,0))
        from Groups as g,ChartGroup as cg,Chart as c,Voucher as v
        where g.GroupCode = cg.GroupCode
        and c.AccountCode = cg.AccountCode
        and c.AccountCode = v.AccountCode
        and cg.AccountCode = v.AccountCode
        and v.VoucherDate <= @Date
        and v.voucherDate between @startfiscaldate and @endfiscaldate
        and g.Type = 'S'
        and g.Statement = @Statement
        group by g.GroupCode,g.GroupName) as t
    group by t.GroupCode
    order by t.GroupCode asc
end
go

COMMENT ON PROCEDURE "saller"."p_statement" IS 
	'Calculates amouts for financial statements.'
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."p_statement" IS 
{create procedure saller.p_statement(@Date date,@Statement varchar(2))
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
    fiscalyears where @Date between startdate and enddate
  select t.GroupCode,GroupName=max(t.GroupName),Balance=abs(sum(t.OpeningBalance+t.CurrentBalance)) from(
    /*Select all groups for statement. */
    select g.GroupCode,GroupName=max(g.GroupName),OpeningBalance=0,CurrentBalance=0 from
      Groups as g where
      g.Type='S'
      and g.Statement=@Statement
      group by g.GroupCode union all
    /* Select the opening balances of groups, also include	 accounts which have no transactions at all.*/
    select g.GroupCode,g.GroupName,
      OpeningBalance=sum(isNull(op.OpeningDr,0)-isnull(op.OpeningCr,0)),CurrentBalance=0 from
      Groups as g,ChartGroup as cg,openingbalances as op where
      g.GroupCode=cg.GroupCode
      and op.AccountCode=cg.AccountCode
      and op.periodid=@periodid
      and g.Type='S'
      and g.Statement=@Statement
      group by g.GroupCode,g.GroupName union all
    /*Select the current balances of groups as of given date*/
    select g.GroupCode,g.GroupName,
      OpeningBalance=0,CurrentBalance=sum(isnull(v.Debit,0)-isnull(v.Credit,0)) from
      Groups as g,ChartGroup as cg,Chart as c,Voucher as v where
      g.GroupCode=cg.GroupCode
      and c.AccountCode=cg.AccountCode
      and c.AccountCode=v.AccountCode
      and cg.AccountCode=v.AccountCode
      and v.VoucherDate<=@Date
      and v.voucherDate between @startfiscaldate and @endfiscaldate
      and g.Type='S'
      and g.Statement=@Statement
      group by g.GroupCode,g.GroupName) as t
    group by t.GroupCode order by
    t.GroupCode asc
end
}
go

create procedure saller.ledger( @group_code varchar(32),@startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14),@style varchar(1) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  --select All Account.
  if @style = '0'
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,c.accountname,t.vouchertype,t.voucherdate,t.debit,t.credit,t.narration,t.voucherid,c.city,t.documentno,t.documentname
      from chart as c,voucher as t
      where c.accountcode = t.accountcode
      and t.accountcode between @startcode and @endcode
      and t.voucherdate between @startdate and @enddate
      order by t.accountcode asc,t.voucherdate asc
  --Select Selected Accounts.
  if @style = '1'
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,c.accountname,t.vouchertype,t.voucherdate,t.debit,t.credit,t.narration,t.voucherid,c.city,t.documentno,t.documentname
      from chart as c,voucher as t
      where c.accountcode = t.accountcode
      and t.voucherdate between @startdate and @enddate
      and c.accountcode = any(select accountcode from chartgroup where groupcode = @group_code)
      order by t.accountcode asc,t.voucherdate asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."ledger" IS 
{create PROCEDURE saller."ledger"(@group_code varchar(32),@startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14),@style varchar(1))
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
    fiscalyears where @startdate between startdate and enddate
  --select All Account.
  if @style='0'
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,c.accountname,t.vouchertype,t.voucherdate,t.debit,t.credit,t.narration,t.voucherid,c.city,t.documentno,t.documentname from
      chart as c,voucher as t where
      c.accountcode=t.accountcode
      and t.accountcode between @startcode and @endcode
      and t.voucherdate between @startdate and @enddate order by
      t.accountcode asc,t.voucherdate asc
  --Select Selected Accounts.
  if @style='1'
   select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,c.accountname,t.vouchertype,t.voucherdate,t.debit,t.credit,t.narration,t.voucherid,c.city,t.documentno,t.documentname from
      chart as c,voucher as t where
      c.accountcode=t.accountcode
      and t.voucherdate between @startdate and @enddate
      and c.accountcode=any(select accountcode from chartgroup where groupcode=@group_code) order by
      t.accountcode asc,t.voucherdate asc
end
}
