create procedure Saller.r_general_journal( @style varchar(1),@startcode varchar(10),@endcode varchar(10),@startdate date,@enddate date,@voucherType varchar(4) ) 
as
begin
  if @style = '1'
    select v.vouchertype,v.voucherid,v.voucherdate,v.accountcode,c.accountname,v.narration,v.credit,v.debit from voucher as v,chart as c
      where v.accountcode = c.accountcode
      and v.vouchertype = @vouchertype
      and v.voucherid between @startcode and @endcode
      and v.voucherdate >= @startdate
      and v.voucherdate <= @enddate
      order by 1 asc,2 asc,3 asc,8 asc
  if @style = '2'
    select v.vouchertype,v.voucherid,v.voucherdate,v.accountcode,c.accountname,v.narration,v.credit,v.debit from voucher as v,chart as c
      where v.accountcode = c.accountcode
      and v.vouchertype = 'JVR'
      and v.voucherdate >= @startdate
      and v.voucherdate <= @enddate
      order by 1 asc,2 asc,3 asc,8 asc
end
go

