create procedure saller.r_cashbook_report( @startdate date,@enddate date ) 
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date,@cashaccount varchar(10)
  select @cashaccount = cashaccount from productcontrol
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  select openingbal=(select isnull(op.openingdr,0)-isnull(op.openingcr,0)
      from openingbalances as op where op.accountcode = @cashaccount and op.periodid = @PeriodID)
    +(select isnull(sum(t.debit),0)-isnull(sum(t.credit),0) from voucher as t
      where t.voucherdate < @startdate
      and t.accountcode = @cashaccount and t.voucherdate between @startfiscaldate and @endfiscaldate), /*c.accountcode=t.accountcode and*/
    tr.voucherid,
    tr.voucherdate,
    tr.narration,
    tr.accountcode,
    c.accountname,
    c.city,
    tr.debit,
    tr.credit
    from chart as c,voucher as tr
    where c.accountcode = tr.accountcode
    and tr.vouchertype between 'CPV' and 'CRV'
    and tr.voucherdate between @startdate and @enddate
    and c.accountcode <> @cashaccount
    order by tr.voucherdate asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_cashbook_report" IS 
{create PROCEDURE saller."r_cashbook_report"(@startdate date,@enddate date)
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date,@cashaccount varchar(10)
  select @cashaccount = cashaccount from productcontrol
  select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
    fiscalyears where @startdate between startdate and enddate
  select openingbal=(select isnull(op.openingdr,0)-isnull(op.openingcr,0) from
      openingbalances as op where op.accountcode=@cashaccount and op.periodid=@PeriodID)
    +(select isnull(sum(t.debit),0)-isnull(sum(t.credit),0) from voucher as t where
      t.voucherdate<@startdate
      and t.accountcode=@cashaccount and t.voucherdate between @startfiscaldate and @endfiscaldate), /*c.accountcode=t.accountcode and*/
    tr.voucherid,
    tr.voucherdate,
    tr.narration,
    tr.accountcode,
    c.accountname,
    c.city,
    tr.debit,
    tr.credit from
    chart as c,voucher as tr where
    c.accountcode=tr.accountcode
    and tr.vouchertype between 'CPV' and 'CRV'
    and tr.voucherdate between @startdate and @enddate
    and c.accountcode<>@cashaccount order by
    tr.voucherdate asc
end
}
