create procedure Saller.opening_balance( @startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  --Calculate the Opening Balances
  begin
    select openingbalnce=(select isnull(max(op.openingdr),0)-isnull(max(op.openingcr),0)
        from openingbalances where openingbalances.accountcode = op.accountcode and op.periodid = @periodid)
      +isnull((select isnull(sum(tr.debit),0)-isnull(sum(tr.credit),0)
        from voucher as tr
        where op.accountcode = c.accountcode
        and op.periodid = @periodid
        and tr.accountcode = c.accountcode
        and tr.voucherdate < @startdate and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by c.accountcode),0),
      c.accountcode,c.accountname,t.voucherdate,t.debit,t.credit,t.narration,t.voucherid
      from openingbalances as op,chart as c,voucher as t
      where op.accountcode = c.accountcode
      and op.periodid = @periodid
      and c.accountcode *= t.accountcode
      and c.accountcode >= @startcode
      and c.accountcode <= @endcode
      and t.voucherdate >= @startdate
      and t.voucherdate <= @enddate
      order by c.accountcode asc
  end
end
