create procedure saller.r_recovery_summary( @startcode varchar(14),@endcode varchar(14),@startdate date,@enddate date ) 
as
begin
  select t.accountcode,AName=(select c.accountname from chart as c where t.accountcode = c.accountcode),
    amount=sum(t.credit)
    from voucher as t,chart as c
    where t.accountcode = c.accountcode
    and c.accountcategory = 'S'
    /*   and t.documentname='JR'*/
    and status = '1'
    and t.accountcode between @startcode and @endcode
    and t.voucherdate between @startdate and @enddate
    group by t.accountcode,aname order by t.accountcode asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_recovery_summary" IS 
{create procedure saller.r_recovery_summary(@startcode varchar(14),@endcode varchar(14),@startdate date,@enddate date)
as
begin
  select t.accountcode,AName=(select c.accountname from chart as c where t.accountcode=c.accountcode),
    amount=sum(t.credit) from
    voucher as t,chart as c where
    t.accountcode=c.accountcode
    and c.accountcategory='S'
    /*   and t.documentname='JR'*/
    and status='1'
    and t.accountcode between @startcode and @endcode
    and t.voucherdate between @startdate and @enddate
    group by t.accountcode,aname order by t.accountcode asc
end
}
go

create procedure Saller.ledger_shedule( @startdate date,@enddate date,@accountcode varchar(14) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  --select All Account. 
  select c.accountcode,
    bal_15=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v
      where v.accountcode = c.accountcode
      and v.voucherdate >= days(@enddate,-15) and v.voucherdate <= @enddate group by v.accountcode),
    bal_30=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v
      where v.accountcode = c.accountcode
      and v.voucherdate >= days(@enddate,-30) and v.voucherdate < days(@enddate,-15) group by v.accountcode),
    bal_45=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v
      where v.accountcode = c.accountcode
      and v.voucherdate >= days(@enddate,-45) and v.voucherdate < days(@enddate,-30) group by v.accountcode),
    bal_60=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v
      where v.accountcode = c.accountcode
      and v.voucherdate >= days(@enddate,-60) and v.voucherdate < days(@enddate,-45) group by v.accountcode),
    bal_90=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v
      where v.accountcode = c.accountcode
      and v.voucherdate >= days(@enddate,-90) and v.voucherdate < days(@enddate,-60) group by v.accountcode),
    /*bal_180=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v where
v.accountcode=c.accountcode
and v.voucherdate>=days(@enddate,-180) and v.voucherdate<days(@enddate,-90) group by v.accountcode),
bal_270=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v where
v.accountcode=c.accountcode
and v.voucherdate>=days(@enddate,-270) and v.voucherdate<days(@enddate,-180) group by v.accountcode),
bal_365=(select sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from voucher as v where
v.accountcode=c.accountcode
and v.voucherdate>=days(@enddate,-365) and v.voucherdate<days(@enddate,-270) group by v.accountcode),*/
    closingbalance=(select isnull(max(op.openingdr),0) from openingbalances as op
      where op.accountcode = c.accountcode and op.periodid = @periodid)
    -(select isnull(max(op.openingcr),0) from openingbalances as op
      where op.accountcode = c.accountcode and op.periodid = @periodid)
    +isnull((select sum(tr.debit) from voucher as tr
      where tr.accountcode = c.accountcode
      and tr.voucherdate < @startdate group by tr.accountcode),0)
    -isnull((select sum(tr.credit) from voucher as tr
      where tr.accountcode = c.accountcode
      and tr.doc < @startdate and tr.doc between @startfiscaldate and @endfiscaldate
      group by tr.accountcode),0)
    +(select sum(t.debit)-sum(t.credit)
      from voucher as t
      where c.accountcode = t.accountcode
      and t.voucherdate >= @startdate
      and t.voucherdate <= @enddate group by t.accountcode),
    above_days=(isnull(closingbalance,0)-isnull(bal_15,0)-isnull(bal_30,0)-isnull(bal_45,0)-isnull(bal_90,0))
    from chart as c
    where c.accountcode = @accountcode
/*if @style='0'
select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
op.accountcode=t.accountcode and op.periodid=@periodid)
-(select isnull(max(op.openingcr),0) from openingbalances as op where
op.accountcode=t.accountcode and op.periodid=@periodid)
+isnull((select sum(tr.debit) from voucher as tr where
tr.accountcode=t.accountcode
and tr.voucherdate<@startdate group by tr.accountcode),0)
-isnull((select sum(tr.credit) from voucher as tr where
tr.accountcode=t.accountcode
and tr.doc<@startdate and tr.doc between @startfiscaldate and @endfiscaldate
group by tr.accountcode),0)
+sum(t.debit)-sum(t.credit) from
chart as c,voucher as t where
c.accountcode=t.accountcode
and t.accountcode>=@startcode
and t.accountcode<=@endcode
and t.voucherdate>=@startdate
and t.voucherdate<=@enddate group by t.accountcode order by
t.accountcode asc
-- select the data for 15 days
select date_15=sum(t.debit)-sum(t.credit) from
chart as c,voucher as t where
c.accountcode=t.accountcode
and t.accountcode>=@startcode
and t.accountcode<=@endcode
and t.voucherdate>=DAYS(@enddate,-15)
and t.voucherdate<=@enddate group by t.accountcode order by
t.accountcode asc
-- select the data for 30 days
select date_30=sum(t.debit)-sum(t.credit) from
chart as c,voucher as t where
c.accountcode=t.accountcode
and t.accountcode>=@startcode
and t.accountcode<=@endcode
and t.voucherdate>=DAYS("date"(@enddate),-30)
