      op.accountcode=c.accountcode and op.periodid=@periodid)
    -(select isnull(max(op.openingcr),0) from openingbalances as op where
      op.accountcode=c.accountcode and op.periodid=@periodid)
    +isnull((select sum(tr.debit) from voucher as tr where
      tr.accountcode=c.accountcode
      and tr.voucherdate<@startdate group by tr.accountcode),0)
    -isnull((select sum(tr.credit) from voucher as tr where
      tr.accountcode=c.accountcode
      and tr.doc<@startdate and tr.doc between @startfiscaldate and @endfiscaldate
      group by tr.accountcode),0)
    +(select sum(t.debit)-sum(t.credit) from
      voucher as t where
      c.accountcode=t.accountcode
      and t.voucherdate>=@startdate
      and t.voucherdate<=@enddate group by t.accountcode),
    above_days=(isnull(closingbalance,0)-isnull(bal_15,0)-isnull(bal_30,0)-isnull(bal_45,0)-isnull(bal_90,0)) from
    chart as c where
    c.accountcode=@accountcode
