create procedure Saller.r_outer_inventory_register( @startdate date,@endDate date,@startCode varchar(32),@endCode varchar(32) ) 
as
begin
  select pcode=res.itemcode,
    pdesc=res.itemName,
    opening_stk=res.opn_stk,
    current_date=res.curr_date,
    transaction_type=res.transaction_type,
    document_no=res.doc_no,
    total_sale_qty=res.tot_sale,
    total_purchase_qty=res.tot_pur,
    total_available=res.tot_pur-res.tot_sale
    /*and pinv.purchasetype<>2*/
    from(select p.itemCode,p.ItemName,
        opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh
            ,SaleInvoiceDetail as s
          where s.ItemCode = p.ItemCode
          and s.SaleInvoiceCode = sh.SaleInvoiceCode
          and sh.InvoiceDate <= @startdate and sh.salestype = 2),0)
        +isnull((select sum(pd.Quantity) from PurchaseHeader as ph
            ,PurchaseDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.PurchaseInvoiceCode = ph.PurchaseInvoiceCode
          and ph.PurchaseInvoiceDate <= @startdate and ph.purchasetype = 2),0),
        curr_date=pinv.purchaseInvoiceDate,transaction_type='P',
        doc_no=pinv.purchaseInvoiceCode,
        tot_sale=0,
        tot_pur=isnull(pinv.tot_pur,0)
        from ItemInformation as p
          ,(select pinvh.PurchaseInvoiceDate,
            pinvh.PurchaseInvoiceCode,
            pinvd.ItemCode,
            tot_pur=sum(quantity)
            from purchaseHeader as pinvh
              ,purchaseDetail as pinvd
            where pinvh.purchaseInvoiceCode = pinvd.purchaseInvoiceCode
            and pinvh.purchaseInvoiceDate >= @startdate
            and pinvh.purchaseInvoiceDate <= @enddate and pinvh.purchasetype = 2
            group by pinvh.purchaseInvoiceCode,pinvh.purchaseInvoiceDate,pinvd.ItemCode) as pinv
        where p.ItemCode = pinv.ItemCode
        and pinv.purchaseInvoiceDate between @startdate and @enddate union all
      select p.ItemCode,p.ItemName,
        opn_stk=p.openingStock-isnull((select sum(s.Quantity) from saleInvoiceHeader as sh
            ,saleInvoiceDetail as s
          where s.Itemcode = p.Itemcode
          and s.saleInvoiceCode = sh.saleInvoiceCode
          and sh.invoiceDate <= @startdate and sh.salestype = 2),0)
        +isnull((select sum(pd.quantity) from purchaseHeader as ph
            ,purchaseDetail as pd
          where pd.ItemCode = p.ItemCode
          and pd.purchaseInvoiceCode = ph.purchaseInvoiceCode
          and ph.purchaseInvoiceDate <= @startdate and ph.purchasetype = 2),0),
        curr_date=sinv.invoiceDate,transaction_type='S',
        doc_no=sinv.saleInvoiceCode,
        tot_sale=isnull(sinv.tot_sale,0),
        tot_pur=0
        from ItemInformation as p
          ,(select inv.invoiceDate,
            inv.saleInvoiceCode,
            invd.ItemCode,
            tot_sale=sum(invd.quantity)
            from saleInvoiceHeader as inv,saleInvoiceDetail as invd
            where inv.saleInvoiceCode = invd.saleInvoiceCode and inv.salestype = 2
            group by inv.saleInvoiceCode,inv.invoiceDate,invd.ItemCode) as sinv
        where p.ItemCode *= sinv.ItemCode
        and sinv.invoiceDate between @startdate and @enddate) as res
    /*and sinv.salestype<>2*/
    where pcode between @startcode and @endcode
    order by 1 asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_outer_inventory_register" IS 
{create procedure Saller.r_outer_inventory_register(@startdate date,@endDate date,@startCode varchar(32),@endCode varchar(32))
as
begin
  select pcode=res.itemcode,
    pdesc=res.itemName,
    opening_stk=res.opn_stk,
    current_date=res.curr_date,
    transaction_type=res.transaction_type,
    document_no=res.doc_no,
    total_sale_qty=res.tot_sale,
    total_purchase_qty=res.tot_pur,
    total_available=res.tot_pur-res.tot_sale from(
    select p.itemCode,p.ItemName,
      opn_stk=p.openingstock-isnull((select sum(s.Quantity) from SaleInvoiceHeader as sh,
        SaleInvoiceDetail as s where
        s.ItemCode=p.ItemCode
        and s.SaleInvoiceCode=sh.SaleInvoiceCode
        and sh.InvoiceDate<=@startdate and sh.salestype=2),0)
      +isnull((select sum(pd.Quantity) from PurchaseHeader as ph,
        PurchaseDetail as pd where
        pd.ItemCode=p.ItemCode
        and pd.PurchaseInvoiceCode=ph.PurchaseInvoiceCode
        and ph.PurchaseInvoiceDate<=@startdate and ph.purchasetype=2),0),
      curr_date=pinv.purchaseInvoiceDate,transaction_type='P',
      doc_no=pinv.purchaseInvoiceCode,
      tot_sale=0,
      tot_pur=isnull(pinv.tot_pur,0) from
      ItemInformation as p,
      (select pinvh.PurchaseInvoiceDate,
        pinvh.PurchaseInvoiceCode,
        pinvd.ItemCode,
        tot_pur=sum(quantity) from
        purchaseHeader as pinvh,
        purchaseDetail as pinvd where
        pinvh.purchaseInvoiceCode=pinvd.purchaseInvoiceCode
        and pinvh.purchaseInvoiceDate>=@startdate
        and pinvh.purchaseInvoiceDate<=@enddate and pinvh.purchasetype=2
        group by pinvh.purchaseInvoiceCode,pinvh.purchaseInvoiceDate,pinvd.ItemCode) as pinv where
      p.ItemCode=pinv.ItemCode
      and pinv.purchaseInvoiceDate between @startdate and @enddate union all /*and pinv.purchasetype<>2*/
    select p.ItemCode,p.ItemName,
      opn_stk=p.openingStock-isnull((select sum(s.Quantity) from saleInvoiceHeader as sh,
        saleInvoiceDetail as s where
        s.Itemcode=p.Itemcode
        and s.saleInvoiceCode=sh.saleInvoiceCode
        and sh.invoiceDate<=@startdate and sh.salestype=2),0)
      +isnull((select sum(pd.quantity) from purchaseHeader as ph,
        purchaseDetail as pd where
        pd.ItemCode=p.ItemCode
        and pd.purchaseInvoiceCode=ph.purchaseInvoiceCode
        and ph.purchaseInvoiceDate<=@startdate and ph.purchasetype=2),0),
      curr_date=sinv.invoiceDate,transaction_type='S',
      doc_no=sinv.saleInvoiceCode,
      tot_sale=isnull(sinv.tot_sale,0),
      tot_pur=0 from
      ItemInformation as p,
      (select inv.invoiceDate,
        inv.saleInvoiceCode,
        invd.ItemCode,
        tot_sale=sum(invd.quantity) from
        saleInvoiceHeader as inv,saleInvoiceDetail as invd where
        inv.saleInvoiceCode=invd.saleInvoiceCode and inv.salestype=2
        group by inv.saleInvoiceCode,inv.invoiceDate,invd.ItemCode) as sinv where
      p.ItemCode*=sinv.ItemCode
      and sinv.invoiceDate between @startdate and @enddate) as res where
    /*and sinv.salestype<>2*/
    pcode between @startcode and @endcode order by
    1 asc
end
}
