create procedure saller.r_bankbook( @startdate date,@enddate date,@accountcode varchar(10) ) 
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  begin
    select openingbal=(select isnull(op.openingdr,0)-isnull(op.openingcr,0)
        from openingbalances as op where op.accountcode = @accountcode and op.periodid = @periodid)
      +(select isnull(sum(t.credit),0)-isnull(sum(t.debit),0)
        from voucher as t
        where t.accountcode = @accountcode
        /*For getting Opening Balance Date*/
        and t.voucherdate < @startdate
        and t.voucherdate between @startfiscaldate and @endfiscaldate), /*c.accountcode=t.accountcode and*/
      tr.voucherid,
      tr.voucherdate,
      tr.narration,
      tr.accountcode,
      tr.accountcode2,
      c.accountname,
      tr.debit,
      tr.credit,
      accountname=(select c.accountname from chart as c where c.accountcode = tr.accountcode2)
      from openingbalances as op,chart as c,voucher as tr
      where op.accountcode = c.accountcode
      and op.periodid = @periodid
      and c.accountcode = tr.accountcode
      --      and tr.vouchertype in('BPV','BRV')
      and tr.voucherdate between @startdate and @enddate
      --    and tr.accountcode2=c.accountcode
      and c.accountcode = @accountcode
      order by tr.voucherdate asc
  end
end
