create procedure Saller.r_closing_stock( @type varchar(1),@startcode varchar(64),@endcode varchar(64),@startdate date,@enddate date ) 
as
begin
  select p.itemcode,p.itemname,p.batch,
    packingsize=(select i.packingsize from iteminformation as i where i.itemcode = p.itemcode),
    --opening quantity
    openingstock-isnull(ops.op_sale_qty,0)+isnull(opp.op_purchase_qty,0)
    +isnull(osr.op_salereturn_qty,0)-isnull(opr.op_purchasereturn_qty,0)
    -isnull(opi.op_issue_qty,0)+isnull(opd.op_dpr_qty,0)+isnull(oadj.op_adjusted_qty,0)-isnull(opmi.op_m_issue_qty,0),
    --     Total Sale
    total_sale_qty=isnull(sl.tot_sale_qty,0),
    --    TOtal Purchase
    total_purchase_qty=isnull(pur.tot_purchase_qty,0),
    --    TOtal DPR
    total_dpr_qty=isnull(dpr.tot_dpr_qty,0),
    --    TOtal Issue
    total_issue_qty=isnull(isr.tot_issue_qty,0),
    --TOtal Sale return
    total_salereturn_qty=isnull(srl.tot_salereturn_qty,0),
    --Total Purchase return
    total_purchasereturn_qty=isnull(prl.tot_purchasereturn_qty,0),
    --Total Adjustment
    total_adjusted_qty=isnull(adj.totadjusted_qty,0),
    total_m_issue_qty=isnull(min.tot_m_issue_qty,0)
    from iteminformation as p
      --opening sale
      ,(select id.itemcode,op_sale_qty=isnull(sum(id.quantity),0)
        from saleinvoicedetail as id,saleinvoiceheader as ih where ih.saleinvoicecode = id.saleinvoicecode
        and invoicedate < @startdate and ih.status = 1 group by id.itemCode) as ops
      --opening purchase
      ,(select pd.itemCode,op_purchase_qty=sum(pd.quantity)
        from purchasedetail as pd,purchaseheader as ph where pd.purchaseinvoicecode = ph.purchaseinvoicecode
        and purchaseinvoicedate < @startdate group by pd.itemCode) as opp
      --opening material issue 
      ,(select mid.itemCode,op_m_issue_qty=sum(mid.quantity)
        from materissuenotedetail as mid,materialissuenoteheader as mih where mid.mincode = mih.mincode
        and mindate < @startdate group by mid.itemCode) as opmi
      --opening dpr
      ,(select dpd.itemCode,op_dpr_qty=isnull(sum(dpd.quantity),0)
        from dprdetail as dpd,dprheader as dph where dpd.dprcode = dph.dprcode
        and dprdate < @startdate group by dpd.itemCode) as opd
      --opening Consumed
      ,(select isd.itemCode,op_issue_qty=isnull(sum(isd.quantity),0)
        from consumptionnotedetail as isd,consumptionnoteheader as ish where isd.consnotecode = ish.consnotecode
        and consnotedate < @startdate group by isd.itemCode) as opi
      --opening sale return
      ,(select id.itemcode,op_salereturn_qty=isnull(sum(id.quantity),0)
        from srdetail as id,srheader as ih where ih.srno = id.srno
        and srdate < @startdate group by id.itemCode) as osr
      --opening purchase return
      ,(select pd.itemCode,op_purchasereturn_qty=isnull(sum(pd.quantity),0)
        from prdetail as pd,prheader as ph where pd.prno = ph.prno
        and prdate < @startdate group by pd.itemCode) as opr
      --opening adjustment
      ,(select ad.itemcode,op_adjusted_qty=isnull(sum(ad.quantity),0)
        from saDetail as ad,saHeader as ah where ad.sacode = ah.sacode
        and sadate < @startdate group by ad.itemcode) as oadj
      -- Sale Quantity 
      ,(select id.itemcode,tot_sale_qty=isnull(sum(id.quantity),0)
        from saleinvoicedetail as id,saleinvoiceheader as ih where ih.saleinvoicecode = id.saleinvoicecode
        and invoicedate between @startdate and @enddate group by id.itemCode) as sl
      --  Purchase Quantity
      ,(select pd.itemcode,tot_purchase_qty=sum(pd.quantity)
        from purchasedetail as pd,purchaseheader as ph where pd.purchaseinvoicecode = ph.purchaseinvoicecode
        and purchaseinvoicedate between @startdate and @enddate group by pd.itemCode) as pur
      --  Material Issue Quantity
      ,(select mid.itemcode,tot_m_issue_qty=sum(mid.quantity)
        from materissuenotedetail as mid,materialissuenoteheader as mih where mid.mincode = mih.mincode
        and mindate between @startdate and @enddate group by mid.itemCode) as min
      --  Consumed Quantity 
      ,(select isd.itemcode,tot_issue_qty=sum(isd.quantity)
        from Consumptionnotedetail as isd,consumptionnoteheader as ish where isd.consnotecode = ish.consnotecode
        and consnotedate between @startdate and @enddate group by isd.itemCode) as isr
      --  Dpr Quantity 
      ,(select dpd.itemcode,tot_dpr_qty=isnull(sum(dpd.quantity),0)
        from dprdetail as dpd,dprheader as dph where dpd.dprcode = dph.dprcode
        and dprdate between @startdate and @enddate group by dpd.itemCode) as dpr
      -- Sale Return Quantity 
      ,(select id.itemcode,tot_salereturn_qty=isnull(sum(id.quantity),0)
        from srdetail as id,srheader as ih where ih.srno = id.srno
        and srdate between @startdate and @enddate group by id.itemCode) as srl
      --  Purchase Return Quantity 
      ,(select pd.itemcode,tot_purchasereturn_qty=sum(pd.quantity)
        from prdetail as pd,prheader as ph where pd.prno = ph.prno
        and prdate between @startdate and @enddate group by pd.itemCode) as prl
      --Adjusted Quantity
      ,(select ad.itemcode,totadjusted_qty=sum(ad.quantity)
        from sadetail as ad,saheader as ah where ad.sacode = ah.sacode
        and sadate between @startdate and @enddate group by ad.itemcode) as adj
    where p.itemCode *= ops.itemCode
    and p.itemCode *= opp.itemCode
    and p.itemCode *= opmi.itemCode
    and p.itemcode *= osr.itemcode
    and p.itemcode *= opr.itemcode
    and p.itemcode *= opi.itemcode
    and p.itemcode *= opd.itemcode
    and p.itemcode *= oadj.itemcode
    and p.itemCode *= sl.itemCode
    and p.itemCode *= pur.itemCode
    and p.itemCode *= min.itemCode
    and p.itemcode *= srl.itemcode
    and p.itemcode *= prl.itemcode
    and p.itemcode *= isr.itemcode
    and p.itemcode *= dpr.itemcode
    and p.itemcode *= adj.itemcode
    --and p.itemtype=@type
    and p.itemcode between @startcode and @endcode
    order by 1 asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_closing_stock" IS 
{create procedure Saller.r_closing_stock(@type varchar(1),@startcode varchar(64),@endcode varchar(64),@startdate date,@enddate date)
as
begin
  select p.itemcode,p.itemname,p.batch,
    packingsize=(select i.packingsize from iteminformation as i where i.itemcode=p.itemcode),
    --opening quantity
    openingstock-isnull(ops.op_sale_qty,0)+isnull(opp.op_purchase_qty,0)
    +isnull(osr.op_salereturn_qty,0)-isnull(opr.op_purchasereturn_qty,0)
    -isnull(opi.op_issue_qty,0)+isnull(opd.op_dpr_qty,0)+isnull(oadj.op_adjusted_qty,0)-isnull(opmi.op_m_issue_qty,0),
    --     Total Sale
    total_sale_qty=isnull(sl.tot_sale_qty,0),
    --    TOtal Purchase
    total_purchase_qty=isnull(pur.tot_purchase_qty,0),
    --    TOtal DPR
    total_dpr_qty=isnull(dpr.tot_dpr_qty,0),
    --    TOtal Issue
    total_issue_qty=isnull(isr.tot_issue_qty,0),
    --TOtal Sale return
    total_salereturn_qty=isnull(srl.tot_salereturn_qty,0),
    --Total Purchase return
    total_purchasereturn_qty=isnull(prl.tot_purchasereturn_qty,0),
    --Total Adjustment
    total_adjusted_qty=isnull(adj.totadjusted_qty,0),
    total_m_issue_qty=isnull(min.tot_m_issue_qty,0) from
    iteminformation as p,
    --opening sale
    (select id.itemcode,op_sale_qty=isnull(sum(id.quantity),0) from
      saleinvoicedetail as id,saleinvoiceheader as ih where ih.saleinvoicecode=id.saleinvoicecode
      and invoicedate<@startdate and ih.status=1 group by id.itemCode) as ops,
    --opening purchase
    (select pd.itemCode,op_purchase_qty=sum(pd.quantity) from
      purchasedetail as pd,purchaseheader as ph where pd.purchaseinvoicecode=ph.purchaseinvoicecode
      and purchaseinvoicedate<@startdate group by pd.itemCode) as opp,
    --opening material issue 
    (select mid.itemCode,op_m_issue_qty=sum(mid.quantity) from
      materissuenotedetail as mid,materialissuenoteheader as mih where mid.mincode=mih.mincode
      and mindate<@startdate group by mid.itemCode) as opmi,
    --opening dpr
    (select dpd.itemCode,op_dpr_qty=isnull(sum(dpd.quantity),0) from
      dprdetail as dpd,dprheader as dph where dpd.dprcode=dph.dprcode
      and dprdate<@startdate group by dpd.itemCode) as opd,
    --opening Consumed
    (select isd.itemCode,op_issue_qty=isnull(sum(isd.quantity),0) from
      consumptionnotedetail as isd,consumptionnoteheader as ish where isd.consnotecode=ish.consnotecode
      and consnotedate<@startdate group by isd.itemCode) as opi,
    --opening sale return
    (select id.itemcode,op_salereturn_qty=isnull(sum(id.quantity),0) from
      srdetail as id,srheader as ih where ih.srno=id.srno
      and srdate<@startdate group by id.itemCode) as osr,
    --opening purchase return
    (select pd.itemCode,op_purchasereturn_qty=isnull(sum(pd.quantity),0) from
      prdetail as pd,prheader as ph where pd.prno=ph.prno
      and prdate<@startdate group by pd.itemCode) as opr,
    --opening adjustment
    (select ad.itemcode,op_adjusted_qty=isnull(sum(ad.quantity),0) from
      saDetail as ad,saHeader as ah where ad.sacode=ah.sacode
      and sadate<@startdate group by ad.itemcode) as oadj,
    -- Sale Quantity 
    (select id.itemcode,tot_sale_qty=isnull(sum(id.quantity),0) from
      saleinvoicedetail as id,saleinvoiceheader as ih where ih.saleinvoicecode=id.saleinvoicecode
      and invoicedate between @startdate and @enddate group by id.itemCode) as sl,
    --  Purchase Quantity
    (select pd.itemcode,tot_purchase_qty=sum(pd.quantity) from
      purchasedetail as pd,purchaseheader as ph where pd.purchaseinvoicecode=ph.purchaseinvoicecode
      and purchaseinvoicedate between @startdate and @enddate group by pd.itemCode) as pur,
    --  Material Issue Quantity
    (select mid.itemcode,tot_m_issue_qty=sum(mid.quantity) from
      materissuenotedetail as mid,materialissuenoteheader as mih where mid.mincode=mih.mincode
      and mindate between @startdate and @enddate group by mid.itemCode) as min,
    --  Consumed Quantity 
    (select isd.itemcode,tot_issue_qty=sum(isd.quantity) from
      Consumptionnotedetail as isd,consumptionnoteheader as ish where isd.consnotecode=ish.consnotecode
      and consnotedate between @startdate and @enddate group by isd.itemCode) as isr,
    --  Dpr Quantity 
    (select dpd.itemcode,tot_dpr_qty=isnull(sum(dpd.quantity),0) from
      dprdetail as dpd,dprheader as dph where dpd.dprcode=dph.dprcode
      and dprdate between @startdate and @enddate group by dpd.itemCode) as dpr,
    -- Sale Return Quantity 
    (select id.itemcode,tot_salereturn_qty=isnull(sum(id.quantity),0) from
      srdetail as id,srheader as ih where ih.srno=id.srno
      and srdate between @startdate and @enddate group by id.itemCode) as srl,
    --  Purchase Return Quantity 
    (select pd.itemcode,tot_purchasereturn_qty=sum(pd.quantity) from
      prdetail as pd,prheader as ph where pd.prno=ph.prno
      and prdate between @startdate and @enddate group by pd.itemCode) as prl,
    --Adjusted Quantity
    (select ad.itemcode,totadjusted_qty=sum(ad.quantity) from
      sadetail as ad,saheader as ah where ad.sacode=ah.sacode
      and sadate between @startdate and @enddate group by ad.itemcode) as adj where
    p.itemCode*=ops.itemCode
    and p.itemCode*=opp.itemCode
    and p.itemCode*=opmi.itemCode
    and p.itemcode*=osr.itemcode
    and p.itemcode*=opr.itemcode
    and p.itemcode*=opi.itemcode
    and p.itemcode*=opd.itemcode
    and p.itemcode*=oadj.itemcode
    and p.itemCode*=sl.itemCode
    and p.itemCode*=pur.itemCode
    and p.itemCode*=min.itemCode
    and p.itemcode*=srl.itemcode
    and p.itemcode*=prl.itemcode
    and p.itemcode*=isr.itemcode
    and p.itemcode*=dpr.itemcode
    and p.itemcode*=adj.itemcode
    --and p.itemtype=@type
    and p.itemcode between @startcode and @endcode order by
    1 asc
end
}
go

create procedure Saller.r_sales_journal( @status char(1),@startdate date,@enddate date ) 
begin
  if @status = '0' then --- All sales posted and unposted. 
    select s.salesType,s.saleInvoiceCode,s.invoiceDate,s.partyCode,s.Name,s.city,s.NetAmount,s.despatch,v.voucherType,v.voucherID
      from saleInvoiceHeader as s,voucher as v
      where v.documentname = 'SL'
      and v.documentno =* s.saleInvoiceCode
      and v.accountCode =* s.partyCode
      and InvoiceDate between @startdate and @enddate
  end if;
  if @status = '1' then -- All Posted Sales
    select s.salesType,s.saleInvoiceCode,s.invoiceDate,s.partyCode,s.Name,s.city,s.NetAmount,s.despatch,v.voucherType,v.voucherID
      from saleInvoiceHeader as s,voucher as v
      where v.documentname = 'SL'
      and v.documentno =* s.saleInvoiceCode
      and v.accountCode =* s.partyCode
      and InvoiceDate between @startdate and @enddate
      and s.status = '1'
  end if;
  if @status = '2' then -- All un-Posted Sales
    select s.salesType,s.saleInvoiceCode,s.invoiceDate,s.partyCode,s.Name,s.city,s.NetAmount,s.despatch,v.voucherType,v.voucherID
      from saleInvoiceHeader as s,voucher as v
      where v.documentname = 'SL'
      and v.documentno =* s.saleInvoiceCode
      and v.accountCode =* s.partyCode
      and InvoiceDate between @startdate and @enddate
      and s.status = '0'
  end if
end
go

