create procedure Saller.r_pr_detail( @startcode integer,@endcode integer ) 
as
begin
  select ih.prtype,ih.documentno,ih.prdate,ih.netamount,ih.partycode,ih.name,ih.address,ih.city,ih.despatch,ih.remarks,ih.deptid,
    id.seqno,id.itemcode,id.itemname,id.purchaserate,id.quantity,id.amount,id.discountrate,ih.discountamount,i.packingsize
    from prheader as ih,prdetail as id,iteminformation as i
    where ih.prno = id.prno
    and id.itemcode = i.itemcode
    and ih.documentno between @startcode and @endcode
end
go

