create procedure saller.r_preturn_gournal( @status char(1),@startdate date,@enddate date ) 
begin
  if @status = '0' then --- All purchase return posted and unposted. 
    select pr.PrType,pr.PrNo,prDate,pr.partyCode,pr.Name,pr.city,pr.NetAmount,v.voucherType,v.voucherID
      from prHeader as pr,voucher as v
      where v.documentname = 'PR'
      and v.documentno =* pr.PrNo
      and v.accountCode =* pr.partyCode
      and PrDate between @startdate and @enddate
  end if;
  if @status = '1' then -- All Posted purchases
    select pr.prType,pr.prNo,prDate,pr.partyCode,pr.Name,pr.city,pr.NetAmount,v.voucherType,v.voucherID
      from prHeader as pr,voucher as v
      where v.documentname = 'PR'
      and v.documentno =* pr.prNo
      and v.accountCode =* pr.partyCode
      and prDate between @startdate and @enddate
      and pr.approved = '1'
  end if;
  if @status = '2' then -- All un-Posted purchases
    select pr.prType,pr.prNo,prDate,pr.partyCode,pr.Name,pr.city,pr.NetAmount,v.voucherType,v.voucherID
      from prHeader as pr,voucher as v
      where v.documentname = 'PR'
      and v.documentno =* pr.prNo
      and v.accountCode =* pr.partyCode
      and prDate between @startdate and @enddate
      and pr.approved = '0'
  end if
end
