create procedure Saller.trail_balance_dealer( @group_code varchar(32),@startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14),@style varchar(1) ) 
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  if @style = '0'
    select op.accountcode,c.accountname,c.limit,
      opngdr=isnull(max(op.openingdr),0)+isnull((select SUM(OPT.DEBIT) from voucher as OPT
        where OPT.ACCOUNTCODE = op.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
      opngcr=isnull(max(op.openingcr),0)+isnull((select SUM(OPT.CREDIT) from voucher as OPT
        where OPT.ACCOUNTCODE = op.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
      isnull(sum(t.debit),0),
      isnull(sum(t.credit),0)
      from chart as c,voucher as t,openingbalances as op
      where op.accountcode *= t.accountcode
      and op.accountcode = c.accountcode
      and op.periodid = @periodid
      and t.voucherdate between @startdate and @enddate
      and op.accountcode between @startcode and @endcode
      group by op.accountcode,c.accountname
      order by 1 asc
  if @style = '1'
    select op.accountcode,c.accountname,c.limit,
      opngdr=isnull(max(op.openingdr),0)+isnull((select SUM(OPT.DEBIT) from voucher as OPT
        where OPT.ACCOUNTCODE = op.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
      opngcr=isnull(max(op.openingcr),0)+isnull((select SUM(OPT.CREDIT) from voucher as OPT
        where OPT.ACCOUNTCODE = op.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
      isnull(sum(t.debit),0),
      isnull(sum(t.credit),0)
      from chart as c,voucher as t,OpeningBalances as op
      where op.accountcode *= t.accountcode
      and op.accountcode = c.accountcode
      and op.periodid = @periodid
      and t.voucherdate between @startdate and @enddate
      and op.accountcode = any(select accountcode from chartgroup where groupcode = @group_code)
      group by op.accountcode,c.accountname
      order by 1 asc
  if @style = '2'
    select c.accountcode,c.accountname,c.limit,
      opngdr=isnull(max(c.openingdr),0)+isnull((select SUM(OPT.DEBIT) from voucher as OPT
        where OPT.ACCOUNTCODE = C.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE),0),
      opngcr=isnull(max(c.openingcr),0)+isnull((select SUM(OPT.CREDIT) from voucher as OPT
        where OPT.ACCOUNTCODE = C.ACCOUNTCODE
        and OPT.voucherdate < @STARTDATE),0),
      isnull(sum(t.debit),0),
      isnull(sum(t.credit),0)
      from chart as c,voucher as t
      where c.accountcode *= t.accountcode
      and t.voucherdate >= @startdate
      and t.voucherdate <= @enddate
      group by c.accountcode,c.accountname
      order by 1 asc
end
go

