create procedure Saller.r_item_wise_production( @style varchar(1),@group varchar(14),@startcode varchar(20),@endcode varchar(20),@startdate date,@enddate date ) 
as
begin
  if @style = '0'
    select dh.dprcode,dh.dprdate,dd.itemcode,max(dd.itemname),max(dd.itemtype),quantity=sum(dd.quantity),
      packingsize=(select packingsize from iteminformation where itemcode = dd.itemcode)
      from dprheader as dh,dprdetail as dd
      where dh.dprCode = dd.dprCode
      and dd.itemcode between @startcode and @endcode
      and dh.dprdate between @startdate and @enddate
      and dh.status = '1'
      group by dh.dprcode,dh.dprdate,dd.itemcode
      order by dd.itemcode asc,dh.dprdate asc
  if @style = '1'
    select dh.dprcode,dh.dprdate,dd.itemcode,max(dd.itemname),max(dd.itemtype),quantity=sum(dd.quantity),
      packingsize=(select packingsize from iteminformation where itemcode = dd.itemcode)
      from dprheader as dh,dprdetail as dd
      where dh.dprCode = dd.dprCode
      and dd.itemcode between @startcode and @endcode
      and dh.dprdate between @startdate and @enddate
      and dd.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group)
      and dh.status = '1'
      group by dh.dprcode,dh.dprdate,dd.itemcode
      order by dd.itemcode asc,dh.dprdate asc
end
go

