create procedure Saller.r_customerwise_salesummary( @startcode varchar(11),@endcode varchar(11),@startdate date,@enddate date ) 
as
begin
  select ih.partycode,max(ih.name),max(ih.city),Amount=sum(ih.netamount),discount=sum(ih.discountamount)
    from saleinvoiceheader as ih
    where ih.partycode between @startcode and @endcode
    and ih.invoicedate between @startdate and @enddate
    and ih.status = '1'
    group by ih.partycode
    order by ih.partycode asc
end
go

