create procedure saller.r_item_wise_purchase( @style varchar(1),@group varchar(14),@startcode varchar(10),@endcode varchar(10),@startdate date,@enddate date ) as
begin
  if @style = '0'
    select pd.itemcode,max(pd.itemname),sum(pd.quantity),sum(pd.amount),ph.purchaseinvoicedate,
      packingsize=(select i.packingsize from iteminformation as i where i.itemcode = pd.itemcode),
      ph.name
      from purchasedetail as pd,purchaseheader as ph
      where ph.purchaseinvoicecode = pd.purchaseinvoicecode
      and pd.itemcode between @startcode and @endcode
      and ph.purchaseinvoicedate between @startdate and @enddate
      and ph.status = '1'
      group by pd.itemcode,ph.purchaseinvoicedate,ph.name
      order by pd.itemcode asc
  if @style = '1'
    select pd.itemcode,max(pd.itemname),sum(pd.quantity),sum(pd.amount),ph.purchaseinvoicedate,
      packingsize=(select i.packingsize from iteminformation as i where i.itemcode = pd.itemcode),
      ph.ph.name
      from purchasedetail as pd,purchaseheader as ph
      where ph.purchaseinvoicecode = pd.purchaseinvoicecode
      and pd.itemcode between @startcode and @endcode
      and ph.purchaseinvoicedate between @startdate and @enddate
      and ph.status = '1'
      and pd.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group)
      group by pd.itemcode,ph.purchaseinvoicedate
      order by pd.itemcode asc,ph.name asc
end
go

