create procedure Saller.r_NotesToAccounts( @Statement varchar(2),@AsOfDate date ) as
begin
  /* select g.GroupCode,c.AccountCode,
max(g.GroupName),max(c.AccountName),
Balance=max(c.OpeningDr)-max(c.OpeningCr)+sum(v.debit)-sum(v.credit) from
groups as g,chart as c,chartGroup as ch,voucher as v where
g.Statement=@Statement
and g.GroupCode=ch.GroupCode
and c.AccountCode=ch.AccountCode
and c.AccountCode=v.AccountCode
and v.doc<=@AsOfDate
group by g.GroupCode,c.AccountCode
*/
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @AsOfDate between startdate and enddate
  select g.groupCode,cg.AccountCode,g.GroupName,c.AccountName,
    Balance=(select Balance=isnull(max(op.openingdr),0)-isnull(max(op.openingcr),0)
      +isnull(sum(t.debit),0)-isnull(sum(t.credit),0)
      from voucher as t,OpeningBalances as op
      where op.accountcode *= t.accountcode
      and op.periodid = @periodid
      and t.voucherdate <= @AsOfDate
      and t.voucherdate between @startfiscaldate and @endfiscaldate
      and op.accountcode = cg.accountCode)
    from groups as g,chartGroup as cg,chart as c
    where g.groupCode = cg.GroupCode
    and cg.accountCode = c.AccountCode
    and g.Statement = @Statement
    and g.Type = 'S'
    order by g.GroupCode asc,cg.AccountCode asc
end
go

