      +isnull(sum(t.debit),0)-isnull(sum(t.credit),0) from
      voucher as t,OpeningBalances as op where
      op.accountcode*=t.accountcode
      and op.periodid=@periodid
      and t.voucherdate<=@AsOfDate
      and t.voucherdate between @startfiscaldate and @endfiscaldate
