create procedure saller.saleorder_remaining_qty( @SaleOrderNo T_Account_code ) 
as
begin
  select sod.ItemCode,
    sod.ItemName,
    sod.MeasuringUnit,
    sod.salerate,
    isnull(max(sod.quantity),0)
    -isnull(sum(sd.quantity),0)
    from SaleInvoiceHeader as s key join SaleInvoiceDetail as sd
      right outer join SaleOrderDetail as sod
      on sd.ItemCode = sod.ItemCode left outer join SaleInvoiceHeader as si
      on sod.SaleOrderNo = si.SaleOrderNo
    where sod.SaleOrderNo = @SaleOrderNo
    group by sod.itemCode,sod.ItemName,sod.MeasuringUnit,sod.salerate
    having isnull(max(sod.quantity),0)-isnull(sum(sd.quantity),0) <> 0
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."saleorder_remaining_qty" IS 
{create procedure saller.saleorder_remaining_qty(@SaleOrderNo T_ACCOUNT_CODE)
as
begin
  select sod.ItemCode,
    sod.ItemName,
    sod.MeasuringUnit,
    sod.salerate,
    isnull(max(sod.quantity),0)
    -isnull(sum(sd.quantity),0) from
    SaleInvoiceHeader as s key join SaleInvoiceDetail as sd right outer join
    SaleOrderDetail as sod on
    sd.ItemCode=sod.ItemCode left outer join SaleInvoiceHeader as si on
    sod.SaleOrderNo=si.SaleOrderNo where
    sod.SaleOrderNo=@SaleOrderNo
    group by sod.itemCode,sod.ItemName,sod.MeasuringUnit,sod.salerate having
    isnull(max(sod.quantity),0)-isnull(sum(sd.quantity),0)<>0
end
}
go

create procedure saller.r_itemwise_salesummary( @style varchar(1),@group varchar(14),@startcode varchar(20),@endcode varchar(20),@startdate date,@enddate date ) 
as
begin
  if @style = '0'
    select d.itemcode,max(d.itemname),sum(d.quantity),sum(d.amount),i.packingsize,ih.invoicedate
      from saleinvoicedetail as d,saleinvoiceheader as ih,iteminformation as i
      where d.saleinvoicecode = ih.saleinvoicecode
      and d.itemcode between @startcode and @endcode
      and d.itemcode = i.itemcode
      and ih.invoicedate between @startdate and @enddate
      group by d.itemcode,i.packingsize,ih.invoicedate
      order by d.itemcode asc
  if @style = '1'
    select d.itemcode,max(d.itemname),sum(d.quantity),sum(d.amount),i.packingsize,ih.invoicedate
      from saleinvoicedetail as d,saleinvoiceheader as ih,iteminformation as i
      where d.saleinvoicecode = ih.saleinvoicecode
      and d.itemcode between @startcode and @endcode
      and d.itemcode = i.itemcode
      and ih.invoicedate between @startdate and @enddate
      and d.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group)
      group by d.itemcode,i.packingsize,ih.invoicedate
      order by d.itemcode asc
end
go

