create procedure saller.ledger_detail( @group_code varchar(32),@startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14),@style varchar(1) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  --select All Account.
  if @style = '0'
    -- selection from saleinvoice amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.InvoiceDate,null,null,si.despatch,sd.itemcode,sd.itemname,sd.quantity,sd.saleRate,
      sd.amount,null,'SInv# '
      +convert(varchar(11),si.documentno),convert(varchar(11),si.documentno),si.city,sd.measuringunit
      from SaleInvoiceHeader as si,SaleInvoiceDetail as sd
      where si.SaleInvoiceCode = sd.SaleInvoiceCode
      and si.status = '1'
      and si.salestype <> 0
      and si.partyCode between @startCode and @endCode
      and si.InvoiceDate between @startDate and @enddate union all
    -- selection from saleinvoice discount amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.InvoiceDate,null,null,null,null,'Discount on Invoice',null,null,
      null,si.discountAmount,'SInv# '
      +convert(varchar(11),si.documentno),convert(varchar(11),si.documentno),si.city,null
      from SaleInvoiceHeader as si
      where si.status = '1'
      and si.salestype <> 0
      and si.partyCode between @startCode and @endCode
      and si.InvoiceDate between @startDate and @enddate
      and si.discountAmount > 0 union all
    -- selection from Voucher
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = t.accountcode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = t.accountcode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,
      c.accountname,
      t.voucherdate,
      t.debit,
      t.credit,
      despatch=null,
      pcode=null,
      pname=null,
      qty=null,
      rate=null,
      amount=null,
      camount=null,
      t.narration,
      t.voucherid,
      c.city,measuringunit=null from chart as c,voucher as t,openingbalances as op
      where op.accountcode = c.accountcode
      and(c.accountcategory = 'S' or c.accountcategory = 'V')
      and op.periodid = @periodid
      and c.accountcode = t.accountcode
      and t.documentno is null
      and t.documentname is null
      and t.accountcode between @startcode and @endcode
      and t.voucherdate between @startdate and @enddate union all
    -- selection of saleReturn amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr
        where tr.accountcode = si.partycode
        and tr.voucherdate < @startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.SrDate,null,null,si.despatch,sd.itemcode,sd.itemname,sd.quantity,sd.saleRate,null,sd.amount,'SRInv# '
      +convert(varchar(11),si.documentno),convert(varchar(11),si.documentno),si.city,sd.measuringunit
      from SRHeader as si,SRDetail as sd
      where si.Srno = sd.Srno
      and si.Approved = '1'
      and si.srtype <> 0
      and si.partyCode between @startCode and @endCode
      and si.SrDate between @startDate and @enddate union all
    -- Select of Purchase Invoice Amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op
        where op.accountcode = si.partycode and op.periodid = @periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr
