      +convert(varchar(11),si.documentno),convert(varchar(11),si.documentno),si.city,sd.measuringunit from
      SaleInvoiceHeader as si,SaleInvoiceDetail as sd where
      si.SaleInvoiceCode=sd.SaleInvoiceCode
      and si.status='1'
      and si.salestype<>0
      and si.partyCode=any(select accountcode from chartgroup where groupcode=@group_code)
      and si.InvoiceDate between @startDate and @enddate union all
    -- selection from Voucher
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=t.accountcode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=t.accountcode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      t.accountcode,
      c.accountname,
      t.voucherdate,
      t.debit,
      t.credit,
      despatch=null,
      pcode=null,
      pname=null,
      qty=null,
      rate=null,
      amount=null,
      camount=null,
      t.narration,
      t.voucherid,
      c.city,measuringunit=null from chart as c,voucher as t,openingbalances as op where
      op.accountcode=c.accountcode
      and(c.accountcategory='S' or c.accountcategory='V')
      and op.periodid=@periodid
      and c.accountcode=t.accountcode
      and t.documentno is null
      and t.documentname is null
      and c.accountcode=any(select accountcode from chartgroup where groupcode=@group_code)
      and t.voucherdate between @startdate and @enddate union all
    -- selection of saleReturn amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.SrDate,null,null,si.despatch,sd.itemcode,sd.itemname,sd.quantity,sd.saleRate,null,sd.amount,'SRInv# '
      +convert(varchar(11),si.documentno),convert(varchar(11),si.documentno),si.city,sd.measuringunit from
      SRHeader as si,SRDetail as sd where
      si.Srno=sd.Srno
      and si.Approved='1'
      and si.srtype<>0
      and si.partyCode=any(select accountcode from chartgroup where groupcode=@group_code)
      and si.SrDate between @startDate and @enddate union all
    -- Select of Purchase Invoice Amount
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.PurchaseInvoiceDate,null,null,si.despatch,sd.itemcode,sd.itemname,
      sd.quantity,sd.purchaseRate,null,sd.amount,'PInv# '+convert(varchar(11),si.documentno),
      convert(varchar(11),si.documentno),si.city ,sd.measuringunit from
      PurchaseHeader as si,PurchaseDetail as sd where
      si.purchaseinvoiceCode=sd.purchaseInvoiceCode
      and si.status='1'
      and si.purchasetype<>0
      and si.partyCode=any(select accountcode from chartgroup where groupcode=@group_code)
      and si.purchaseInvoiceDate between @startDate and @enddate union all
    -- Select Amount of Purchase Return
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.PrDate,null,null,si.despatch,sd.itemcode,sd.itemname,sd.quantity,sd.purchaseRate,
      sd.amount,null,'PRInv# '+convert(varchar(11),si.documentno),
      convert(varchar(11),si.documentno),si.city,sd.measuringunit from
      PrHeader as si,PrDetail as sd where
      si.prNo=sd.prNo
      and si.approved='1'
      and si.prtype<>0
      and si.partyCode=any(select accountcode from chartgroup where groupcode=@group_code)
      and si.prDate between @startDate and @enddate union all
-- Select Amount of Inward / Outward
    select openingdebit=(select isnull(max(op.openingdr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      openingcredit=(select isnull(max(op.openingcr),0) from openingbalances as op where
        op.accountcode=si.partycode and op.periodid=@periodid),
      totaldebit=isnull((select sum(tr.debit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      totalcredit=isnull((select sum(tr.credit) from voucher as tr where
        tr.accountcode=si.partycode
        and tr.voucherdate<@startdate
        and tr.voucherdate between @startfiscaldate and @endfiscaldate
        group by tr.accountcode),0),
      si.Partycode,si.name,
      si.InwardDate,null,null,si.despatch,sd.itemcode,sd.itemname,sd.quantity,sd.saleRate,
      sd.amount,null,'Service Inv# '+convert(varchar(11),si.documentno),
      convert(varchar(11),si.documentno),si.city,sd.measuringunit from
      InwardHeader as si,InwardDetail as sd where
      si.InwardNo=sd.InwardNo
      and si.status='1'
      and si.partyCode=any(select accountcode from chartgroup where groupcode=@group_code)
      and si.InwardDate between @startDate and @enddate order by
      5 asc,7 asc,18 asc,17 asc
end
}
go

create procedure Saller.r_vendorwise_purchasesummary( @startcode varchar(11),@endcode varchar(11),@startdate date,@enddate date ) 
as
begin
  select ph.partycode,max(ph.name),max(ph.city),Amount=sum(ph.netamount)
    from purchaseheader as ph
    where ph.partycode between @startcode and @endcode
    and ph.purchaseinvoicedate between @startdate and @enddate
    and ph.status = '1'
    group by ph.partycode
    order by ph.partycode asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_vendorwise_purchasesummary" IS 
{create procedure Saller.r_vendorwise_purchasesummary(@startcode varchar(11),@endcode varchar(11),@startdate date,@enddate date)
as
begin
  select ph.partycode,max(ph.name),max(ph.city),Amount=sum(ph.netamount) from
    purchaseheader as ph where
    ph.partycode between @startcode and @endcode
    and ph.purchaseinvoicedate between @startdate and @enddate
    and ph.status='1'
    group by ph.partycode order by
    ph.partycode asc
end
}
