create procedure saller.p_salestax_return( @startdate date,@enddate date ) 
/* RESULT ( column-name,... ) */
as
begin
  declare @period date
  declare @reg_sales numeric(14,2)
  declare @unreg_sales numeric(14,2)
  declare @exempt_sales numeric(14,2)
  declare @reg_st_rate numeric(5,2)
  declare @purchase numeric(14,2)
  declare @input_st_rate numeric(5,2)
  declare @exempt_purchase numeric(14,2)
  declare @zr_purchase numeric(14,2)
  declare @outstanding numeric(14,2)
  declare @refund_claimed numeric(14,2)
  declare @st_payable numeric(14,2)
  declare @pay_date date
  declare @remarks varchar(64)
  declare @status char(1)
  select @reg_sales = sum(sh.netamount),
    @reg_st_rate = sd.strate
    from saleinvoiceheader as sh
      ,saleinvoicedetail as sd
    where sh.saletaxNo is not null
    and sh.invoicedate between @startdate and @enddate
  select @unreg_sales = sum(sh.netamount),
    @reg_st_rate = sd.strate
    from saleinvoiceheader as sh
      ,saleinvoicedetail as sd
    where sh.saletype = '0'
    and sh.invoicedate between @startdate and @enddate
  select @purchase = sum(ph.netamount),
    @input_st_rate = pd.strate
    from purchaseheader as ph
      ,purchasedetail as pd
    where ph.purchasetype = '1'
    and ph.purchaseinvoicedate between @startdate and @enddate
end
go

