create procedure Saller.r_accounts_payable( @startdate date,@enddate date ) 
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  /* Get the fiscal period for given time frame. */
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  select op.accountcode,c.accountname,c.city,
    opngdr=isnull(max(op.openingdr),0)+isnull((select SUM(isnull(OPT.DEBIT,0)) from voucher as OPT
      where OPT.ACCOUNTCODE = OP.ACCOUNTCODE
      and OPT.Voucherdate < @STARTDATE
      and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
    opngcr=isnull(max(op.openingcr),0)+isnull((select SUM(isnull(OPT.CREDIT,0)) from voucher as OPT
      where OPT.ACCOUNTCODE = op.ACCOUNTCODE
      and OPT.voucherdate < @STARTDATE
      and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
    isnull(sum(v.debit),0),
    isnull(sum(v.credit),0)
    from openingbalances as op,voucher as v,chart as c
    where op.accountcode *= v.accountcode
    and op.accountcode = c.accountcode
    and op.periodid = @periodid
    and v.voucherdate between @startdate and @enddate
    and c.accountcategory = 'V'
    group by op.accountcode,c.accountname,c.city
end
go

