create procedure saller.sale_order_search( @style varchar(1),@startdate date,@enddate date ) 
as /* RESULT ( column-name,... ) */
begin
  if @style = '0'
    select saleorderno,invoicedate,name,city,status
      from saleorderheader
      where invoicedate between @startdate and @enddate
  else if @style = '1'
      select saleorderno,invoicedate,name,city,status
        from saleorderheader where approved = '0'
        and status <> 'F'
        and invoicedate between @startdate and @enddate
    else if @style = '2'
        select saleorderno,invoicedate,name,city,status
          from saleorderheader where approved = '1'
          and invoicedate between @startdate and @enddate
      else if @style = '3'
          select saleorderno,invoicedate,name,city,status
            from saleorderheader where approved = '1'
            and status <> 'F'
            and invoicedate between @startdate and @enddate
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."sale_order_search" IS 
{create PROCEDURE saller."sale_order_search"(@style varchar(1),@startdate date,@enddate date)
as /* RESULT ( column-name,... ) */
begin
  if @style='0'
    select saleorderno,invoicedate,name,city,status from
      saleorderheader where
      invoicedate between @startdate and @enddate
  else if @style='1'
      select saleorderno,invoicedate,name,city,status from
        saleorderheader where approved = '0'
        and status<>'F'
        and invoicedate between @startdate and @enddate
    else if @style='2'
        select saleorderno,invoicedate,name,city,status from
          saleorderheader where approved='1'
          and invoicedate between @startdate and @enddate
      else if @style='3'
          select saleorderno,invoicedate,name,city,status from
            saleorderheader where approved='1'
            and status<>'F'
            and invoicedate between @startdate and @enddate
end
