      group by ch.consnotecode,ch.consnotedate,ch.dprcode,cd.itemcode,i.packingsize,i.purchaserate
      order by cd.itemcode asc
  if @style = '1'
    select ch.consnotecode,ch.consnotedate,ch.dprcode,cd.itemcode,max(cd.itemname),sum(cd.quantity),sum(cd.wastagequantity),
      i.packingsize,i.purchaserate
      from consumptionnotedetail as cd,consumptionnoteheader as ch,iteminformation as i
      where cd.consNoteCode = ch.consNoteCode
      and i.itemcode = cd.itemcode
      and cd.itemcode between @startcode and @endcode
      and ch.consNoteDate between @startdate and @enddate
      and ch.status = '1'
      and cd.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group)
      group by ch.consnotecode,ch.consnotedate,ch.dprcode,cd.itemcode,i.packingsize,i.purchaserate
      order by cd.itemcode asc
end
