create procedure saller.FMClosingYear( @oldperiodid varchar(12),@newperiodid varchar(12) ) 
as
begin
  declare @enddate date,@startdate date,@accountcode varchar(14),@balance numeric(14,2)
  select @startdate = startdate,@enddate = enddate from fiscalyears
    where year = @oldperiodid
  insert into openingbalances select @newperiodid,accountcode,0,0,accounttype
      from chart
      where not accountcode = any(select accountcode from openingbalances
        where periodid = @newperiodid)
  declare cur_bal dynamic scroll cursor for select o.accountcode,
      isnull(max(o.openingdr),0)-isnull(max(o.openingcr),0)+sum(isnull(v.debit,0))-sum(isnull(v.credit,0))
      from openingbalances as o,voucher as v
      where o.accountcode *= v.accountcode
      and v.voucherdate between @startdate and @enddate
      and periodid = @oldperiodid
      and o.accounttype in( 'A','L','C' ) 
      group by o.accountcode
  open cur_bal
  fetch next cur_bal into @accountcode,@balance
  while @@sqlstatus <> 2
    begin
      if @balance >= 0
        update openingbalances
          set openingdr = @balance,
          openingcr = 0
          where accountcode = @accountcode
          and periodid = @newperiodid
      else
        update openingbalances set openingdr = 0,openingcr = abs(@balance)
          where accountcode = @accountcode
          and periodid = @newperiodid
      fetch next cur_bal into @accountcode,@balance
    end
  close cur_bal
  deallocate cursor cur_bal
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."FMClosingYear" IS 
{create procedure saller.FMClosingYear(@oldperiodid varchar(12),@newperiodid varchar(12))
as
begin
  declare @enddate date,@startdate date,@accountcode varchar(14),@balance numeric(14,2)
  select @startdate=startdate,@enddate=enddate from fiscalyears where
    year=@oldperiodid
  insert into openingbalances select @newperiodid,accountcode,0,0,accounttype from
      chart where
      not accountcode=any(select accountcode from openingbalances where
        periodid=@newperiodid)
  declare cur_bal dynamic scroll cursor for select o.accountcode,
      isnull(max(o.openingdr),0)-isnull(max(o.openingcr),0)+sum(isnull(v.debit,0))-sum(isnull(v.credit,0)) from
      openingbalances as o,voucher as v where
      o.accountcode*=v.accountcode
      and v.voucherdate between @startdate and @enddate
      and periodid=@oldperiodid
      and o.accounttype in('A','L','C')
      group by o.accountcode
  open cur_bal
  fetch next cur_bal into @accountcode,
    @balance
  while @@sqlstatus<>2
    begin
      if @balance>=0
        update openingbalances set
          openingdr=@balance,
          openingcr=0 where
          accountcode=@accountcode
          and periodid=@newperiodid
      else
        update openingbalances set openingdr=0,openingcr=abs(@balance) where
          accountcode=@accountcode
          and periodid=@newperiodid
      fetch next cur_bal into @accountcode,
        @balance end
  close cur_bal
  deallocate cursor cur_bal
end
}
go

