create procedure saller.so_remaining_qty( @so_no integer ) 
as /* RESULT ( column-name,... ) */
begin
  select max(sd.seqno),sd.itemcode,sd.itemname,sd.measuringunit,sd.salerate,remaining_qty=sd.quantity-isNull(sin.qty,0),
    sd.discountrate,sd.discountamount
    from saleorderdetail as sd
      ,(select sh.saleorderno,invd.itemcode,qty=sum(invd.quantity)
        from saleinvoiceheader as sh,saleinvoicedetail as invd
        where sh.saleInvoiceCode = invd.saleinvoicecode
        group by sh.saleOrderNo,invd.itemcode) as sin
    where sd.saleOrderNo *= sin.saleOrderNo
    and sd.itemcode *= sin.itemcode
    and sd.saleOrderNo = @so_no
    group by sd.itemcode,sd.itemname,sd.measuringunit,sd.salerate,sd.quantity,sin.qty,sd.discountrate,sd.discountamount
    having sd.quantity-isNull(sin.qty,0) > 0
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."so_remaining_qty" IS 
{create PROCEDURE saller."so_remaining_qty"(@so_no integer)
as /* RESULT ( column-name,... ) */
begin
  select max(sd.seqno),sd.itemcode,sd.itemname,sd.measuringunit,sd.salerate,remaining_qty=sd.quantity-isNull(sin.qty,0),
         sd.discountrate,sd.discountamount
        from saleorderdetail as sd,  
    (select sh.saleorderno,invd.itemcode,qty=sum(invd.quantity) from
      saleinvoiceheader as sh,saleinvoicedetail as invd where
      sh.saleInvoiceCode=invd.saleinvoicecode
      group by sh.saleOrderNo,invd.itemcode) as sin where
    sd.saleOrderNo*=sin.saleOrderNo
    and sd.itemcode*=sin.itemcode
    and sd.saleOrderNo=@so_no
    group by sd.itemcode,sd.itemname,sd.measuringunit,sd.salerate,sd.quantity,sin.qty,sd.discountrate,sd.discountamount having
    sd.quantity-isNull(sin.qty,0)>0
end
}
go

