create procedure saller.UF_GET_LAST_PURCHASE_RATE( @ITEM_ID varchar(32) ) 
as
begin
  declare @RATE numeric(14,2)
  select @Rate = isNull(p.purchaserate,0)
    from purchasedetail as p
      join(select itemcode,doc_no=max(PURCHASEINVOICECODE)
        from purchasedetail group by itemcode) as g
      on p.itemcode = g.itemcode
      and p.PURCHASEINVOICECODE = g.doc_no
      and p.itemcode = @ITEM_ID
  return(@RATE)
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."UF_GET_LAST_PURCHASE_RATE" IS 
{create PROCEDURE saller."UF_GET_LAST_PURCHASE_RATE"(@ITEM_ID varchar(32))
as
begin
  declare @RATE numeric(14,2)
  select @Rate=isNull(p.purchaserate,0) from
    purchasedetail as p join(select itemcode,doc_no=max(PURCHASEINVOICECODE) from
      purchasedetail group by itemcode) as g on
    p.itemcode=g.itemcode
    and p.PURCHASEINVOICECODE=g.doc_no
    and p.itemcode=@ITEM_ID
  return(@RATE)
end
}
go

create procedure saller.r_citywise_saleorder( @style char(1),@City varchar(32),@startDate datetime,@enddate datetime ) 
as
begin
  if @style = '1' --select all the sale
    select saleInvoicecode,invoicedate,partycode,name,city,discountamount,netamount
      from saleInvoiceheader
      where invoicedate >= @startdate
      and invoicedate <= @enddate
  if @style = '2' --filter city wise  
    select saleInvoicecode,invoicedate,partycode,name,city,discountamount,netamount
      from saleInvoiceheader
      where city = @city
      and invoicedate >= @startdate
      and invoicedate <= @enddate
end
