create procedure saller.monthwise_sales_summary( @startdate date,@endDate date ) as
begin
  select t.mName,t.yName,t.city,sales=sum(t.sales),receive=sum(t.receive)
    from(select monthno=month(invoiceDate),mName=monthName(invoiceDate),yName=Year(invoiceDate),city,
        sales=sum(netAmount),
        receive=0
        from SaleInvoiceHeader
        where invoiceDate between @startDate and @endDate
        group by year(invoiceDate),monthName(invoiceDate),city,month(invoiceDate) union all
      select monthno=month(v.voucherDate),monthName(v.voucherDate),year(v.voucherDate),
        c.city,sales=0,receive=sum(v.credit)
        from voucher as v key join chart as c
        where v.voucherDate between @startDate and @endDate
        and v.voucherType in( 'CRV','BRV' ) 
        and c.accountCategory = 'S'
        group by monthName(v.voucherDate),year(v.voucherDate),c.city,month(v.voucherDate)) as t
    group by t.mName,t.yName,t.city,t.monthno
    order by t.city asc,t.yName asc,t.monthno asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."monthwise_sales_summary" IS 
{create procedure saller.monthwise_sales_summary(@startdate date,@endDate date) as
begin
  select t.mName,t.yName,t.city,sales=sum(t.sales),receive=sum(t.receive) from(
    select monthno=month(invoiceDate),mName=monthName(invoiceDate),yName=Year(invoiceDate),city,
      sales=sum(netAmount),
      receive=0 from
      SaleInvoiceHeader where
      invoiceDate between @startDate and @endDate
      group by year(invoiceDate),monthName(invoiceDate),city,month(invoiceDate) union all
    select monthno=month(v.voucherDate),monthName(v.voucherDate),year(v.voucherDate),
      c.city,sales=0,receive=sum(v.credit) from
      voucher as v key join chart as c where
      v.voucherDate between @startDate and @endDate
      and v.voucherType in('CRV','BRV')
      and c.accountCategory='S'
      group by monthName(v.voucherDate),year(v.voucherDate),c.city,month(v.voucherDate)) as t
    group by t.mName,t.yName,t.city,t.monthno order by
    t.city asc,t.yName asc,t.monthno asc
end
}
