        cal30=0,
        cal45=0,
        cal60=0,
        calabove=0,
        credit=0
        from voucher as v
        where v.voucherdate between dateadd(day,-15,@asofdate) and @asofDate
        and v.accountcode between @startCode and @endCode
        group by v.accountcode union all
      select v.accountcode,
        cal15=0,
        cal30=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),
        cal45=0,
        cal60=0,
        calabove=0,
        credit=0
        from voucher as v
        where v.voucherdate between dateadd(day,-30,@asofdate) and dateadd(day,-16,@asofdate)
        and v.accountcode between @startCode and @endCode
        group by v.accountcode union all
      select v.accountcode,
        cal15=0,
        cal30=0,
        cal45=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),
        cal60=0,
        calabove=0,
        credit=0
        from voucher as v
        where v.voucherdate between dateadd(day,-45,@asofdate) and dateadd(day,-31,@asofdate)
        and v.accountcode between @startCode and @endCode
        group by v.accountcode union all
      select v.accountcode,
