        where v.voucherdate between dateadd(day,-60,@asofdate) and dateadd(day,-46,@asofdate)
        and v.accountcode between @startCode and @endCode
        group by v.accountcode union all
      select v.accountcode,
        cal15=0,
        cal30=0,
        cal45=0,
        cal60=0,
        calabove=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),
        credit=0
        from voucher as v
        where v.voucherdate between @startfiscalDate and dateadd(day,-61,@asofdate)
        and v.accountcode between @startCode and @endCode
        group by v.accountcode) as t
      on c.accountcode = t.accountcode
      join openingbalances as op
      on c.accountcode = op.accountcode
    where op.periodid = @periodid
    and c.accountcode between @startCode and @endCode
    and c.accountcategory = 'S'
    group by c.accountcode,c.accountname
    order by 1 asc,2 asc
