create procedure Saller.r_bank_report( @startdate date,@enddate date ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  begin
    select t.monthno,t.monthname,t.yearname,sum(t.openingBalance),totaldebit=0,totalcredit=0
      from(select monthno=0,monthname='',yearname='',
          openingbalance=isnull(max(op.openingdr),0)-isnull(max(op.openingcr),0),
          totaldebit=0,totalcredit=0
          from openingbalances as op
          where op.accountcode = '100011'
          and op.periodid = @periodid union all
        select monthno=0,monthname='',yearname='',openingbalance=isnull(sum(t.debit),0)-isnull(sum(t.credit),0),
          totaldebit=0,totalcredit=0
          from voucher as t
          where t.accountcode = '100011'
          and t.voucherdate between @startfiscaldate and @startdate) as t
      group by t.monthname,t.yearname,t.monthno union all
    select monthno=month(voucherDate),monthname(voucherDate),year(voucherDate),openingBalance=0,isnull(sum(debit),0),isnull(sum(credit),0)
      from voucher
      where voucherdate between @startDate and @endDate
      and accountCode = '100011'
      group by monthname(voucherDate),year(voucherDate),month(voucherDate)
  end
end
go

