  begin
    select t.monthno,t.monthname,t.yearname,sum(t.openingBalance),totaldebit=0,totalcredit=0 from(
      select monthno=0,monthname='',yearname='',
        openingbalance=isnull(max(op.openingdr),0)-isnull(max(op.openingcr),0),
        totaldebit=0,totalcredit=0 from
        openingbalances as op where
        op.accountcode='100011'
        and op.periodid=@periodid union all
      select monthno=0,monthname='',yearname='',openingbalance=isnull(sum(t.debit),0)-isnull(sum(t.credit),0),
        totaldebit=0,totalcredit=0 from
        voucher as t where
        t.accountcode='100011'
        and t.voucherdate between @startfiscaldate and @startdate) as t
