create procedure saller.p_ItemTypeWise_StockValue_pl( @StartDate date,@AsOfDate date ) 
/*  Procedure for evaluating stock in hand.
**  Author:  Abdul Sattar Mughal         Date: 2002-04-19
*/
as
begin
  select t2.ItemType,StockValue=sum(t2.ClosingStockValue)
    /* Produced */
    /* Purchased */
    /* Sale Returned */
    /* Sold */
    /* Consumed */
    /* Purchase Returned */
    from(select i.ItemCode,i.ItemType,ClosingStockValue=isNull((isNull(max(i.OpeningStock),0)+sum(t.ProducedQty)+sum(t.PurchasedQty)
        +sum(t.SaleReturnedQty)-sum(t.SoldQty)-sum(t.ConsumedQty)-sum(t.PurchaseReturnedQty)),0)*isNull(max(i.PurchaseRate),0)
        from ItemInformation as i
          ,(select dprd.ItemCode,ProducedQty=sum(dprd.Quantity),
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from DPRHeader as dprh,DPRDetail as dprd
            where dprh.DPRCode = dprd.DPRCode
            and dprh.Status = '1'
            and dprh.DPRDate between @startDate and @AsOfDate
            group by dprd.ItemCode union all
          select pd.ItemCode,ProducedQty=0,
            PurchasedQty=sum(pd.Quantity),SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from PurchaseHeader as ph,PurchaseDetail as pd
            where ph.PurchaseInvoiceCode = pd.PurchaseInvoiceCode
            and ph.Status = '1'
            and ph.PurchaseInvoiceDate between @startDate and @AsOfDate
            group by pd.ItemCode union all
          select srd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=sum(srd.Quantity),SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=0
            from SRHeader as srh,SRDetail as srd
            where srh.SRNo = srd.SRNo
            and srh.Approved = '1'
            and srh.SRDate between @startDate and @AsOfDate
            group by srd.ItemCode union all
          select sd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=sum(sd.Quantity),
            ConsumedQty=0,PurchaseReturnedQty=0
            from SaleInvoiceHeader as sh,SaleInvoiceDetail as sd
            where sh.SaleInvoiceCode = sd.SaleInvoiceCode
            and sh.Status = '1'
            and sh.InvoiceDate between @startDate and @AsOfDate
            group by sd.ItemCode union all
          select cd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=sum(cd.Quantity),PurchaseReturnedQty=0
            from ConsumptionNoteHeader as ch,ConsumptionNoteDetail as cd
            where ch.ConsNoteCode = cd.ConsNoteCode
            and ch.ConsNoteDate between @startDate and @AsOfDate
            group by cd.ItemCode union all
          select prd.ItemCode,ProducedQty=0,
            PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
            ConsumedQty=0,PurchaseReturnedQty=sum(prd.Quantity)
            from PRHeader as prh,PRDetail as prd
            where prh.PRNo = prd.PRNo
            and prh.Approved = '1'
            and prh.PRDate between @startDate and @AsOfDate
            group by prd.ItemCode) as t
        where i.ItemCode *= t.ItemCode
        group by i.ItemCode,i.ItemType) as t2
    group by t2.ItemType
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."p_ItemTypeWise_StockValue_pl" IS 
{create procedure saller.p_ItemTypeWise_StockValue_pl(@StartDate date,@AsOfDate date)
/*  Procedure for evaluating stock in hand.
**  Author:  Abdul Sattar Mughal         Date: 2002-04-19
*/
as
begin
  select t2.ItemType,StockValue=sum(t2.ClosingStockValue) from
    (select i.ItemCode,i.ItemType,ClosingStockValue=isNull((isNull(max(i.OpeningStock),0)+sum(t.ProducedQty)+sum(t.PurchasedQty)
      +sum(t.SaleReturnedQty)-sum(t.SoldQty)-sum(t.ConsumedQty)-sum(t.PurchaseReturnedQty)),0)*isNull(max(i.PurchaseRate),0) from
      ItemInformation as i,(
      /* Produced */
      select dprd.ItemCode,ProducedQty=sum(dprd.Quantity),
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        DPRHeader as dprh,DPRDetail as dprd where
        dprh.DPRCode=dprd.DPRCode
        and dprh.Status='1'
        and dprh.DPRDate between @startDate and @AsOfDate
        group by dprd.ItemCode union all
      /* Purchased */
      select pd.ItemCode,ProducedQty=0,
        PurchasedQty=sum(pd.Quantity),SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        PurchaseHeader as ph,PurchaseDetail as pd where
        ph.PurchaseInvoiceCode=pd.PurchaseInvoiceCode
        and ph.Status='1'
        and ph.PurchaseInvoiceDate between @startDate and @AsOfDate
        group by pd.ItemCode union all
      /* Sale Returned */
      select srd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=sum(srd.Quantity),SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=0 from
        SRHeader as srh,SRDetail as srd where
        srh.SRNo=srd.SRNo
        and srh.Approved='1'
        and srh.SRDate between @startDate and @AsOfDate
        group by srd.ItemCode union all
      /* Sold */
      select sd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=sum(sd.Quantity),
        ConsumedQty=0,PurchaseReturnedQty=0 from
        SaleInvoiceHeader as sh,SaleInvoiceDetail as sd where
        sh.SaleInvoiceCode=sd.SaleInvoiceCode
        and sh.Status='1'
        and sh.InvoiceDate between @startDate and @AsOfDate
        group by sd.ItemCode union all
      /* Consumed */
      select cd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=sum(cd.Quantity),PurchaseReturnedQty=0 from
        ConsumptionNoteHeader as ch,ConsumptionNoteDetail as cd where
        ch.ConsNoteCode=cd.ConsNoteCode
        and ch.ConsNoteDate between @startDate and @AsOfDate
        group by cd.ItemCode union all
      /* Purchase Returned */
      select prd.ItemCode,ProducedQty=0,
        PurchasedQty=0,SaleReturnedQty=0,SoldQty=0,
        ConsumedQty=0,PurchaseReturnedQty=sum(prd.Quantity) from
        PRHeader as prh,PRDetail as prd where
        prh.PRNo=prd.PRNo
        and prh.Approved='1'
        and prh.PRDate between @startDate and @AsOfDate
        group by prd.ItemCode) as t where
      i.ItemCode*=t.ItemCode
      group by i.ItemCode,i.ItemType) as t2
    group by t2.ItemType
end
}
go

create procedure saller.p_statement_pl( @StartDate date,@Date date,@Statement varchar(2) ) 
as
begin
  /*declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
fiscalyears where @Date between startdate and enddate */
  select t.GroupCode,GroupName=max(t.GroupName),Balance=abs(sum(t.CurrentBalance))
    /*Select all groups for statement. */
    /* Select the opening balances of groups, also include	 accounts which have no transactions at all.*/
    /*Select the current balances of groups as of given date*/
    from(select g.GroupCode,GroupName=max(g.GroupName),OpeningBalance=0,CurrentBalance=0
        from Groups as g
        where g.Type = 'S'
        and g.Statement = @Statement
        group by g.GroupCode union all
      select g.GroupCode,g.GroupName,
        OpeningBalance=0,CurrentBalance=sum(isnull(v.Debit,0)-isnull(v.Credit,0))
        from Groups as g,ChartGroup as cg,Chart as c,Voucher as v
        where g.GroupCode = cg.GroupCode
        and c.AccountCode = cg.AccountCode
        and c.AccountCode = v.AccountCode
        and cg.AccountCode = v.AccountCode
        and v.VoucherDate between @startdate and @Date
        and g.Type = 'S'
        and g.Statement = @Statement
        group by g.GroupCode,g.GroupName) as t
    group by t.GroupCode
    order by t.GroupCode asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."p_statement_pl" IS 
{create procedure saller.p_statement_pl(@StartDate date,@Date date,@Statement varchar(2))
as
begin
  /*declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
  fiscalyears where @Date between startdate and enddate */
  select t.GroupCode,GroupName=max(t.GroupName),Balance=abs(sum(t.CurrentBalance)) from(
    /*Select all groups for statement. */
    select g.GroupCode,GroupName=max(g.GroupName),OpeningBalance=0,CurrentBalance=0 from
      Groups as g where
      g.Type='S'
      and g.Statement=@Statement
      group by g.GroupCode union all
    /* Select the opening balances of groups, also include	 accounts which have no transactions at all.*/
    /*Select the current balances of groups as of given date*/
    select g.GroupCode,g.GroupName,
      OpeningBalance=0,CurrentBalance=sum(isnull(v.Debit,0)-isnull(v.Credit,0)) from
      Groups as g,ChartGroup as cg,Chart as c,Voucher as v where
      g.GroupCode=cg.GroupCode
      and c.AccountCode=cg.AccountCode
      and c.AccountCode=v.AccountCode
      and cg.AccountCode=v.AccountCode
      and v.VoucherDate between @startdate and @Date
      and g.Type='S'
      and g.Statement=@Statement
      group by g.GroupCode,g.GroupName) as t
    group by t.GroupCode order by
    t.GroupCode asc
end
}
go

create procedure saller.r_citywise_pr( @style char(1),@City varchar(32),@startDate datetime,@enddate datetime ) 
as
begin
  if @style = '1' --select all the sale
    select prno,prdate,partycode,name,ApplyTo,discountamount,netamount
      from Prheader
      where prdate >= @startdate
      and prdate <= @enddate
  if @style = '2' --filter city wise
    select prno,prdate,partycode,name,ApplyTo,discountamount,netamount
      from prheader
      where applyto = @city
      and prdate >= @startdate
      and prdate <= @enddate
end
