create procedure Saller.r_GroupNotes_pl( @GroupCode varchar(10),@startDate date,@AsOfDate date ) as
begin
  select g.groupCode,cg.AccountCode,g.GroupName,c.AccountName,
    Balance=(select Balance=isnull(sum(t.debit),0)-isnull(sum(t.credit),0)
      from voucher as t
      where t.voucherdate between @startDate and @AsOfDate
      and t.accountcode = cg.accountCode)
    from groups as g,chartGroup as cg,chart as c
    where g.groupCode = cg.GroupCode
    and g.groupCode = @GroupCode
    and cg.AccountCode = c.AccountCode
    order by g.GroupCode asc,cg.AccountCode asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_GroupNotes_pl" IS 
{create procedure Saller.r_GroupNotes_pl(@GroupCode varchar(10),@startDate date,@AsOfDate date) as
begin
