create procedure saller.r_item_wise_stock_tracking( @style char(1),@city varchar(64),@startDate datetime,@endDate datetime ) 
as
begin
  if @style = '1'
    begin
      --- combine the whole result
      select t.city,t.itemCode,t.itemName,opening=isnull(sum(t.opening),0),
        totalSale=isnull(sum(t.sales),0),totalPurchase=isnull(sum(t.purchase),0),
        totalPR=isnull(sum(t.purchaseReturn),0),totalSR=isnull(sum(t.salereturn),0)
        --- Get the Opening Balances
        ---- get the Opening Sale Quantity from the SaleInvoiceheader
        --- get the Opening SaleReturn
        --- get the Opening PurchaseRetrun
        ---- get the Total Sale Quantity from the SaleInvoiceheader
        --- get the Total Purchase Quantity
        --- get the Total SaleReturn
        --- get the total PurchaseRetrun
        from(select sh.city,sd.itemCode,sd.itemName,opening=-isnull(sum(sd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from saleInvoiceHeader as sh key join saleInvoiceDetail as sd
            where sh.InvoiceDate < @startDate
            group by sh.city,sd.itemCode,sd.itemName union all
          select ph.applyTo,pd.itemCode,pd.itemName,opening=isnull(sum(pd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from purchaseHeader as ph key join purchaseDetail as pd
            where ph.PurchaseInvoiceDate < @startDate
            group by ph.applyTo,pd.itemCode,pd.itemName union all
          select srh.city,srd.itemCode,srd.itemName,opening=isnull(sum(srd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from SrHeader as srh key join SrDetail as srd
            where srh.SrDate < @startDate
            group by srh.city,srd.itemCode,srd.itemName union all
          select prh.applyto,prd.itemCode,prd.itemName,opening=-isnull(sum(prd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from PrHeader as prh key join PrDetail as prd
            where prh.PrDate < @startDate
            group by prh.applyto,prd.itemCode,prd.itemName union all
          select sh.city,sd.itemCode,sd.itemName,opening=0,
            sales=sum(sd.quantity),purchase=0,purchasereturn=0,salereturn=0
            from saleInvoiceHeader as sh key join saleInvoiceDetail as sd
            where sh.InvoiceDate between @startDate and @endDate
            group by sh.city,sd.itemCode,sd.itemName union all
          select ph.applyTo,pd.itemCode,pd.itemName,opening=0,
            sales=0,purchase=sum(pd.quantity),purchasereturn=0,salereturn=0
            from purchaseHeader as ph key join purchaseDetail as pd
            where ph.PurchaseInvoiceDate between @startDate and @endDate
            group by ph.applyTo,pd.itemCode,pd.itemName union all
          select srh.city,srd.itemCode,srd.itemName,opening=0,
            sales=0,purchase=0,purchasereturn=0,salereturn=sum(srd.quantity)
            from SrHeader as srh key join SrDetail as srd
            where srh.SrDate between @startDate and @endDate
            group by srh.city,srd.itemCode,srd.itemName union all
          select prh.applyto,prd.itemCode,prd.itemName,opening=0,
            sales=0,purchase=0,purchasereturn=sum(prd.quantity),salereturn=0
            from PrHeader as prh key join PrDetail as prd where prh.PrDate between @startDate and @endDate
            group by prh.applyto,prd.itemCode,prd.itemName) as t
        group by t.city,t.itemCode,t.itemName
        order by 1 asc,2 asc
    end
  if @style = '2'
    begin
      --- combine the whole result
      select t.city,t.itemCode,t.itemName,opening=isnull(sum(t.opening),0),
        totalSale=isnull(sum(t.sales),0),totalPurchase=isnull(sum(t.purchase),0),
        totalPR=isnull(sum(t.purchaseReturn),0),totalSR=isnull(sum(t.salereturn),0)
        --- Get the Opening Balances
        ---- get the Opening Sale Quantity from the SaleInvoiceheader
        --- get the Opening Purchase Quantity
        --- get the Opening SaleReturn
        --- get the Opening PurchaseRetrun
        ---- get the Total Sale Quantity from the SaleInvoiceheader
        --- get the Total Purchase Quantity
        --- get the Total SaleReturn
        --- get the total PurchaseRetrun
        from(select sh.city,sd.itemCode,sd.itemName,opening=-isnull(sum(sd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from saleInvoiceHeader as sh key join saleInvoiceDetail as sd
            where sh.city = @city and sh.InvoiceDate < @startDate
            group by sh.city,sd.itemCode,sd.itemName union all
          select ph.applyTo,pd.itemCode,pd.itemName,opening=isnull(sum(pd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from purchaseHeader as ph key join purchaseDetail as pd
            where ph.applyTo = @city and ph.PurchaseInvoiceDate < @startDate
            group by ph.applyTo,pd.itemCode,pd.itemName union all
          select srh.city,srd.itemCode,srd.itemName,opening=isnull(sum(srd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from SrHeader as srh key join SrDetail as srd
            where srh.city = @city and srh.SrDate < @startDate
            group by srh.city,srd.itemCode,srd.itemName union all
          select prh.applyto,prd.itemCode,prd.itemName,opening=-isnull(sum(prd.quantity),0),
            sales=0,purchase=0,purchasereturn=0,salereturn=0
            from PrHeader as prh key join PrDetail as prd
            where prh.applyto = @city and prh.PrDate < @startDate
            group by prh.applyto,prd.itemCode,prd.itemName union all
          select sh.city,sd.itemCode,sd.itemName,opening=0,
            sales=sum(sd.quantity),purchase=0,purchasereturn=0,salereturn=0
            from saleInvoiceHeader as sh key join saleInvoiceDetail as sd
            where sh.city = @city and sh.InvoiceDate between @startDate and @endDate
            group by sh.city,sd.itemCode,sd.itemName union all
          select ph.applyTo,pd.itemCode,pd.itemName,opening=0,
            sales=0,purchase=sum(pd.quantity),purchasereturn=0,salereturn=0
            from purchaseHeader as ph key join purchaseDetail as pd
            where ph.applyTo = @city and ph.PurchaseInvoiceDate between @startDate and @endDate
            group by ph.applyTo,pd.itemCode,pd.itemName union all
          select srh.city,srd.itemCode,srd.itemName,opening=0,
            sales=0,purchase=0,purchasereturn=0,salereturn=sum(srd.quantity)
            from SrHeader as srh key join SrDetail as srd
            where srh.city = @city and srh.SrDate between @startDate and @endDate
            group by srh.city,srd.itemCode,srd.itemName union all
          select prh.applyto,prd.itemCode,prd.itemName,opening=0,
            sales=0,purchase=0,purchasereturn=sum(prd.quantity),salereturn=0
            from PrHeader as prh key join PrDetail as prd
            where prh.applyto = @city and prh.PrDate between @startDate and @endDate
            group by prh.applyto,prd.itemCode,prd.itemName) as t
        group by t.city,t.itemCode,t.itemName
        order by 1 asc,2 asc
    end
end
go

