create procedure saller.uf_getPreviosBalance( @document_no integer ) 
as
begin
  declare @balance T_AMOUNT,
  @cashAmount T_AMOUNT,
  @doc_date date,
  @partycode varchar(6),
  @periodid varchar(10)
  select @doc_date = invoicedate,@partycode = partycode
    from saleinvoiceheader
    where saleinvoicecode = @document_no
  select @periodid = year
    from fiscalyears where @doc_date between startdate and enddate
  select @cashAmount = isnull(openingdr,0)-isnull(openingcr,0)
    from openingbalances
    where accountcode = @partyCode
    and periodid = @periodid
  if @CashAmount is null
    select @CashAmount = 0
  select @balance = isnull(sum(debit),0)-isnull(sum(credit),0)
    from voucher
    where accountcode = @partycode
    and voucherdate < @doc_date
  select @balance = @balance+@cashAmount
  return(@balance)
end
go

