  @doc_date date,
  @partycode varchar(6),
  @periodid varchar(10)
  select @doc_date=invoicedate,@partycode=partycode from
    saleinvoiceheader where
    saleinvoicecode=@document_no

  select @periodid=year from
    fiscalyears where @doc_date between startdate and enddate
  

  select @cashAmount=isnull(openingdr,0)-isnull(openingcr,0) from
