create procedure saller.r_voucher_activity( @startDate date,@endDate date ) 
as /* RESULT( column_name column_type, ... ) */
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  declare @OpeningBalance T_Amount,
  @ClosingBalance T_Amount,
  @CashAccount T_AccountCode
  select @CashAccount = caShAccount from productControl
  select
    @openingBalance = (select isnull(op.openingdr,0)-isnull(op.openingcr,0)
      from openingbalances as op where op.accountcode = @CashAccount and op.periodid = @PeriodID)
    +(select isnull(sum(t.debit),0)-isnull(sum(t.credit),0) from voucher as t
      where t.voucherdate < @startdate
      and t.accountcode = @CashAccount and t.voucherdate between @startfiscaldate and @endfiscaldate)
  -- Select the closing balance 
  select @closingBalance = isnull(sum(v.debit),0)-isnull(sum(v.credit),0)
    from voucher as v
    where v.voucherdate between @startdate and @enddate
    and v.accountcode = @cashAccount
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Journal',v.documentname,v.documentno
    from voucher as v join chart as c
      on v.accountcode = c.accountcode
    where v.voucherdate between @startDate and @endDate
    and v.vouchertype = 'JVR' union all
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Payments',v.documentname,v.documentno
    from voucher as v join chart as c
      on v.accountcode = c.accountcode
    where v.voucherdate between @startDate and @endDate
    and v.vouchertype in( 'CPV','BPV' ) union all
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Receipts',v.documentname,v.documentno
    from voucher as v join chart as c
      on v.accountcode = c.accountcode
    where v.voucherdate between @startDate and @endDate
    and v.vouchertype in( 'CRV','BRV' ) 
end
go

