  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid=year,@startfiscaldate=startdate,@endfiscaldate=enddate from
    fiscalyears where @startdate between startdate and enddate
  declare @OpeningBalance T_AMOUNT,
  @ClosingBalance T_AMOUNT,
  @CashAccount T_ACCOUNTCODE
  select @CashAccount=caShAccount from productControl
  select
    @openingBalance=(select isnull(op.openingdr,0)-isnull(op.openingcr,0) from
      openingbalances as op where op.accountcode=@CashAccount and op.periodid=@PeriodID)
    +(select isnull(sum(t.debit),0)-isnull(sum(t.credit),0) from voucher as t where
      t.voucherdate<@startdate
      and t.accountcode=@CashAccount and t.voucherdate between @startfiscaldate and @endfiscaldate)
  -- Select the closing balance 
  select @closingBalance=isnull(sum(v.debit),0)-isnull(sum(v.credit),0) from
    voucher as v where
    v.voucherdate between @startdate and @enddate
    and v.accountcode=@cashAccount
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Journal',v.documentname,v.documentno from
    voucher as v join chart as c on
    v.accountcode=c.accountcode where
    v.voucherdate between @startDate and @endDate
    and v.vouchertype='JVR' union all
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Payments',v.documentname,v.documentno from
    voucher as v join chart as c on
    v.accountcode=c.accountcode where
    v.voucherdate between @startDate and @endDate
    and v.vouchertype in('CPV','BPV') union all
  select @openingBalance,@openingBalance+@closingBalance,v.vouchertype,v.voucherid,v.voucherdate,v.narration,v.seqno,v.accountcode,
    v.debit,v.credit,c.accountname,category='Receipts',v.documentname,v.documentno from
    voucher as v join chart as c on
    v.accountcode=c.accountcode where
    v.voucherdate between @startDate and @endDate
    and v.vouchertype in('CRV','BRV')
end
}
go

create procedure saller.p_ledger_detail( @DocumentType varchar(3),@InvoiceNo varchar(8) ) as
begin
  if @DocumentType = 'SL'
    select sih.documentno,sih.discountamount,sih.netamount,
      sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,sid.amount,
      sid.discountrate,sid.discountamount,sid.Totalamount,sid.measuringunit
      from SaleInvoiceHeader as sih join SaleInvoiceDetail as sid
        on sih.saleinvoicecode = sid.saleinvoicecode
      where sih.saleinvoicecode = @InvoiceNo
  if @DocumentType = 'SR'
    select sih.documentno,sih.discountamount,sih.netamount,
      sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,sid.amount,
      sid.discountrate,sid.discountamount,sid.totalamount,sid.measuringunit
      from SRHeader as sih join SRDetail as sid
        on sih.srno = sid.srno
      where sih.srno = @InvoiceNo
  if @DocumentType = 'PU'
    select pih.documentno,pih.discountamount,pih.netamount,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.purchaserate,pid.amount,
      pid.discountrate,pid.discountamount,pid.totalamount,pid.measuringunit
      from PurchaseHeader as pih join PurchaseDetail as pid
        on pih.purchaseInvoicecode = pid.purchaseInvoicecode
      where pih.purchaseInvoicecode = @InvoiceNo
  if @DocumentType = 'PR'
    select pih.documentno,pih.discountamount,pih.netamount,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.purchaserate,pid.amount,
      pid.discountrate,pid.discountamount,pid.netamount,pid.measuringunit
      from PrHeader as pih join PrDetail as pid
        on pih.prno = pid.prNo
      where pih.prno = @InvoiceNo
  if @DocumentType = 'SI'
    select pih.documentno,pih.discountamount,pih.netamount,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.salerate,pid.amount,
      pid.discountrate,pid.discountamount,pid.totalamount,pid.measuringunit
      from InwardHeader as pih join InwardDetail as pid
        on pih.InwardNo = pid.InwardNo
      where pih.InwardNo = @InvoiceNo
end
go

