create procedure SALLER.p_general_ledger( @groupcode varchar(32),@startdate date,@enddate date,@startcode varchar(14),@endcode varchar(14),@style char(1) ) 
as
begin
  if @style = 0
    begin
      select c.accountcode,c.accountname,vouchertype='',voucherid='00000000',voucherdate='1900-01-01',narration='Opening Balance',
        openingbalance=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),
        totaldr=0,totalcr=0,documentno=null,documentname=null
        from chart as c join voucher as v
          on c.accountcode = v.accountcode
        where v.voucherdate < @startdate
        and c.accountcode between @startcode and @endcode
        group by c.accountcode,c.accountname union all
      select c.accountcode,c.accountname,v.vouchertype,v.voucherid,v.voucherdate,
        v.narration,openingbalance=0,isnull(v.debit,0),isnull(v.credit,0),v.documentno,v.documentname
        from chart as c join voucher as v
          on c.accountcode = v.accountcode
        where c.accountcode between @startcode and @endcode
        and v.voucherdate between @startdate and @enddate
        order by 1 asc,5 asc,4 asc,3 asc
    end
  if @style = 1
    begin
      select c.accountcode,c.accountname,vouchertype='',voucherid='00000000',voucherdate='1900-01-01',narration='Opening Balance',
        openingbalance=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),
        totaldr=0,totalcr=0,documentno=null,documentname=null
        from chart as c join voucher as v
          on c.accountcode = v.accountcode
        where v.voucherdate < @startdate
        and c.accountcode = any(select accountcode from chartgroup where groupcode = @groupcode)
        group by c.accountcode,c.accountname union all
      select c.accountcode,c.accountname,v.vouchertype,v.voucherid,v.voucherdate,
        v.narration,openingbalance=0,isnull(v.debit,0),isnull(v.credit,0),v.documentno,v.documentname
        from chart as c join voucher as v
          on c.accountcode = v.accountcode
        where c.accountcode = any(select accountcode from chartgroup where groupcode = @groupcode)
        and v.voucherdate between @startdate and @enddate
        order by 1 asc,5 asc,4 asc,3 asc
    end
end
go

