create procedure Saller.r_composition_casting( @startcode varchar(32),@endcode varchar(32) ) 
as /* RESULT ( column-name,... ) */
begin
  select cih.itemcode,cih.itemname,
    cid.seqno,cid.itemcode,cid.itemname,cid.measuringunit,cid.quantity,
    cid.wastagerate,purchase_rate=(select p.purchaserate from purchasedetail as p join(select itemcode,doc_no=max(purchaseinvoicecode) from purchasedetail group by itemcode) as g
        on p.itemcode = g.itemcode
        and p.purchaseinvoicecode = g.doc_no
        and p.itemcode = cid.itemcode)
    from compositionheader as cih join compositiondetail as cid
      on cih.compcode = cid.compcode
    where cih.itemcode between @startcode and @endcode union all
  select i.itemcode,i.itemname,seqno=998,itemcode=null,itemname='Direct Labour',measuringunit=null,quantity=1,
    wastagerate=0,purchase_rate=i.directlabour from iteminformation as i
    where i.itemcode between @startcode and @endCode union all
  select i.itemcode,i.itemname,seqno=999,itemcode=null,itemname='Factory Overhead',measuringunit=null,quantity=1,
    wastagerate=0,purchase_rate=i.factoryOH from iteminformation as i
    where i.itemcode between @startcode and @endCode
end
go

