create procedure saller.R_INVENTORY_ALL( @style varchar(1),@group varchar(14),@START_CODE varchar(32),@END_CODE varchar(32),@START_DATE date,@END_DATE date,@DEPARTMENT varchar(32) ) 
as
begin
  declare @Start_dept varchar(32),
  @End_dept varchar(32)
  if @DEPARTMENT = '<ALL>'
    select @Start_dept = '0',@End_dept = 'zzzzz'
  else
    select @Start_dept = @DEPARTMENT,@End_dept = @DEPARTMENT
  if @style = '0'
    select T.ITEM_ID,
      T.ITEM_INFO,
      T.DEPTID,
      OPENING_QTY=SUM(T.OPENING_QTY),
      GRN_QUANTITY=SUM(T.GRN_QTY),
      SR_QUANTITY=SUM(T.SR_QTY),
      SI_QUANTITY=SUM(T.SALE_QTY),
      PR_QUANTITY=SUM(T.PR_QTY),
      ISSUE_QUANTITY=SUM(T.ISSUE_QTY),
      RECEIPT_QUANTITY=SUM(T.INWARD_REC_QTY),
      DPR_QUANTITY=SUM(T.DPR_QTY),
      CONSUMED_QUANTITY=SUM(T.CONSUMED_QTY),
      ADJUST_QUANTITY=SUM(T.UNDPR_QTY),
      T.PURCHASERATE
      from(select T.ITEM_ID,
          ITEM_INFO=I.ITEMNAME,T.DEPTID,
          OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
          -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
          GRN_QTY=0,
          SR_QTY=0,
          SALE_QTY=0,
          PR_QTY=0,
          ISSUE_QTY=0,
          INWARD_REC_QTY=0,
          DPR_QTY=0,
          CONSUMED_QTY=0,UNDPR_QTY=0,I.PURCHASERATE
          from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
            on T.ITEM_ID = I.ITEMCODE
          where T.ITEM_ID between @START_CODE and @END_CODE and I.status = '1'
          and T.DEPTID between @START_DEPT and @END_DEPT
          and T.DOCUMENT_DATE < @START_DATE union all
        select T.ITEM_ID,
          ITEM_INFO=I.ITEMNAME,T.DEPTID,
          T.OPENING_QTY,
          T.GRN_QTY,T.SR_QTY,
          T.SALE_QTY,T.PR_QTY,
          T.ISSUE_QTY,INWARD_REC_QTY,T.DPR_QTY,T.CONSUMED_QTY,T.UNDPR_QTY,I.PURCHASERATE
          from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
            on T.ITEM_ID = I.ITEMCODE
          where T.ITEM_ID between @START_CODE and @END_CODE
          and T.DEPTID between @START_DEPT and @END_DEPT and I.status = '1'
          and T.DOCUMENT_DATE between @START_DATE and @END_DATE) as T
      group by T.ITEM_ID,T.ITEM_INFO,T.DEPTID,T.PURCHASERATE
  if @style = '1'
    select T.ITEM_ID,
      T.ITEM_INFO,
      T.DEPTID,
      OPENING_QTY=SUM(T.OPENING_QTY),
      GRN_QUANTITY=SUM(T.GRN_QTY),
      SR_QUANTITY=SUM(T.SR_QTY),
      SI_QUANTITY=SUM(T.SALE_QTY),
      PR_QUANTITY=SUM(T.PR_QTY),
      ISSUE_QUANTITY=SUM(T.ISSUE_QTY),
      RECEIPT_QUANTITY=SUM(T.INWARD_REC_QTY),
      DPR_QUANTITY=SUM(T.DPR_QTY),
      CONSUMED_QUANTITY=SUM(T.CONSUMED_QTY),
      ADJUST_QUANTITY=SUM(T.UNDPR_QTY),
      T.PURCHASERATE
      from(select T.ITEM_ID,
          ITEM_INFO=I.ITEMNAME,T.DEPTID,
          OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
          -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
          GRN_QTY=0,
          SR_QTY=0,
          SALE_QTY=0,
          PR_QTY=0,
          ISSUE_QTY=0,
          INWARD_REC_QTY=0,
          DPR_QTY=0,
          CONSUMED_QTY=0,UNDPR_QTY=0,I.PURCHASERATE
          from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
            on T.ITEM_ID = I.ITEMCODE
          where T.ITEM_ID = any(select itemcode from itemgroupdetail where groupcode = @group)
          and T.DEPTID between @START_DEPT and @END_DEPT and I.status = '1'
          and T.DOCUMENT_DATE < @START_DATE union all
        select T.ITEM_ID,
          ITEM_INFO=I.ITEMNAME,T.DEPTID,
          T.OPENING_QTY,
          T.GRN_QTY,T.SR_QTY,
          T.SALE_QTY,T.PR_QTY,
          T.ISSUE_QTY,INWARD_REC_QTY,T.DPR_QTY,T.CONSUMED_QTY,T.UNDPR_QTY,I.PURCHASERATE
          from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
            on T.ITEM_ID = I.ITEMCODE
          where T.ITEM_ID = any(select itemcode from itemgroupdetail where groupcode = @group)
          and T.DEPTID between @START_DEPT and @END_DEPT and I.status = '1'
          and T.DOCUMENT_DATE between @START_DATE and @END_DATE) as T
      group by T.ITEM_ID,T.ITEM_INFO,T.DEPTID,T.PURCHASERATE
end
go

