create procedure saller.R_ITEM_LEDGER( @START_CODE varchar(32),@END_CODE varchar(32),@START_DATE date,@END_DATE date,@DEPARTMENT varchar(10) ) 
as
begin
  declare @Start_dept varchar(32),
  @End_dept varchar(32)
  if @DEPARTMENT = '<ALL>'
    select @Start_dept = '0',@End_dept = 'zzzzzz'
  else
    select @Start_dept = @DEPARTMENT,@End_dept = @DEPARTMENT
  select T.ITEM_ID,
    T.ITEM_INFO,
    T.DEPTID,T.DOCUMENT_DATE,T.DOCUMENT_NO,T.DOCUMENT_NAME,
    IN_QTY=SUM(T.OPENING_QTY)+SUM(T.GRN_QTY)+SUM(T.SR_QTY)+SUM(T.DPR_QTY)+SUM(T.INWARD_REC_QTY)+SUM(T.UNDPR_QTY),
    OUT_QTY=SUM(T.SALE_QTY)+SUM(T.PR_QTY)+SUM(T.ISSUE_QTY)+SUM(T.CONSUMED_QTY)
    from(select T.ITEM_ID,
        ITEM_INFO=I.ITEMNAME,
        DEPTID=T.DEPTID,DOCUMENT_DATE=null,DOCUMENT_NO=null,DOCUMENT_NAME='OPENING STOCK',
        OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
        -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
        GRN_QTY=0,
        SR_QTY=0,
        SALE_QTY=0,
        PR_QTY=0,
        ISSUE_QTY=0,DPR_QTY=0,
        CONSUMED_QTY=0,INWARD_REC_QTY=0,UNDPR_QTY=0
        from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
          on T.ITEM_ID = I.ITEMCODE
        where T.ITEM_ID between @START_CODE and @END_CODE and I.status = '1'
        and T.DOCUMENT_DATE < @START_DATE and T.DEPTID between @START_DEPT and @END_DEPT union all
      select T.ITEM_ID,
        ITEM_INFO=I.ITEMNAME,T.DEPTID,T.DOCUMENT_DATE,T.DOCUMENT_NO,DOCUMENT_NAME,
        T.OPENING_QTY,
        T.GRN_QTY,T.SR_QTY,
        T.SALE_QTY,T.PR_QTY,
        T.ISSUE_QTY,T.DPR_QTY,
        T.CONSUMED_QTY,T.INWARD_REC_QTY,T.UNDPR_QTY
        from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
          on T.ITEM_ID = I.ITEMCODE
        where T.ITEM_ID between @START_CODE and @END_CODE and I.status = '1'
        and T.DOCUMENT_DATE between @START_DATE and @END_DATE and T.DEPTID between @START_DEPT and @END_DEPT) as T
    group by T.ITEM_ID,T.ITEM_INFO,T.DEPTID,T.DOCUMENT_DATE,T.DOCUMENT_NO,T.DOCUMENT_NAME
end
go

