create procedure saller.r_citywise_purchase( @style char(1),@City varchar(32),@startDate DATETIME,@enddate DATETIME ) 
as
begin
  if @style = '1' --select all the sale
    select PurchaseInvoiceCode,purchaseInvoicedate,partycode,name,city,discountamount,netamount
      from Purchaseheader
      where PurchaseInvoiceDate >= @startdate
      and PurchaseInvoiceDate <= @enddate
  if @style = '2' --filter city wise
    select PurchaseInvoiceCode,purchaseInvoicedate,partycode,name,city,discountamount,netamount
      from Purchaseheader
      where PurchaseInvoiceDate >= @startdate
      and PurchaseInvoiceDate <= @enddate and city = @city
end
go

