as
begin
  if @style='1' --select all the sale
    select PurchaseInvoiceCode,purchaseInvoicedate,partycode,name,city,discountamount,netamount from
      Purchaseheader where
      PurchaseInvoiceDate>=@startdate
      and PurchaseInvoiceDate<=@enddate
  if @style='2' --filter city wise
    select PurchaseInvoiceCode,purchaseInvoicedate,partycode,name,city,discountamount,netamount from
      Purchaseheader where
      PurchaseInvoiceDate>=@startdate
      and PurchaseInvoiceDate<=@enddate and city=@city
  
end
}
