  ----- Set the item name and item type in complete receipes table -----------------  
  update complete_receipe as t,iteminformation as i set
    t.item_name=i.itemname,
    t.class=i.itemtype where
    t.item_id=i.itemcode
  update complete_receipe set
    expanded='0' where
    class='O'
    and expanded='-1'
  select @counter=isNull(count(expanded),0) from
    complete_receipe where
    expanded='0'
  while(@counter>0)
    begin
      -- Get the Item ID from receipe to expand  
      select top 1 @item_id=item_id,@levelno=levelno+1 from
        complete_receipe where
        class='O'
        and expanded='0'
      select @directLabour=isNull(i.DirectLabour,0),
        @factoryOH=isNull(i.FactoryOH,0),
        @itemName=i.itemname from
        ItemInformation as i join compositionheader as ir on
        i.itemcode=ir.itemcode where
        ir.itemcode=@item_id
      -- calcualte and insert the receipe of current item id  
      insert into complete_receipe
        select h.itemcode,h.itemname,d.seqno,d.itemcode,null,
          d.quantity+(d.quantity*d.WastageRate/100),null,-1,null,@levelno from
          compositionheader as h join compositiondetail as d on
          h.compcode=d.compcode where
          h.itemcode=@item_id
      insert into complete_receipe
        select @item_Id,@itemName,9998,null,'Direct Labour',
          1,'D',-1,@directLabour,@levelno
      insert into complete_receipe
        select @item_Id,@itemName,9999,null,'FactoryOH',
          1,'H',-1,@factoryOH,@levelno
      update complete_receipe as t,iteminformation as i set
        t.item_name=i.itemname,
        t.class=i.itemtype where
        t.item_id=i.itemcode
        and t.item_name is null
      update complete_receipe set
        expanded='0' where
        class='O'
        and expanded='-1'
      ---- Make the expanded status of current item as expaneded  
      update complete_receipe set
        expanded='1' where
        item_id=@item_id
      ---- Check wheather to loop again or not  
      select @counter=isNull(count(expanded),0) from
        complete_receipe where
        expanded='0'
    end
  ---- Get the prices from the purchase table  
    update complete_receipe as t
    set t.purchase_price=isnull(d.purchaserate,0) from
    complete_receipe as t,
    (select p.itemcode,p.purchaserate from
      purchasedetail as p join(select itemcode,
        doc_no=max(purchaseinvoicecode) from purchasedetail group by itemcode) as g on
      p.itemcode=g.itemcode
      and p.purchaseinvoicecode=g.doc_no) as d where
    t.item_id=d.itemcode


 /* update t set
    t.purchase_price=isnull(d.purchase_rate,0) from
    complete_receipe as t,
    (select p.itemcode,p.purchaserate from
      purchasedetail as p join(select itemcode,
        doc_no=max(purchaseinvoicecode) from purchasedetail group by itemcode) as g on
      p.itemcode=g.itemcode
      and p.purchaseinvoicecode=g.doc_no) as d where
    t.item_id=d.itemcode*/
  --- update the prices of the products for whom purchase price is not available
  update complete_receipe as t,iteminformation as d set
    t.purchase_price=isNull(d.purchaserate,0) where
    t.item_id=d.itemcode
    and t.purchase_price is null
   -- and t.class='O'
  ---- Sum up the prices   
  begin
    declare @parent_item_id T_PRODUCT_ID,
    @PURCHASE_PRICE T_AMOUNT


  declare childsum cursor  
  for select parent_item_id, item_id, purchase_price, levelno from  
  complete_receipe where class = 'O'  
  order by levelno desc  

  open childsum
  
  fetch next childsum into @parent_item_id, @item_id, @purchase_price, @levelno  

  while @@fetch_status = 0  
  begin  

  update complete_receipe t  
  set t.purchase_price = (select isnull(sum(c.purchase_price * c.quantity),0) from complete_receipe c  
  where c.levelno > t.levelno and  
  c.parent_item_id = t.item_id)  
  from complete_receipe t  
  where t.parent_item_id = @parent_item_id and  
  t.item_id = @item_id and  
  t.levelno = @levelno  
  

  fetch next childsum into @parent_item_id, @item_id, @purchase_price, @levelno  
  end  

  close childsum  
  deallocate childsum 
  end
end
