create procedure saller.r_department_wise_production( @START_CODE varchar(32),@END_CODE varchar(32),@START_DATE date,@END_DATE date,@DEPARTMENT varchar(32) ) 
as
begin
  select sih.deptid,sid.itemcode,sid.itemtype,sid.itemname,qty=sum(sid.quantity)
    from dprheader as sih join dprdetail as sid on sih.dprcode = sid.dprcode
    where sih.dprdate between @start_date and @end_date
    and sid.itemcode between @start_code and @end_code
    and sih.deptid = @department
    group by sih.deptid,sid.itemcode,sid.itemtype,sid.itemname
    order by sid.itemcode asc,sid.itemname asc
end
go

COMMENT ON PROCEDURE "saller"."r_department_wise_production" IS 
	'Procedure For Department Wise Production'
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_department_wise_production" IS 
{create PROCEDURE saller."r_department_wise_production"( @START_CODE varchar(32),@END_CODE varchar(32),@START_DATE date,@END_DATE date,@DEPARTMENT varchar(32) )
AS
BEGIN
    select sih.deptid,sid.itemcode,sid.itemtype,sid.itemname,qty=sum(sid.quantity)
    from  dprheader as sih inner join dprdetail as sid on sih.dprcode = sid.dprcode 
    where sih.dprdate between @start_date and @end_date and
          sid.itemcode between @start_code and @end_code and
          sih.deptid = @department
    group by sih.deptid,sid.itemcode,sid.itemtype,sid.itemname
    order by sid.itemcode asc,sid.itemname asc
   END
}
