COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."department_wise_material_issue" IS 
{create PROCEDURE saller."department_wise_material_issue"( @START_CODE varchar(32),@END_CODE varchar(32),@START_DATE date,@END_DATE date,@DEPARTMENT varchar(32) )
AS
BEGIN
    select sih.deptid,sid.itemcode,sid.itemtype,sid.itemname,qty=sum(sid.quantity)
    from  MaterialIssueNoteHeader as sih inner join MaterIssueNoteDetail as sid on sih.mincode = sid.mincode 
    where sih.mindate between @start_date and @end_date and
          sid.itemcode between @start_code and @end_code and
          sih.deptid = @department
    group by sih.deptid,sid.itemcode,sid.itemtype,sid.itemname
    order by sid.itemcode asc,sid.itemname asc
   END
}
go

create procedure saller.R_DEPT_WISE_SALE( @START_DATE date,@END_DATE date,@START_CODE varchar(32),@END_CODE varchar(32),@DEPTID varchar(10) ) 
as
begin
  select D.ITEMCODE,D.ITEMNAME,
    LAHROE=SUM(case H.DEPTID when '01' then D.QUANTITY else 0 end),
    MULTAN=SUM(case H.DEPTID when '02' then D.QUANTITY else 0 end),
    FAISALABAD=SUM(case H.DEPTID when '03' then D.QUANTITY else 0 end),
    HAYDERABAD=SUM(case H.DEPTID when '04' then D.QUANTITY else 0 end),
    KARACHI=SUM(case H.DEPTID when '05' then D.QUANTITY else 0 end),
    QUETTA=SUM(case H.DEPTID when '06' then D.QUANTITY else 0 end),
    RAWALPINDI=SUM(case H.DEPTID when '07' then D.QUANTITY else 0 end),
    PESHAWAR=SUM(case H.DEPTID when '08' then D.QUANTITY else 0 end),
    MAINGODOWN=SUM(case H.DEPTID when '09' then D.QUANTITY else 0 end),
    RAWMATERIALGODOWN=SUM(case H.DEPTID when '10' then D.QUANTITY else 0 end),
    SOUTH=SUM(case H.DEPTID when '11' then D.QUANTITY else 0 end),
    NORTH=SUM(case H.DEPTID when '12' then D.QUANTITY else 0 end),
    FACTORY=SUM(case H.DEPTID when '13' then D.QUANTITY else 0 end),DEPTID
    from SALEINVOICEHEADER as H key join SALEINVOICEDETAIL as D
      on H.SALEINVOICECODE = D.SALEINVOICECODE
    where H.INVOICEDATE between @START_DATE and @END_DATE
    and H.DEPTID = @DEPTID
    and D.ITEMCODE between @START_CODE and @END_CODE
    group by D.ITEMCODE,D.ITEMNAME,DEPTID
    order by D.ITEMCODE asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_DEPT_WISE_SALE" IS 
{create PROCEDURE saller."R_DEPT_WISE_SALE" @START_DATE DATE, @END_DATE DATE , @START_CODE VARCHAR(32), @END_CODE VARCHAR(32),@DEPTID VARCHAR(10)
AS
BEGIN

SELECT D.ITEMCODE, D.ITEMNAME, 
        SUM( CASE H.DEPTID WHEN '01' THEN D.QUANTITY ELSE 0 END ) AS LAHROE,
        SUM( CASE H.DEPTID WHEN '02' THEN D.QUANTITY ELSE 0 END ) AS MULTAN,
        SUM( CASE H.DEPTID WHEN '03' THEN D.QUANTITY ELSE 0 END ) AS FAISALABAD,
        SUM( CASE H.DEPTID WHEN '04' THEN D.QUANTITY ELSE 0 END ) AS HAYDERABAD,
        SUM( CASE H.DEPTID WHEN '05' THEN D.QUANTITY ELSE 0 END ) AS KARACHI,
        SUM( CASE H.DEPTID WHEN '06' THEN D.QUANTITY ELSE 0 END ) AS QUETTA,
        SUM( CASE H.DEPTID WHEN '07' THEN D.QUANTITY ELSE 0 END ) AS RAWALPINDI,
        SUM( CASE H.DEPTID WHEN '08' THEN D.QUANTITY ELSE 0 END ) AS PESHAWAR,
        SUM( CASE H.DEPTID WHEN '09' THEN D.QUANTITY ELSE 0 END ) AS MAINGODOWN,
        SUM( CASE H.DEPTID WHEN '10' THEN D.QUANTITY ELSE 0 END ) AS RAWMATERIALGODOWN,
        SUM( CASE H.DEPTID WHEN '11' THEN D.QUANTITY ELSE 0 END ) AS SOUTH,
        SUM( CASE H.DEPTID WHEN '12' THEN D.QUANTITY ELSE 0 END ) AS NORTH,
        SUM( CASE H.DEPTID WHEN '13' THEN D.QUANTITY ELSE 0 END ) AS FACTORY,DEPTID
FROM SALEINVOICEHEADER AS H KEY JOIN SALEINVOICEDETAIL AS D on
        H.SALEINVOICECODE = D.SALEINVOICECODE
WHERE H.INVOICEDATE BETWEEN @START_DATE AND @END_DATE AND
        H.DEPTID = @DEPTID AND
        D.ITEMCODE BETWEEN @START_CODE AND @END_CODE
GROUP BY D.ITEMCODE, D.ITEMNAME,DEPTID
ORDER BY D.ITEMCODE

END
}
go

create procedure saller.r_citywise_sale_return( @style char(1),@City varchar(32),@startDate datetime,@enddate datetime ) 
as
begin
  if @style = '1' --select all the sale
    select srno,srdate,partycode,name,city,discountamount,netamount
      from srheader
      where srdate >= @startdate
      and srdate <= @enddate
  if @style = '2' --filter city wise  
    select srno,srdate,partycode,name,city,discountamount,netamount
      from srheader
      where city = @city
      and srdate >= @startdate
      and srdate <= @enddate
end
go

