create procedure saller.DELEAR_SALE_SUMMARY( @start_code varchar(14),@end_code varchar(14),@start_date date,@end_date date ) 
begin
  select sih.documentno,sih.saleinvoicecode,sih.invoicedate,sih.partycode,
    sih.name,sih.address,sih.city,sid.itemcode,max(sid.itemname),sid.quantity,sid.salerate,sid.discountrate,sid.discountamount,sid.amount,
    sih.netamount,isNull(sih.DeliverTo,'N/A') as Deliver_to
    from saleinvoiceheader as sih,saleinvoicedetail as sid
    where sih.saleinvoicecode = sid.saleinvoicecode
    and sih.partycode between @start_code and @end_code
    and sih.invoicedate between @start_date and @end_date
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."DELEAR_SALE_SUMMARY" IS 
{create PROCEDURE saller."DELEAR_SALE_SUMMARY"(@start_code varchar(14),@end_code varchar(14),@start_date date,@end_date date)
begin
  select sih.documentno,sih.saleinvoicecode,sih.invoicedate,sih.partycode,
    sih.name,sih.address,sih.city,sid.itemcode,max(sid.itemname),sid.quantity,sid.salerate,sid.discountrate,sid.discountamount,sid.amount,
    sih.netamount, isNull( sih.DeliverTo , 'N/A' ) as Deliver_to
from
    saleinvoiceheader as sih , saleinvoicedetail as sid 
where
    sih.saleinvoicecode=sid.saleinvoicecode and
    sih.partycode between @start_code and @end_code
    and sih.invoicedate between @start_date and @end_date
    
end
}
