create procedure saller.R_DEALER_SALE_SR_COMPARISION( @start_code varchar(11),@end_code varchar(11),@start_date date,@end_date date ) 
as
begin
  /*Author: Adil Sharif*/
  select T.PARTYCODE,T.NAME,T.ITEMCODE,T.ITEMNAME,SALE_QTY=SUM(T.SALE_QTY),SALE_RATE=MAX(T.SALERATE),
    SR_QTY=SUM(T.SR_QTY),SR_RATE=MAX(T.SR_RATE)
    from(select H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,SALE_QTY=D.QUANTITY,D.SALERATE,
        SR_QTY=0,SR_RATE=0
        from SALEINVOICEHEADER as H join SALEINVOICEDETAIL as D
          on H.SALEINVOICECODE = D.SALEINVOICECODE
        where H.PARTYCODE between @START_CODE and @END_CODE
        and H.INVOICEDATE between @START_DATE and @END_DATE union all
      select H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,SALE_QTY=0,SALERATE=0,
        SR_QTY=D.QUANTITY,SR_RATE=D.SALERATE
        from SRHEADER as H join SRDETAIL as D
          on H.SRNO = D.SRNO
        where H.PARTYCODE between @START_CODE and @END_CODE
        and H.SRDATE between @START_DATE and @END_DATE) as T
    group by T.PARTYCODE,T.NAME,T.ITEMCODE,T.ITEMNAME
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_DEALER_SALE_SR_COMPARISION" IS 
{create PROCEDURE saller."R_DEALER_SALE_SR_COMPARISION"(@start_code varchar(11),@end_code varchar(11),@start_date date,@end_date date)
AS
BEGIN
/*Author: Adil Sharif*/
SELECT T.PARTYCODE, T.NAME, T.ITEMCODE, T.ITEMNAME, SALE_QTY = SUM(T.SALE_QTY), SALE_RATE = MAX(T.SALERATE),   
 SR_QTY = SUM(T.SR_QTY), SR_RATE = MAX(T.SR_RATE)
FROM (
SELECT H.PARTYCODE, H.NAME, D.ITEMCODE, D.ITEMNAME , SALE_QTY = D.QUANTITY, D.SALERATE,
 SR_QTY = 0, SR_RATE = 0  
FROM SALEINVOICEHEADER AS H INNER JOIN SALEINVOICEDETAIL AS D ON    
 H.SALEINVOICECODE = D.SALEINVOICECODE    
WHERE H.PARTYCODE BETWEEN @START_CODE AND @END_CODE AND    
 H.INVOICEDATE BETWEEN @START_DATE AND @END_DATE 
UNION ALL
SELECT H.PARTYCODE,H.NAME, D.ITEMCODE, D.ITEMNAME , SALE_QTY = 0, SALERATE= 0,
 SR_QTY = D.QUANTITY, SR_RATE = D.SALERATE
FROM SRHEADER AS H INNER JOIN SRDETAIL AS D ON    
     H.SRNO = D.SRNO    
WHERE H.PARTYCODE BETWEEN @START_CODE AND @END_CODE AND 
 H.SRDATE BETWEEN @START_DATE AND @END_DATE  ) AS T 
GROUP BY T.PARTYCODE, T.NAME, T.ITEMCODE, T.ITEMNAME 


  


END
}
go

