create procedure saller.P_VOUCHER_NO( @YEAR integer,@MONTH integer,@NUMBER integer,
  @VOUCHER_NO varchar(8) output ) as
begin
  declare @YEAR_NO varchar(2),
  @MONTH_NO varchar(2),
  @DAY_NO varchar(2),
  @NO varchar(4)
  select @YEAR_NO = "RIGHT"(@YEAR,2)
  select @MONTH_NO = REPLICATE('0',2-LEN(convert(varchar(2),@MONTH)))+convert(varchar(2),@MONTH)
  select @DAY_NO = REPLICATE('0',2-LEN(convert(varchar(2),@MONTH)))+convert(varchar(2),@DAY)
  select @NO = REPLICATE('0',4-LEN(convert(varchar(4),@NUMBER)))+convert(varchar(4),@NUMBER)
  select @VOUCHER_NO = @YEAR_NO+@MONTH_NO+@DAY_NO+@NO
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."P_VOUCHER_NO" IS 
{create PROCEDURE saller."P_VOUCHER_NO" @YEAR INT , @MONTH INT , @NUMBER INT,@VOUCHER_NO VARCHAR(8) OUTPUT
AS
BEGIN
	DECLARE @YEAR_NO VARCHAR(2),
            @MONTH_NO VARCHAR(2),
            @DAY_NO  VARCHAR(2),
		@NO VARCHAR(4)
SELECT @YEAR_NO = RIGHT(@YEAR,2)
SELECT @MONTH_NO = REPLICATE('0',2 - LEN(CAST(@MONTH AS VARCHAR(2)))) + CAST(@MONTH AS VARCHAR(2))
SELECT @DAY_NO = REPLICATE('0',2 - LEN(CAST(@MONTH AS VARCHAR(2)))) + CAST(@DAY AS VARCHAR(2))
SELECT @NO = REPLICATE('0',4-LEN(CAST(@NUMBER AS VARCHAR(4)))) + CAST(@NUMBER AS VARCHAR(4))

SELECT @VOUCHER_NO = @YEAR_NO + @MONTH_NO + @DAY_NO + @NO

END
}
go

