create procedure saller.r_pending_saleorder( @startdate date,@endDate date ) 
as
begin
  select ih.saleorderno,ih.documentno,ih.invoicedate,ih.partycode,
    ih.name,ih.city,total_quantity=sum(invd.quantity),
    sale_qty=(select sum(isnull(d.quantity,0)) from saleinvoiceheader as h join saleinvoicedetail as d
        on h.saleinvoicecode = d.saleinvoicecode
        and h.saleorderno = ih.saleorderno)
    from saleorderheader as ih join saleorderdetail as invd
      on ih.saleorderno = invd.saleorderno
    where ih.invoicedate between @startdate and @enddate
    and ih.approved = '1' and status <> 'F'
    group by ih.saleorderno,ih.documentno,ih.invoicedate,ih.partycode,ih.name,ih.city
end
go

