create procedure saller.ITEM_LIST( @ASOFDATE date ) 
as /* RESULT ( column-name,... ) */
begin
  select STRING(T.ITEM_ID),STRING(T.ITEMNAME),T.ITEMTYPE,
    OPENING_QTY=SUM(isNull(T.OPENING_QTY,0.0)),MAX(T.DEPTID),T.SALERATE
    from(select T.ITEM_ID,I.ITEMNAME,
        OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
        -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
        I.ITEMTYPE,T.DEPTID,I.SALERATE from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I
          on T.ITEM_ID = I.ITEMCODE
          and T.DOCUMENT_DATE <= @ASOFDATE) as T
    group by T.ITEM_ID,T.ITEMNAME,T.ITEMTYPE,T.SALERATE
end
commit work
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."ITEM_LIST" IS 
{create PROCEDURE saller."ITEM_LIST"(@ASOFDATE date)
as /* RESULT ( column-name,... ) */
begin
  select STRING(T.ITEM_ID),STRING(T.ITEMNAME),T.ITEMTYPE,
    OPENING_QTY=SUM(isNull(T.OPENING_QTY,0.00)),MAX(T.DEPTID),T.SALERATE from
    (select T.ITEM_ID,I.ITEMNAME,
      OPENING_QTY=(T.OPENING_QTY+T.GRN_QTY+T.SR_QTY+T.DPR_QTY+T.INWARD_REC_QTY+T.UNDPR_QTY)
      -(T.SALE_QTY+T.PR_QTY+T.ISSUE_QTY+T.CONSUMED_QTY),
      I.ITEMTYPE,T.DEPTID,I.SALERATE from VIEW_INVENTORY_DEPT as T join ITEMINFORMATION as I on
      T.ITEM_ID = I.ITEMCODE and
      T.DOCUMENT_DATE <= @ASOFDATE) as T
    group by T.ITEM_ID,T.ITEMNAME,T.ITEMTYPE,T.SALERATE
end

 commit
}
