create procedure saller.r_vendorwise_payment( @style varchar(1),@group varchar(16),@startcode varchar(14),@endcode varchar(14),@startdate date,@enddate date ) 
as
begin
  if @style = '1'
    select v.voucherid,v.Narration,c.AccountCode,c.AccountName,c.city,v.Debit,v.voucherdate
      from Chart as c,voucher as v
      where c.AccountCode = v.AccountCode
      and c.AccountCategory = 'V'
      -- and v.DocumentName='JR'
      and v.Debit > 0
      and c.AccountCode between @startCode and @endcode
      and v.voucherdate between @startdate and @enddate order by c.accountcode asc,
      v.voucherid asc
end
go

