create procedure saller.R_POST_DATED_CHEQUE_SUMMARY( @CHEQUETYPE varchar(3),@START_DATE datetime,@END_DATE datetime,@accountcode varchar(10) ) 
as
begin
  if @CHEQUETYPE = 'BRV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      ISNULL(VA.CREDIT,0),DEBIT=0,VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2)
      from VOUCHER as VA join CHART as C
        on VA.ACCOUNTCODE = C.ACCOUNTCODE
      where VA.CHEQUEDATE is not null
      and VA.CHEQUEDATE between @START_DATE and @END_DATE
      and VA.ACCOUNTCODE2 = @ACCOUNTCODE
      and VA.CREDIT > 0 and VA.SEQNO = 1
      order by VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
  if @CHEQUETYPE = 'BPV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      CREDIT=0,ISNULL(VA.DEBIT,0),VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2)
      from VOUCHER as VA join CHART as C
        on VA.ACCOUNTCODE = C.ACCOUNTCODE
      where VA.CHEQUEDATE is not null
      and VA.CHEQUEDATE between @START_DATE and @END_DATE
      and VA.ACCOUNTCODE2 = @ACCOUNTCODE
      and VA.DEBIT > 0 and VA.SEQNO = 1
      order by VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_POST_DATED_CHEQUE_SUMMARY" IS 
{create PROCEDURE saller."R_POST_DATED_CHEQUE_SUMMARY"(@CHEQUETYPE varchar(3),@START_DATE datetime,@END_DATE datetime,@accountcode varchar(10))
as
begin
  if @CHEQUETYPE = 'BRV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      ISNULL(VA.CREDIT,0),DEBIT=0,VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2) from
      VOUCHER as VA join CHART as C on
      VA.ACCOUNTCODE = C.ACCOUNTCODE where
      VA.CHEQUEDATE is not null and
      VA.CHEQUEDATE between @START_DATE and @END_DATE 
      and VA.ACCOUNTCODE2=@ACCOUNTCODE
      and VA.CREDIT > 0 and VA.SEQNO = 1 order by
      VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
  if @CHEQUETYPE = 'BPV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      CREDIT=0,ISNULL(VA.DEBIT,0),VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2) from
      VOUCHER as VA join CHART as C on
      VA.ACCOUNTCODE = C.ACCOUNTCODE where
      VA.CHEQUEDATE is not null and
      VA.CHEQUEDATE between @START_DATE and @END_DATE
      and VA.ACCOUNTCODE2=@ACCOUNTCODE
      and VA.DEBIT > 0 and VA.SEQNO = 1 order by
      VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
end
}
