create procedure saller.r_dept_issue_vs_consumption( @start_code varchar(11),@end_code varchar(11),@start_date date,@end_date date,@DEPTID varchar(10) ) 
as
begin
  select T.CODE,T.DEPTID,T.ITEMCODE,T.ITEMNAME,MEASURINGUNIT=T.MEASURINGUNIT,ISSUE_QTY=SUM(T.ISSUE_QTY),
    CONSUMPTION_QTY=SUM(T.CONSUMPTION_QTY)
    from(select CODE=H.MINCODE,H.DEPTID,D.ITEMCODE,D.ITEMNAME,D.MEASURINGUNIT,ISSUE_QTY=D.QUANTITY,
        CONSUMPTION_QTY=0
        from MATERIALISSUENOTEHEADER as H join MATERISSUENOTEDETAIL as D
          on H.MINCODE = D.MINCODE
        where H.MINDATE between @START_DATE and @END_DATE
        and D.ITEMCODE between @START_CODE and @END_CODE
        and H.DEPTID = @DEPTID union all
      select CODE=H.CONSNOTECODE,H.DEPTID,D.ITEMCODE,D.ITEMNAME,MEASURINGUNIT='',ISSUE_QTY=0,
        CONSUMPTION_QTY=D.QUANTITY
        from CONSUMPTIONNOTEHEADER as H join CONSUMPTIONNOTEDETAIL as D
          on H.CONSNOTECODE = D.CONSNOTECODE
        where H.CONSNOTEDATE between @START_DATE and @END_DATE
        and D.ITEMCODE between @START_CODE and @END_CODE
        and H.DEPTID = @DEPTID) as T
    group by T.CODE,T.DEPTID,T.ITEMCODE,T.ITEMNAME,T.MEASURINGUNIT
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."r_dept_issue_vs_consumption" IS 
{create PROCEDURE saller."r_dept_issue_vs_consumption"(@start_code varchar(11),@end_code varchar(11),@start_date date,@end_date date,@DEPTID VARCHAR(10))
AS
BEGIN

SELECT T.CODE,T.DEPTID, T.ITEMCODE, T.ITEMNAME, MEASURINGUNIT=T.MEASURINGUNIT, ISSUE_QTY = SUM(T.ISSUE_QTY), 
 CONSUMPTION_QTY = SUM(T.CONSUMPTION_QTY)
FROM (
SELECT CODE = H.MINCODE, H.DEPTID, D.ITEMCODE, D.ITEMNAME ,D.MEASURINGUNIT, ISSUE_QTY = D.QUANTITY, 
 CONSUMPTION_QTY = 0
FROM MATERIALISSUENOTEHEADER AS H INNER JOIN MATERISSUENOTEDETAIL AS D ON    
     H.MINCODE = D.MINCODE    
  WHERE H.MINDATE BETWEEN @START_DATE AND @END_DATE AND 
     D.ITEMCODE BETWEEN @START_CODE AND @END_CODE AND
     H.DEPTID = @DEPTID
UNION ALL
SELECT CODE = H.CONSNOTECODE,H.DEPTID, D.ITEMCODE, D.ITEMNAME ,MEASURINGUNIT='', ISSUE_QTY = 0,
 CONSUMPTION_QTY = D.QUANTITY
FROM CONSUMPTIONNOTEHEADER AS H INNER JOIN CONSUMPTIONNOTEDETAIL AS D ON    
      H.CONSNOTECODE = D.CONSNOTECODE    
  WHERE H.CONSNOTEDATE BETWEEN @START_DATE AND @END_DATE AND
      D.ITEMCODE BETWEEN @START_CODE AND @END_CODE AND
      H.DEPTID = @DEPTID ) AS T 
GROUP BY T.CODE, T.DEPTID, T.ITEMCODE, T.ITEMNAME ,T.MEASURINGUNIT
         
end
}
go

create procedure saller.stock_transfer_search( @sort varchar(2),@start_date date,@end_date date ) as
begin
  if @sort = '0'
    select code=documentno,
      pdate=inwarddate,
      name=name,
      ogprefno
      from inwardheader where pdate >= @start_date
      and pdate <= @end_date
  if @sort = '1'
    select code=documentno,
      pdate=inwarddate,
      name=name,
      ogprefno
      from inwardheader where pdate >= @start_date
      and pdate <= @end_date and status = '0'
  if @sort = '2'
    select code=documentno,
      pdate=inwarddate,
      name=name,
      ogprefno
      from inwardheader where pdate >= @start_date
      and pdate <= @end_date and inwardtype = 'O' and status = '1'
end
go

