create procedure saller.r_inward_detail( @startcode integer,@endcode integer ) 
begin
  select sih.inwardno,sih.inwarddate,sih.partycode,sih.partytype,
    sih.name,sih.address,sih.city,sih.saletaxno,sih.inwardtype,sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,
    sid.amount,sid.discountrate,sid.discountamount,sid.strate,sid.saletaxamount,sid.totalamount,sid.measuringunit,
    sid.standardweight,sid.weight,sid.wastageweight,sid.wastagequantity
    from inwardheader as sih,inwarddetail as sid
    where sih.inwardno = sid.inwardno
    and sih.DOCUMENTno between @startcode and @endcode
end
