create procedure saller.r_inward_outward( @start_code varchar(14),@end_code varchar(14),@start_date DATETIME,@end_date DATETIME ) 
as
begin
  /* declare @outward_qty long,@inward_qty long,@wastage_qty long*/
  select ih.InwardNo,ih.InwardDate,ih.InwardType,ih.PartyCode,ih.Name,ih.PartyType,ih.City,ih.SaleCategory,id.ItemCode,id.ItemName,
    OutwardQuantiy=0,InwardQuantiy=id.Quantity,id.MeasuringUnit,id.SaleRate,id.StandardWeight,
    id.WastageQuantity,id.Weight,id.wastageweight
    from InwardHeader as ih,InwardDetail as id
    where((ih.InwardNo = id.InwardNo) and(ih.partyCode between @start_code and @end_code)
    and(ih.Inwarddate between @start_date and @end_date) and ih.InwardType = 'I') union all
  select ih.InwardNo,ih.InwardDate,ih.InwardType,ih.PartyCode,ih.Name,ih.PartyType,ih.City,ih.SaleCategory,id.ItemCode,id.ItemName,
    OutwardQuantiy=id.Quantity,InwardQuantiy=0,id.MeasuringUnit,id.SaleRate,id.StandardWeight,
    id.WastageQuantity,id.Weight,id.wastageweight
    from InwardHeader as ih,InwardDetail as id
    where((ih.InwardNo = id.InwardNo) and(ih.partyCode between @start_code and @end_code)
    and(ih.Inwarddate between @start_date and @end_date) and ih.InwardType = 'O')
end
go

