create procedure saller.R_POSTDATED_CHEQUE_SUB1( @CHEQUETYPE varchar(3),@CHEQUE_NO varchar(32) ) 
as
begin
  if @CHEQUETYPE = 'BRV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      DEBIT=ISNULL(VA.DEBIT,0),CREDIT=0,VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2)
      from VOUCHER as VA join CHART as C
        on VA.ACCOUNTCODE = C.ACCOUNTCODE
      where VA.CHEQUEDATE is not null
      and VA.CHEQUENO = @CHEQUE_NO and VA.DEBIT > 0 and VA.SEQNO = 1
      order by VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
  if @CHEQUETYPE = 'BPV'
    select VA.VOUCHERDATE,VA.ACCOUNTCODE,C.ACCOUNTNAME,VA.VOUCHERTYPE,VA.CHEQUENO,
      DEBIT=0,CREDIT=ISNULL(VA.CREDIT,0),VA.NARRATION,VA.CHEQUEDATE,VA.ACCOUNTCODE2,
      NAME2=(select ACCOUNTNAME from CHART where ACCOUNTCODE = VA.ACCOUNTCODE2)
      from VOUCHER as VA join CHART as C
        on VA.ACCOUNTCODE = C.ACCOUNTCODE
      where VA.CHEQUEDATE is not null
      and VA.CHEQUENO = @CHEQUE_NO and VA.CREDIT > 0 and VA.SEQNO = 1
      order by VA.ACCOUNTCODE asc,VA.CHEQUEDATE asc
end
go

