create procedure saller.price_policy_search( @sort varchar(2),@start_date date,@end_date date ) as
begin
  if @sort = '1'
    select code=document_no,
      pdate=document_date,
      name=narration
      from price_policy_header
      where approved = '0' and pdate >= @start_date and pdate <= @end_date
  else
    if @sort = '2'
      select code=document_no,
        pdate=document_date,
        name=narration
        from price_policy_header
        where approved = '1' and pdate >= @start_date and pdate <= @end_date
end
go

