create procedure saller.R_DAILY_ACTIVITY_SUB( @START_DATE date ) 
as
begin
  select DESCRIPTION='Sale Detail',H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,D.QUANTITY,RATE=D.SALERATE,D.AMOUNT
    from SALEINVOICEHEADER as H join SALEINVOICEDETAIL as D
      on H.SALEINVOICECODE = D.SALEINVOICECODE
    where H.INVOICEDATE = @START_DATE
    and H.STATUS = '1' union all
  select DESCRIPTION='Sale Return Detail',H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,D.QUANTITY,RATE=D.SALERATE,D.AMOUNT
    from SRHEADER as H join SRDETAIL as D
      on H.SRNO = D.SRNO
    where H.SRDATE = @START_DATE
    and H.APPROVED = '1' union all
  select DESCRIPTION='Purchase Detail',H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,D.QUANTITY,RATE=D.PURCHASERATE,D.AMOUNT
    from PURCHASEHEADER as H join PURCHASEDETAIL as D
      on H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE
    where H.PURCHASEINVOICEDATE = @START_DATE
    and H.STATUS = '1' union all
  select DESCRIPTION='Purchase Return Detail',H.PARTYCODE,H.NAME,D.ITEMCODE,D.ITEMNAME,D.QUANTITY,RATE=D.PURCHASERATE,D.AMOUNT
    from PRHEADER as H join PRDETAIL as D
      on H.PRNO = D.PRNO
    where H.PRDATE = @START_DATE
    and H.APPROVED = '1'
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_DAILY_ACTIVITY_SUB" IS 
{create PROCEDURE saller."R_DAILY_ACTIVITY_SUB"(@START_DATE DATE)
AS
BEGIN

SELECT DESCRIPTION='Sale Detail',H.PARTYCODE, H.NAME, D.ITEMCODE, D.ITEMNAME , D.QUANTITY, RATE=D.SALERATE, D.AMOUNT
 FROM SALEINVOICEHEADER AS H INNER JOIN SALEINVOICEDETAIL AS D ON    
 H.SALEINVOICECODE = D.SALEINVOICECODE    
WHERE 
 H.INVOICEDATE =  @START_DATE and 
 H.STATUS = '1' 
UNION ALL
SELECT DESCRIPTION='Sale Return Detail',H.PARTYCODE, H.NAME, D.ITEMCODE, D.ITEMNAME , D.QUANTITY, RATE=D.SALERATE, D.AMOUNT
 FROM SRHEADER AS H INNER JOIN SRDETAIL AS D ON    
 H.SRNO = D.SRNO  
WHERE 
 H.SRDATE =  @START_DATE and 
 H.APPROVED = '1'
UNION ALL
SELECT DESCRIPTION='Purchase Detail',H.PARTYCODE,H.NAME, D.ITEMCODE, D.ITEMNAME , D.QUANTITY, RATE=D.PURCHASERATE, D.AMOUNT
 FROM PURCHASEHEADER AS H INNER JOIN PURCHASEDETAIL AS D ON    
     H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE    
WHERE 
 H.PURCHASEINVOICEDATE = @START_DATE  and
 H.STATUS = '1'
UNION ALL
SELECT DESCRIPTION='Purchase Return Detail',H.PARTYCODE, H.NAME, D.ITEMCODE, D.ITEMNAME , D.QUANTITY, RATE=D.PURCHASERATE, D.AMOUNT
 FROM PRHEADER AS H INNER JOIN PRDETAIL AS D ON    
 H.PRNO = D.PRNO  
WHERE 
 H.PRDATE =  @START_DATE and 
 H.APPROVED = '1'

end
}
