create procedure Saller.R_DAILY_ACTIVITY_SUB1( @START_DATE date ) 
as
begin
  select T.DESCRIPTION,T.VOUCHERTYPE,T.ACCOUNTCODE,C.ACCOUNTNAME,T.NARRATION,T.DEBIT,T.CREDIT
    from(select DESCRIPTION='Receipt Detail',H.VOUCHERTYPE,H.ACCOUNTCODE,H.NARRATION,DEBIT=0,H.CREDIT
        from VOUCHER as H
        where H.VOUCHERDATE = @START_DATE and H.VOUCHERTYPE in( 'CRV','BRV' ) and H.CREDIT > 0 union all
      select DESCRIPTION='Payment & Expenses Detail',H.VOUCHERTYPE,H.ACCOUNTCODE,H.NARRATION,H.DEBIT,CREDIT=0
        from VOUCHER as H
        where H.VOUCHERDATE = @START_DATE and H.VOUCHERTYPE in( 'CPV','BPV' ) and H.DEBIT > 0) as T join CHART as C
      on T.ACCOUNTCODE = C.ACCOUNTCODE
end
