create procedure saller.R_DAILY_ACTIVITY_SUB3( @START_DATE date ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @start_date between startdate and enddate
  select c.accountcode,c.accountname,
    OpeningBalance=isnull(max(v.openingdr),0)-isnull(max(v.openingcr),0)+isnull((select SUM(OPT.DEBIT)-SUM(OPT.credit) from voucher as OPT
      where OPT.ACCOUNTCODE = c.ACCOUNTCODE
      and OPT.voucherdate < @STARt_DATE
      and opt.voucherdate between @startfiscaldate and @endfiscaldate group by OPT.AccountCode),0)
    from chart as c left outer join openingbalances as v on c.accountcode = v.accountcode
    where c.accounttype in( 'A','L','C' ) and v.periodid = @PeriodID
    group by c.accountcode,c.accountname order by c.accountcode asc
