create procedure Saller.R_DAILY_ACTIVITY_SUB5( @START_DATE date ) 
as
begin
  select T.description,sum(T.debit),abs(sum(T.credit))
    from(select description='Total',c.accountcode,c.accountname,debit=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),credit=0
        from chart as c left outer join voucher as v
          on c.accountcode = v.accountcode
        where v.voucherdate <= @START_DATE
        and c.accounttype in( 'A','L','C' ) 
        group by c.accountcode,c.accountname
        having isnull(sum(v.debit),0)-isnull(sum(v.credit),0) > 0 union all
      select description='Total',c.accountcode,c.accountname,debit=0,credit=isnull(sum(v.debit),0)-isnull(sum(v.credit),0)
        from chart as c left outer join voucher as v
          on c.accountcode = v.accountcode
        where v.voucherdate <= @START_DATE
        and c.accounttype in( 'A','L','C' ) 
        group by c.accountcode,c.accountname
        having isnull(sum(v.debit),0)-isnull(sum(v.credit),0) < 0) as T
    group by T.description
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_DAILY_ACTIVITY_SUB5" IS 
{create PROCEDURE Saller."R_DAILY_ACTIVITY_SUB5"(@START_DATE DATE)
AS
BEGIN
SELECT T.description, sum(T.debit), abs(sum(T.credit))
FROM (
     select  description = 'Total' , c.accountcode,c.accountname, debit=isnull(sum(v.debit),0)-isnull(sum(v.credit),0),credit = 0
      from   chart as c left outer join voucher as v on
      c.accountcode=v.accountcode where
      v.voucherdate<=@START_DATE and
      c.accounttype in ('A','L','C')
      group by c.accountcode,c.accountname
       having isnull(sum(v.debit),0)-isnull(sum(v.credit),0) > 0
UNION ALL
select  description = 'Total' , c.accountcode,c.accountname, debit = 0, credit=isnull(sum(v.debit),0)-isnull(sum(v.credit),0)
      from   chart as c left outer join voucher as v on
      c.accountcode=v.accountcode where
      v.voucherdate<=@START_DATE and
      c.accounttype in ('A','L','C')
      group by c.accountcode,c.accountname
       having isnull(sum(v.debit),0)-isnull(sum(v.credit),0) < 0 ) AS T 
GROUP BY T.description
end
}
go

create procedure saller.R_PARTY_WISE_PURCHASE( @startcode varchar(10),@endcode varchar(10),@START_DATE datetime,@END_DATE datetime ) 
as
begin
  /******************************************************************************      
Called by : PowerAccounting 2.0      
Author : Adil Sharif      
Date  : 2006-08-15      
*******************************************************************************/
  select H.DOCUMENTNO,H.PURCHASEINVOICEDATE,H.PARTYCODE,H.NAME,
    D.ITEMCODE,D.ITEMNAME,D.QUANTITY,D.PURCHASERATE,D.AMOUNT
    from PURCHASEHEADER as H join PURCHASEDETAIL as D
      on H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE
    where H.PURCHASEINVOICEDATE between @START_DATE and @END_DATE
    and H.STATUS = '1'
    and H.PARTYCODE between @startcode and @endcode
end
--select * from purchaSEHEADER

go

