create procedure saller.R_PARTY_WISE_PURCHASE_INVOICES( @startcode varchar(8),@endcode varchar(8),@START_DATE datetime,@END_DATE datetime ) 
as
begin
  select H.DOCUMENTNO,H.PURCHASEINVOICEDATE,H.PARTYCODE,H.NAME,
    H.REMARKS,QTY=SUM(D.QUANTITY),H.NETAMOUNT
    from PURCHASEHEADER as H
      join PURCHASEDETAIL as D
      on H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE
    where H.PURCHASEINVOICEDATE between @START_DATE and @END_DATE
    and H.STATUS = '1'
    and H.PARTYCODE between @STARTCODE and @ENDCODE
    group by H.PURCHASEINVOICECODE,H.PURCHASEINVOICEDATE,H.PARTYCODE,H.NAME,
    H.REMARKS,H.NETAMOUNT
    order by H.PURCHASEINVOICEDATE asc,H.PURCHASEINVOICECODE asc
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_PARTY_WISE_PURCHASE_INVOICES" IS 
{create PROCEDURE saller."R_PARTY_WISE_PURCHASE_INVOICES"(@startcode varchar(8),@endcode varchar(8),@START_DATE DATETIME,@END_DATE DATETIME)  
AS   
BEGIN  
  
SELECT H.DOCUMENTNO, H.PURCHASEINVOICEDATE, H.PARTYCODE, H.NAME,  
 H.REMARKS, QTY = SUM(D.QUANTITY),H.NETAMOUNT  
FROM PURCHASEHEADER AS H INNER JOIN  
 PURCHASEDETAIL AS D ON  
  H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE  
WHERE  H.PURCHASEINVOICEDATE BETWEEN @START_DATE AND @END_DATE AND  
 H.STATUS = '1' AND  
 H.PARTYCODE BETWEEN @STARTCODE AND @ENDCODE  
GROUP BY H.PURCHASEINVOICECODE, H.PURCHASEINVOICEDATE, H.PARTYCODE, H.NAME,  
 H.REMARKS,H.NETAMOUNT 
ORDER BY H.PURCHASEINVOICEDATE, H.PURCHASEINVOICECODE  
END
}
go

create procedure saller.R_PARTY_WISE_PURCHASE_HEADER( @START_ACCOUNT_CODE T_AccountCode,@END_ACCOUNT_CODE T_AccountCode,@START_DATE date,@END_DATE date ) 
/* List of input parameters. */
/*  */
/*  */
/*  */
/*  */
/* Output Parameters List*/
/* (None) */
-- WITH ENCRYPTION    
as
begin
  /******************************************************************************    
Called by : PowerAccounting 2.0    
Author : Rizwan Younas    
Date  : 2006-08-15    
*******************************************************************************/
  select T.PARTYCODE,T.NAME,AMOUNT=SUM(T.PUR_AMOUNT)-SUM(T.PR_AMOUNT)
    from(select H.PARTYCODE,H.NAME,
        PUR_AMOUNT=SUM(D.AMOUNT),PR_AMOUNT=0
        from PURCHASEHEADER as H
          join PURCHASEDETAIL as D
          on H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE
        where H.PURCHASEINVOICEDATE between @START_DATE and @END_DATE
        and H.STATUS = '1'
        and H.PARTYCODE between @START_ACCOUNT_CODE and @END_ACCOUNT_CODE
        group by H.PARTYCODE,H.NAME union all
      select H.PARTYCODE,H.NAME,
        PUR_AMOUNT=0,PR_AMOUNT=SUM(D.AMOUNT)
        from PRHEADER as H
          join PRDETAIL as D
          on H.PRNO = D.PRNO
        where H.PRDATE between @START_DATE and @END_DATE
        and H.APPROVED = '1'
        and H.PARTYCODE between @START_ACCOUNT_CODE and @END_ACCOUNT_CODE
        group by H.PARTYCODE,H.NAME) as T
    group by T.PARTYCODE,T.NAME
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."R_PARTY_WISE_PURCHASE_HEADER" IS 
{create PROCEDURE saller."R_PARTY_WISE_PURCHASE_HEADER"  (  
 /* List of input parameters. */    
 @START_ACCOUNT_CODE  T_ACCOUNTCODE, /*  */    
 @END_ACCOUNT_CODE  T_ACCOUNTCODE,  /*  */    
 @START_DATE  DATE,  /*  */    
 @END_DATE DATE ) /*  */    
 /* Output Parameters List*/    
 /* (None) */    
-- WITH ENCRYPTION    
as
begin
/******************************************************************************    
 Called by : PowerAccounting 2.0    
 Author : Rizwan Younas    
 Date  : 2006-08-15    
*******************************************************************************/    
  SELECT T.PARTYCODE , T.NAME, AMOUNT= SUM(T.PUR_AMOUNT) - SUM(T.PR_AMOUNT)  
FROM(  
SELECT H.PARTYCODE, H.NAME ,   
 PUR_AMOUNT = SUM(D.AMOUNT),PR_AMOUNT =0  
  
    
FROM PURCHASEHEADER AS H INNER JOIN    
 PURCHASEDETAIL AS D ON    
   H.PURCHASEINVOICECODE = D.PURCHASEINVOICECODE    
WHERE 
 H.PURCHASEINVOICEDATE BETWEEN @START_DATE AND @END_DATE AND    
 H.STATUS = '1' AND    
 H.PARTYCODE BETWEEN @START_ACCOUNT_CODE AND @END_ACCOUNT_CODE    
GROUP BY H.PARTYCODE ,  H.NAME UNION ALL  
SELECT H.PARTYCODE, H.NAME ,  
 PUR_AMOUNT = 0, PR_AMOUNT = SUM(D.AMOUNT)  
    
FROM PRHEADER AS H INNER JOIN    
 PRDETAIL AS D ON    
  H.PRNO = D.PRNO    
WHERE  
 H.PRDATE BETWEEN @START_DATE AND @END_DATE AND    
 H.APPROVED = '1' AND    
 H.PARTYCODE BETWEEN @START_ACCOUNT_CODE AND @END_ACCOUNT_CODE    
GROUP BY H.PARTYCODE ,  H.NAME) AS T  
GROUP BY T.PARTYCODE , T.NAME  
  
    
END
}
go

