create procedure saller.r_CustomerWise_SRDetail( @style varchar(1),@group varchar(16),@startCode varchar(8),@endCode varchar(8),@startDate T_DocumentDate,@endDate T_DocumentDate,@start_Code varchar(16),@end_Code varchar(16) ) 
as
begin
  if @style = '0'
    select s.srDate,s.DocumentNo,s.Name,s.city,s.deptid,sd.ItemCode,
      sd.ItemName,sd.Quantity,sd.SaleRate,sd.Amount,s.partycode,
      sd.seqno
      from SrHeader as s key join SrDetail as sd
      where s.PartyCode between @startCode and @endcode
      and s.SrDate between @startDate and @endDate
      and sd.itemcode between @start_Code and @end_Code
      and s.approved = '1'
      order by s.srDate asc
  if @style = '1'
    select s.srDate,s.DocumentNo,s.Name,s.city,s.deptid,sd.ItemCode,
      sd.ItemName,sd.Quantity,sd.SaleRate,sd.Amount,s.partycode,
      sd.seqno
      from SrHeader as s key join SrDetail as sd
      where s.PartyCode between @startCode and @endcode
      and s.SrDate between @startDate and @endDate
      and sd.itemcode = any(select itemcode from itemgroupdetail where groupcode = @group)
      and s.approved = '1'
      order by s.srDate asc
end
go

