    s.srDate asc
if @style='1'
  select s.srDate,s.DocumentNo,s.Name,s.city,s.deptid,sd.ItemCode,
    sd.ItemName,sd.Quantity,sd.SaleRate,sd.Amount,s.partycode,
    sd.seqno from
    SrHeader as s key join SrDetail as sd where
    s.PartyCode between @startCode and @endcode
    and s.SrDate between @startDate and @endDate and
    sd.itemcode=any(select itemcode from itemgroupdetail where groupcode=@group)and
    s.approved = '1' order by
    s.srDate asc
end
}
go

create procedure Saller.r_consolidated_trialbalance( @startdate date,@enddate date,@startGroup varchar(32),@endGroup varchar(32) ) 
/* ( @parameter_name datatype [= default] [output], ... ) */
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  select t.groupcode,t.accountcode,t.accountname,
    openingdebit=case when isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)
    -isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0) > 0 then
      isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)
      -(isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0))
    else 0
    end,
    --isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0),
    openingcredit=case when isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)
    -isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0) <= 0 then
      isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0)
      -(isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0))
    else
      0
    end,
    --        isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0),
    isnull(sum(t.currentdebit),0),isnull(sum(t.currentcredit),0),
    closingdebit=case when isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)+isnull(sum(t.currentdebit),0)
    -(isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0)+isnull(sum(t.currentcredit),0)) > 0 then
      isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)+isnull(sum(t.currentdebit),0)
      -(isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0)+isnull(sum(t.currentcredit),0))
    else 0
    end,
    closingcredit=case when isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)+isnull(sum(t.currentdebit),0)
    -(isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0)+isnull(sum(t.currentcredit),0)) <= 0 then
      isnull(sum(t.openingcredit),0)+isnull(sum(t.previouscredit),0)+isnull(sum(t.currentcredit),0)
      -(isnull(sum(t.openingdebit),0)+isnull(sum(t.previousdebit),0)+isnull(sum(t.currentdebit),0))
    else
      0
    end
    from(select g.groupcode,c.accountcode,c.accountname,
        openingdebit=isnull(max(op.openingdr),0),
        openingcredit=isnull(max(op.openingcr),0),
        previousdebit=0,previouscredit=0,
        currentdebit=0,currentcredit=0
        from chartgroup as g join chart as c
          on g.accountcode = c.accountcode
          left outer join openingbalances as op
          on c.accountcode = op.accountcode
        where op.periodid = @periodid
        and g.groupcode between @startgroup and @endgroup
        group by g.groupcode,c.accountcode,c.accountname union all
      select g.groupcode,c.accountcode,c.accountname,openingdebit=0,openingcredit=0,
        previousdebit=isnull(sum(v.debit),0),previouscredit=isnull(sum(v.credit),0),
        currentdebit=0,
        currentcredit=0
        from chartgroup as g join chart as c
          on g.accountcode = c.accountcode
          join voucher as v
          on g.accountcode = v.accountcode
        where v.voucherdate < @startdate
        and v.voucherdate between @startfiscaldate and @endfiscaldate
        and g.groupcode between @startgroup and @endgroup
        group by g.groupcode,c.accountcode,c.accountname union all
      select g.groupcode,c.accountcode,c.accountname,openingdebit=0,openingcredit=0,
        previousdebit=0,previouscredit=0,
        currentdebit=isnull(sum(v.debit),0),
        currentcredit=isnull(sum(v.credit),0)
        from chartgroup as g join chart as c
          on g.accountcode = c.accountcode
          join voucher as v
          on g.accountcode = v.accountcode
        where v.voucherdate between @startdate and @enddate
        and g.groupcode between @startgroup and @endgroup
        group by g.groupcode,c.accountcode,c.accountname) as t
    group by t.groupcode,t.accountcode,t.accountname
end
go

