create procedure saller.r_customer_balance_summary( @groupcode varchar(32),@startdate date,@enddate date,@startcode varchar(6),@endcode varchar(6),@style char(1) ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate date,@endfiscaldate date
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  if @style = '0'
    select c.accountcode,c.accountname,c.Address,c.city,c.phone,c.MobileNo,
      opngdr=isnull(max(v.openingdr),0)+isnull((select SUM(OPT.DEBIT) from voucher as OPT
        where OPT.ACCOUNTCODE = c.ACCOUNTCODE
        and OPT.voucherdate < @ENDDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate group by OPT.AccountCode),0),
      opngcr=isnull(max(v.openingcr),0)+isnull((select SUM(OPT.CREDIT) from voucher as OPT
        where OPT.ACCOUNTCODE = c.ACCOUNTCODE
        and OPT.voucherdate < @ENDDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate group by OPT.AccountCode),0)
      from chart as c left outer join openingbalances as v on c.accountcode = v.accountcode
      where c.accountcode between @startcode and @endcode and v.periodid = @PeriodID
      group by c.accountcode,c.accountname,c.Address,c.city,c.phone,c.MobileNo order by c.accountcode asc
  if @style = '1'
    select c.accountcode,c.accountname,c.Address,c.city,c.phone,c.MobileNo,
      opngdr=isnull(max(v.openingdr),0)+isnull((select SUM(OPT.DEBIT) from voucher as OPT
        where OPT.ACCOUNTCODE = c.ACCOUNTCODE
        and OPT.voucherdate < @ENDDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0),
      opngcr=isnull(max(v.openingcr),0)+isnull((select SUM(OPT.CREDIT) from voucher as OPT
        where OPT.ACCOUNTCODE = c.ACCOUNTCODE
        and OPT.voucherdate < @ENDDATE
        and opt.voucherdate between @startfiscaldate and @endfiscaldate),0)
      from chart as c left outer join openingbalances as v on c.accountcode = v.accountcode
      where c.accountcode = any(select accountcode from chartgroup where groupcode = @groupcode) and v.periodid = @PeriodID
      group by c.accountcode,c.accountname,c.Address,c.city,c.phone,c.MobileNo order by c.accountcode asc
end
go

