create procedure saller.R_CUSTOMER_WISE_SALES_HEADER( @START_CODE T_AccountCode,@END_CODE T_AccountCode,@START_DATE date,@END_DATE date,@GROUP_CODE T_Group_code,@STYLE varchar(1) ) 
/* List of input parameters. */
/*  */
/*  */
/*  */
/*  */
/*  */
/*  */
/* Output Parameters List*/
/* (None) */
-- WITH ENCRYPTION    
as
begin
  /******************************************************************************    
Called by : PowerAccounting 2.0    
Author : Ayaz Mehboob    
Date  : 2013-04-10    
*******************************************************************************/
  --SELECT ALL ACCOUNTS
  if @STYLE = '0'
    select AMOUNT=SUM(T.SALE_AMOUNT)-SUM(T.SR_AMOUNT)
      from(select H.PARTYCODE,H.NAME,
          SALE_AMOUNT=SUM(D.AMOUNT),SR_AMOUNT=0
          from SALEINVOICEHEADER as H
            join SALEINVOICEDETAIL as D
            on H.SALEINVOICECODE = D.SALEINVOICECODE
          where H.INVOICEDATE between @START_DATE and @END_DATE
          and H.STATUS = '1'
          and H.PARTYCODE between @START_CODE and @END_CODE
          group by H.PARTYCODE,H.NAME union all
        select H.PARTYCODE,H.NAME,
          SALE_AMOUNT=0,SR_AMOUNT=SUM(D.AMOUNT)
          from SRHEADER as H
            join SRDETAIL as D
            on H.SRNO = D.SRNO
          where H.SRDATE between @START_DATE and @END_DATE
          and H.APPROVED = '1'
          and H.PARTYCODE between @START_CODE and @END_CODE
          group by H.PARTYCODE,H.NAME) as T
  --SELECT SPECIFIC ACCOUNTS
  if @STYLE = '1'
    select AMOUNT=SUM(T.SALE_AMOUNT)-SUM(T.SR_AMOUNT)
      --H.PARTYCODE BETWEEN @START_CODE AND @END_CODE    
      --H.PARTYCODE BETWEEN @START_CODE AND @END_CODE    
      from(select H.PARTYCODE,H.NAME,
          SALE_AMOUNT=SUM(D.AMOUNT),SR_AMOUNT=0
          from SALEINVOICEHEADER as H
            join SALEINVOICEDETAIL as D
            on H.SALEINVOICECODE = D.SALEINVOICECODE
          where H.INVOICEDATE between @START_DATE and @END_DATE
          and H.STATUS = '1'
          and H.PARTYCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @GROUP_CODE)
          group by H.PARTYCODE,H.NAME union all
        select H.PARTYCODE,H.NAME,
          SALE_AMOUNT=0,SR_AMOUNT=SUM(D.AMOUNT)
          from SRHEADER as H
            join SRDETAIL as D
            on H.SRNO = D.SRNO
          where H.SRDATE between @START_DATE and @END_DATE
          and H.APPROVED = '1'
          and H.PARTYCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @GROUP_CODE)
          group by H.PARTYCODE,H.NAME) as T
end
