create procedure saller.R_CUSTOMERWISE_SALE( @STARTCODE varchar(10),@ENDCODE varchar(10),@START_DATE DATETIME,@END_DATE DATETIME,@GROUP_CODE varchar(32),@STYLE varchar(1) ) 
