  if @STYLE = '1'
    select H.DOCUMENTNO,H.INVOICEDATE,H.PARTYCODE,H.NAME,
      D.ITEMCODE,D.ITEMNAME,D.QUANTITY,D.SALERATE,D.AMOUNT
      from SALEINVOICEHEADER as H join SALEINVOICEDETAIL as D
        on H.SALEINVOICECODE = D.SALEINVOICECODE
      where H.PARTYCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @GROUP_CODE)
      and H.INVOICEDATE between @START_DATE and @END_DATE
      and H.STATUS = '1'
end
