create procedure saller.R_SALE_ITEMRATE_GROUP( @START_ACCOUNT_CODE T_AccountCode,@END_ACCOUNT_CODE T_AccountCode,@START_DATE date,@END_DATE date,@GROUP_CODE varchar(32),@STYLE varchar(1) ) 
/* List of input parameters. */
/*  */
/*  */
/*  */
/*  */
/*  */
/*  */
/* Output Parameters List*/
/* (None) */
-- WITH ENCRYPTION    
as
begin
  /******************************************************************************    
Called by : Finance Manager
Author : Ayaz Mehboob
Date  : 2013-04-10    
*******************************************************************************/
  if @STYLE = '0'
    select D.ITEMCODE,I.ITEMNAME,SUM(D.QUANTITY),SUM(D.AMOUNT)/SUM(D.QUANTITY),SUM(D.AMOUNT)
      from SALEINVOICEHEADER as H,SALEINVOICEDETAIL as D,ITEMINFORMATION as I
      where H.SALEINVOICECODE = D.SALEINVOICECODE and D.ITEMCODE = I.ITEMCODE
      and H.INVOICEDATE between @START_DATE and @END_DATE
      and H.STATUS = '1'
      and H.PARTYCODE between @START_ACCOUNT_CODE and @END_ACCOUNT_CODE
      group by D.ITEMCODE,I.ITEMNAME
  if @STYLE = '1'
    select D.ITEMCODE,I.ITEMNAME,SUM(D.QUANTITY),SUM(D.AMOUNT)/SUM(D.QUANTITY),SUM(D.AMOUNT)
      from SALEINVOICEHEADER as H,SALEINVOICEDETAIL as D,ITEMINFORMATION as I
      where H.SALEINVOICECODE = D.SALEINVOICECODE and D.ITEMCODE = I.ITEMCODE
      and H.PARTYCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @GROUP_CODE)
      and H.INVOICEDATE between @START_DATE and @END_DATE
      and H.STATUS = '1'
      group by D.ITEMCODE,I.ITEMNAME
end
go

