create procedure saller.r_sale_summary( @startdate date,@enddate date ) 
begin
  select sih.documentno,sih.invoicedate,sih.partycode,
    max(sih.name),sih.address,sih.city,sum(sid.quantity),
    sih.netamount,sih.despatch
    from saleinvoiceheader as sih,saleinvoicedetail as sid
    where sih.saleinvoicecode = sid.saleinvoicecode
    and sih.invoicedate between @startdate and @enddate
    and status = '1' group by sih.documentno,sih.invoicedate,sih.partycode,
    max(sih.name),sih.address,sih.city,sih.netamount,sih.despatch
end
go

