create procedure saller.p_ledger_detail_customise( @DocumentType varchar(3),@InvoiceNo varchar(8) ) as
begin
  if @DocumentType = 'SL'
    select sih.documentno,sih.discountamount,sih.netamount,sih.despatch,sih.remarks,
      sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,sid.amount,
      sid.discountrate,sid.discountamount,sid.Totalamount,sid.measuringunit
      from SaleInvoiceHeader as sih join SaleInvoiceDetail as sid
        on sih.saleinvoicecode = sid.saleinvoicecode
      where sih.saleinvoicecode = @InvoiceNo
  if @DocumentType = 'SR'
    select sih.documentno,sih.discountamount,sih.netamount,sih.despatch,sih.remarks,
      sid.seqno,sid.itemcode,sid.itemname,sid.quantity,sid.salerate,sid.amount,
      sid.discountrate,sid.discountamount,sid.totalamount,sid.measuringunit
      from SRHeader as sih join SRDetail as sid
        on sih.srno = sid.srno
      where sih.srno = @InvoiceNo
  if @DocumentType = 'PU'
    select pih.documentno,pih.discountamount,pih.netamount,pih.despatch,pih.remarks,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.purchaserate,pid.amount,
      pid.discountrate,pid.discountamount,pid.totalamount,pid.measuringunit
      from PurchaseHeader as pih join PurchaseDetail as pid
        on pih.purchaseInvoicecode = pid.purchaseInvoicecode
      where pih.purchaseInvoicecode = @InvoiceNo
  if @DocumentType = 'PR'
    select pih.documentno,pih.discountamount,pih.netamount,pih.despatch,pih.remarks,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.purchaserate,pid.amount,
      pid.discountrate,pid.discountamount,pid.netamount,pid.measuringunit
      from PrHeader as pih join PrDetail as pid
        on pih.prno = pid.prNo
      where pih.prno = @InvoiceNo
  if @DocumentType = 'SI'
    select pih.documentno,pih.discountamount,pih.netamount,pih.despatch,pih.remarks,
      pid.seqno,pid.itemcode,pid.itemname,pid.quantity,pid.salerate,pid.amount,
      pid.discountrate,pid.discountamount,pid.totalamount,pid.measuringunit
      from InwardHeader as pih join InwardDetail as pid
        on pih.InwardNo = pid.InwardNo
      where pih.InwardNo = @InvoiceNo
end
commit work
go

