create procedure Saller.D_Accounts( @AccountGroup varchar(128),@AmountType varchar(4),@STARTDATE DATETIME,@ENDDATE DATETIME ) 
as
begin
  declare @periodid varchar(16),@startfiscaldate datetime,@endfiscaldate datetime
  select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate
  -- WHEN NO GROUP SELECTED
  if @AccountGroup = '-999' -- LEVEL-1
    begin
      -- FOR REMAINING BALANCES
      if @AMOUNTTYPE = 'B'
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,VOUCHERID=convert(varchar(12),MAX(V.VOUCHERID)),MAX(V.VOUCHERDATE),
          AMOUNT=SUM(IsNull(V.DEBIT,0.0))-SUM(IsNull(V.CREDIT,0.0))+(select SUM(ISNULL(B.OPENINGDR,0.0))-SUM(ISNULL(B.OPENINGCR,0.0))
            from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE and PERIODID = @PeriodID)
          from Chart as C left outer join Voucher as V on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE between @STARTDATE and @ENDDATE and C.ACCOUNTCATEGORY in( 'S','V','P' ) 
          group by C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,C.MOBILENO,C.ACCOUNTCATEGORY
      -- FOR ONLY RECEIPTS                    
      if @AMOUNTTYPE = 'R'
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,V.VOUCHERID,V.VOUCHERDATE,
          AMOUNT=IsNull(V.CREDIT,0.0)+(select SUM(ISNULL(B.OPENINGCR,0.0)) from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE and PERIODID = @PERIODID)
          from Voucher as V left outer join Chart as C on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE between @STARTDATE and @ENDDATE and V.CREDIT > 0
          and C.ACCOUNTCATEGORY in( 'S','V','P' ) 
      -- FOR ONLY PAYMENTS
      if @AMOUNTTYPE = 'P'
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,V.VOUCHERID,V.VOUCHERDATE,
          AMOUNT=IsNull(V.DEBIT,0.0)+(select SUM(ISNULL(B.OPENINGDR,0.0)) from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE and PERIODID = @PERIODID)
          from Voucher as V left outer join Chart as C on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE between @STARTDATE and @ENDDATE and V.debit > 0
          and C.ACCOUNTCATEGORY in( 'S','V','P' )  -- LTRIM(LENGTH(C.MOBILENO)) > 0 AND
      -- FOR SALE ENTRIES
      if @AMOUNTTYPE not in( 'B','R','P' ) 
        select STATUS='0',V.ACCOUNTCODE,V.ACCOUNTNAME,V.CITY,V.MOBILENO,V.ACCOUNTCATEGORY,V.DOCUMENTNO,V.DOCUMENTDATE,V.NETAMOUNT
          from VIEW_INVOICES as V
          where V.DOCUMENTNAME = @AMOUNTTYPE and V.DOCUMENTDATE between @STARTDATE and @ENDDATE
    end -- LEVEL-1
  -- WHEN USER SELECT A SPEIFIC GROUP THEN GET DATA FROM CHART ONLY AS PER GROUP
  if @AccountGroup <> '-999' -- LEVEL-2
    begin
      select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,VOUCHERID='',VOUCHERDATE=null,AMOUNT=0.0
        from CHART as C
        where C.ACCOUNTCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @ACCOUNTGROUP)
        and C.ACCOUNTCATEGORY in( 'S','V','P' ) 
    end -- LEVEL-2   
end
go

COMMENT TO PRESERVE FORMAT ON PROCEDURE "saller"."D_Accounts" IS 
{create PROCEDURE Saller."D_Accounts"( @AccountGroup varchar(128), @AmountType varchar(4), @STARTDATE DATETIME, @ENDDATE DATETIME ) 
as
begin
    
    declare @periodid varchar(16),@startfiscaldate datetime ,@endfiscaldate datetime
    select @periodid = year,@startfiscaldate = startdate,@endfiscaldate = enddate
    from fiscalyears where @startdate between startdate and enddate

  -- WHEN NO GROUP SELECTED
  if @AccountGroup = '-999' -- LEVEL-1
    begin
      -- FOR REMAINING BALANCES
      if @AMOUNTTYPE = 'B'
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY, VOUCHERID = CAST(MAX(V.VOUCHERID) AS VARCHAR(12)), MAX(V.VOUCHERDATE),
          AMOUNT=SUM(IsNull(V.DEBIT,0.0))-SUM(IsNull(V.CREDIT,0.0)) + (select SUM(ISNULL(B.OPENINGDR,0.0))-SUM(ISNULL(B.OPENINGCR,0.0)) 
          from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE AND PERIODID = @PeriodID ) 
          FROM Chart as C LEFT OUTER JOIN Voucher as V on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE BETWEEN  @STARTDATE AND @ENDDATE AND C.ACCOUNTCATEGORY IN ( 'S', 'V', 'P' ) 
          group by C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,C.MOBILENO,C.ACCOUNTCATEGORY

        -- FOR ONLY RECEIPTS                    
      if @AMOUNTTYPE = 'R'     
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY, V.VOUCHERID, V.VOUCHERDATE ,
          AMOUNT=IsNull(V.CREDIT,0.0) + (select SUM(ISNULL(B.OPENINGCR,0.0)) from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE AND PERIODID = @PERIODID)
          FROM Voucher as V LEFT OUTER JOIN Chart as C on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE BETWEEN @STARTDATE AND @ENDDATE AND V.CREDIT > 0 
            AND C.ACCOUNTCATEGORY IN ( 'S', 'V', 'P' )

       -- FOR ONLY PAYMENTS
      if @AMOUNTTYPE = 'P'
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY,  V.VOUCHERID, V.VOUCHERDATE ,
          AMOUNT=IsNull(V.DEBIT,0.0) + (select SUM(ISNULL(B.OPENINGDR,0.0)) from OPENINGBALANCES as B where B.ACCOUNTCODE = C.ACCOUNTCODE AND PERIODID = @PERIODID )
          FROM Voucher as V LEFT OUTER JOIN Chart as C on V.ACCOUNTCODE = C.ACCOUNTCODE
          where V.VOUCHERDATE BETWEEN @STARTDATE AND @ENDDATE  and V.debit > 0 
            AND C.ACCOUNTCATEGORY IN ( 'S', 'V', 'P' )-- LTRIM(LENGTH(C.MOBILENO)) > 0 AND
        
      -- FOR SALE ENTRIES
      IF @AMOUNTTYPE NOT IN ( 'B', 'R', 'P' )    
          SELECT STATUS = '0' , V.ACCOUNTCODE, V.ACCOUNTNAME , V.CITY, V.MOBILENO, V.ACCOUNTCATEGORY, V.DOCUMENTNO, V.DOCUMENTDATE, V.NETAMOUNT
          FROM VIEW_INVOICES AS V
          WHERE V.DOCUMENTNAME = @AMOUNTTYPE AND V.DOCUMENTDATE BETWEEN @STARTDATE AND @ENDDATE 

end -- LEVEL-1
  

   -- WHEN USER SELECT A SPEIFIC GROUP THEN GET DATA FROM CHART ONLY AS PER GROUP
  if @AccountGroup <> '-999' -- LEVEL-2
    begin
        select STATUS='0',C.ACCOUNTCODE,C.ACCOUNTNAME,C.CITY,MOBILENO=REPLACE(C.MOBILENO,'-',''),C.ACCOUNTCATEGORY, VOUCHERID ='' , VOUCHERDATE= null ,AMOUNT=0.00
        from CHART as C  
        where C.ACCOUNTCODE = any(select ACCOUNTCODE from CHARTGROUP where GROUPCODE = @ACCOUNTGROUP)
        AND C.ACCOUNTCATEGORY IN ( 'S', 'V', 'P' )
    end -- LEVEL-2   



end
}
go

