create trigger tr_insert_voucher.tr_insert_voucher after insert order 1 on
Saller.Voucher
referencing new as inserted
for each row
begin
  if inserted.vouchertype in( 'CPV','BPV' ) and inserted.seqno = 1 and inserted.documentno is null then
    insert into voucher( VoucherType,
      TransactionNo,SeqNo,VoucherID,VoucherDate,AccountCode,
      Narration,Debit,Credit,UserCode,Status,DocumentNo,DocumentName,
      Doc,AccountCode2,chequeDate,ChequeNo ) 
      values( inserted.VoucherType,
      inserted.TransactionNo,
      2,
      inserted.VoucherID,
      inserted.VoucherDate,inserted.AccountCode2,
      inserted.Narration,
      0,
      inserted.debit,
      inserted.userCode,
      inserted.status,
      null,
      null,
      inserted.doc,
      inserted.AccountCode,
      inserted.ChequeDate,inserted.Chequeno ) 
  end if;
  if inserted.vouchertype in( 'CRV','BRV' ) and inserted.seqno = 1 and inserted.documentno is null then
    insert into voucher( VoucherType,
      TransactionNo,SeqNo,VoucherID,VoucherDate,AccountCode,
      Narration,Debit,Credit,UserCode,Status,DocumentNo,DocumentName,
      Doc,AccountCode2,chequeDate,ChequeNo ) 
      values( inserted.VoucherType,
      inserted.TransactionNo,
      2,
      inserted.VoucherID,
      inserted.VoucherDate,inserted.AccountCode2,
      inserted.Narration,
      inserted.credit,
      0,
      inserted.userCode,
      inserted.status,
      null,
      null,
      inserted.doc,
      inserted.AccountCode,
      inserted.ChequeDate,inserted.Chequeno ) 
  end if
end
