create trigger saller.tr_delete_voucher after delete order 2 on
Saller.Voucher
referencing old as deleted
for each row
begin
  if deleted.vouchertype in( 'CPV','CRV','BPV','BRV' ) and deleted.SeqNo = 1 and deleted.documentno is null then
    delete from voucher
      where TransactionNo = deleted.TransactionNo
      and voucherType = deleted.VoucherType
  end if
end
go

