create trigger tr_pr_update.tr_pr_update on
Saller.PRHeader for update
as
if update(Approved) begin
    declare @PInvoiceNo integer,
    @documentno integer,
    @InvoiceDate date,
    @PartyCode varchar(14),
    @PartyType char(1),
    @PartyName varchar(128),
    @City varchar(32),
    @PrType char(1),
    @DiscountAmount numeric(14,2),
    @NetAmount numeric(14,2),
    @Status char(1),
    @userCode varchar(10),
    @TrNo integer,
    @VrNo integer,
    @voucherNo varchar(10),
    @MonthNo tinyint,
    @YearNo smallint,
    @Month varchar(2),
    @Year varchar(2),
    @CashAccount varchar(14),
    @PrAccount varchar(14),
    @leftPart varchar(4),
    @rightPart varchar(3),
    @voucherType char(3)
    /* Select the Values from the inserted */
    select @PinvoiceNo = PrNo,
      @documentno = documentno,
      @invoiceDate = PrDate,
      @PartyCode = PartyCode,
      @PartyName = Name,
      @city = city,
      @PrType = PrType,
      @DiscountAmount = isnull(DiscountAmount,0),
      @NetAmount = isnull(NetAmount,0),
      @status = Approved,
      @userCode = userCode
      from inserted
    /* Check Whether Cash or Credit Sale */
    if @PrType = '0'
      begin
        select @voucherType = 'CRV'
        --- Procedure for Posting
        if @status = 1
          begin
            -- Get the Max Transaction ID and VoucherID
            select @TrNo = isnull(max(TransactionNo),0)
              from voucher
            --- Get the Maximum VoucherID of the Selected Voucher Type   
            select @VoucherNo = max(VoucherID)
              from voucher
              where vouchertype = @voucherType
              and dateformat(@invoicedate,'yymm') = "left"(VoucherID,4)
            --- Get the Month No from the InvoiceDate
            select @Month = Month(@invoiceDate)
            --- Check to verify Whether to Create the a New VoucherID of Increment the Existing One
            if @VoucherNo is null
              begin
                select @MonthNo = Month(@invoiceDate),
                  @YearNo = Year(@invoiceDate)
                if length(trim(convert(varchar(2),@MonthNo))) = 1
                  select @Month = '0'+convert(varchar(1),@MonthNo)
                else
                  select @Month = convert(varchar(2),@MonthNo)
                select @Year = "right"(convert(varchar(4),@YearNo),2)
                select @voucherNo = @Year+@Month+'001'
              end
            else
              begin
                --- Split the Voucher ID into Two Parts
                select @leftpart = "left"(@voucherNo,4)
                select @rightPart = "right"(@voucherNo,3)
                -- Incerment the right Part
                select @rightPart = convert(varchar(3),convert(integer,@rightPart)+1)
                -- Make Sure that Length of RightPart is of 3 Characters
                if length(@rightPart) = 1
                  select @rightPart = '00'+@rightPart
                if length(@rightPart) = 2
                  select @rightPart = '0'+@rightPart
                --- Make the New VoucherID
                select @voucherNo = @leftPart+@rightPart
              end
            --- Generate the New Transaction ID
            select @TrNo = @TrNo+1
            --- Get the Cash, Sale and Sales Tax Payble Account
            select @CashAccount = CashAccount,
              @PrAccount = PrAccountCode
              from ProductControl
            --- Insert a new Row in the Voucher Table
            insert into voucher
              select @voucherType,@TrNo,1,@voucherNo,@invoiceDate,@cashAccount,'Purchase Return Vide Inv#'
                +convert(varchar(10),@documentno),
                @NetAmount,0,@userCode,'1',@PinvoiceNo,'PR',getdate(),@PrAccount
            ----- insert a new row for Sale
            insert into voucher
              select @voucherType,@TrNo,2,@voucherNo,@invoiceDate,@PrAccount,'Purchase Return Vide Inv#'
                +convert(varchar(10),@documentno),
                0,@NetAmount,@userCode,'1',@PinvoiceNo,'PR',getdate(),@cashAccount
          ---- insert a new row for Sales Tax Payable
          /*if @saleTaxAmount<>0
insert into voucher
select @voucherType,@Trno,3,@voucherNo,@invoiceDate,@STAdvanceaccount,'Purchase Return Vide Inv#'
+convert(varchar(10),@PinvoiceNo),
0,@saleTaxAmount,@userCode,'1',@PinvoiceNo,'PR',getdate(*),@cashAccount*/
          end
        if @status = '0'
          --- Delete the Enteries of Voucher 
          delete from voucher
            where vouchertype = @voucherType
            and documentno = @PinvoiceNo
            and documentName = 'PR'
      end
    if @PrType = '1'
      begin
        select @voucherType = 'JVR'
        --- Procedure for Posting
        if @status = 1
          begin
            -- Get the Max Transaction ID and VoucherID
            select @TrNo = isnull(max(TransactionNo),0)
              from voucher
            -- Set the Voucher Type
            select @VoucherNo = max(VoucherID)
              from voucher
              where vouchertype = @voucherType
              and Month(@invoicedate) = Month(VoucherDate)
              and Year(@invoicedate) = Year(VoucherDate)
            --- Get the Month No from the InvoiceDate
            select @Month = Month(@invoiceDate)
            --- Check to verify Whether to Create the a New VoucherID of Increment the Existing One
            if @VoucherNo is null
              begin
                select @MonthNo = Month(@invoiceDate),
                  @YearNo = Year(@invoiceDate)
                if length(trim(convert(varchar(2),@MonthNo))) = 1
                  select @Month = '0'+convert(varchar(1),@MonthNo)
                select @Year = "right"(convert(varchar(4),@YearNo),2)
                select @voucherNo = @Year+@Month+'001'
              end
            else
              begin
                --- Split the Voucher ID into Two Parts
                select @leftpart = "left"(@voucherNo,4)
                select @rightPart = "right"(@voucherNo,3)
                -- Incerment the right Part
                select @rightPart = convert(varchar(3),convert(integer,@rightPart)+1)
                -- Make Sure that Length of RightPart is of 3 Characters
                if length(@rightPart) = 1
                  select @rightPart = '00'+@rightPart
                if length(@rightPart) = 2
                  select @rightPart = '0'+@rightPart
                --- Make the New VoucherID
                select @voucherNo = @leftPart+@rightPart
              --select @voucherNo=@vrNo+1
              /*if length(trim(convert(varchar(7),@vrNo)))<7
select @voucherNo='0'+@vrNo
else
select @voucherNo=trim(convert(varchar(7),@vrNo)) */
              end
            --- Generate the New Transaction ID
            select @TrNo = @TrNo+1
            --- Get the Cash, Sale and Sales Tax Payble Account
            select @PrAccount = PrAccountCode
              from ProductControl
            --- Insert a new Row in the Voucher Table
            insert into voucher
              select @voucherType,@TrNo,1,@voucherNo,@invoiceDate,@PartyCode,'Credit Purchase Return #'
                +convert(varchar(10),@documentno),
                @NetAmount,0,@userCode,'1',@PinvoiceNo,'PR',getdate(),@PrAccount,null,null
            ----- insert a new row for 
            insert into voucher
              select @voucherType,@TrNo,2,@voucherNo,@invoiceDate,@PrAccount,'Credit Purchase Return #'
                +convert(varchar(10),@documentno),
                0,@NetAmount,@userCode,'1',@PinvoiceNo,'PR',getdate(),@PartyCode,null,null
          ---- insert a new row for Sales Tax Payable
          /*if @saleTaxAmount<>0
insert into voucher
select @voucherType,@Trno,3,@voucherNo,@invoiceDate,@STAdvanceaccount,'Credit Purchase Return #'
+convert(varchar(10),@PinvoiceNo),
0,@saleTaxAmount,@userCode,'1',@PinvoiceNo,'PR',getdate(*),@PartyCode*/
          end
        if @status = '0'
          --- Delete the Enteries of Voucher 
