    @YearNo smallint,
    @Month varchar(2),
    @Year varchar(2),
    @debitAccount varchar(14),
    @CashAccount varchar(14),
    @SaleAccount varchar(14),
    @leftPart varchar(4),
    @rightPart varchar(3),
    @voucherType char(3),
    @Narration varchar(256),
    @Remarks varchar(256),
    @documentno t_document_no
    /* Select the Values from the inserted */
    select @invoiceNo = SaleInvoiceCode,
      @invoiceDate = InvoiceDate,
      @PartyCode = PartyCode,
      @PartyName = Name,
      @city = city,
      @SalesType = SalesType,
      @Remarks = Remarks,
      @DiscountAmount = isnull(DiscountAmount,0),
      @NetAmount = isnull(NetAmount,0),
      @status = Status,
      @userCode = userCode,
      @documentno = documentno
      from inserted
    --- Get the Cash, Sale and Sales Tax Payable Account
    select @CashAccount = CashAccount,
      @SaleAccount = SaleAccountCode
      from ProductControl
    --- Select Voucher Type
    if @SalesType = 0
      select @voucherType = 'CRV',@Narration = 'Sale vide Invoice No',@debitAccount = @cashAccount
    else
      select @voucherType = 'JVR',@Narration = 'Credit Sale Vide Invoice No',@debitAccount = @partyCode
    --- Procedure for Posting
    if @status = 1
      begin
        -- Get the Max Transaction ID and VoucherID
        select @TrNo = isnull(max(TransactionNo),0)
          from voucher
        --- Get the Maximum VoucherID of the Selected Voucher Type   
        select @VoucherNo = max(VoucherID)
          from voucher
          where vouchertype = @voucherType
          and dateformat(@invoicedate,'yymm') = "left"(VoucherID,4)
        --- Check to verify Whether to Create the a New VoucherID of Increment the Existing One
        if @VoucherNo is null
          begin
            select @MonthNo = Month(@invoiceDate),
              @YearNo = Year(@invoiceDate)
            -- Make sure the Two Digit Month No
            if length(trim(convert(varchar(2),@MonthNo))) = 1
              select @Month = '0'+convert(varchar(1),@MonthNo)
            else
              select @Month = convert(varchar(2),@MonthNo)
            -- Trancate the Year to Two Digits
            select @Year = "right"(convert(varchar(4),@YearNo),2)
            select @voucherNo = @Year+@Month+'001'
          end
        else
          begin
            --- Split the Voucher ID into Two Parts
            select @leftpart = "left"(@voucherNo,4)
            select @rightPart = "right"(@voucherNo,3)
            -- Incerment the right Part
            select @rightPart = convert(varchar(3),convert(integer,@rightPart)+1)
            -- Make Sure that Length of RightPart is of 3 Characters
            select @rightPart = String(Repeat('0',3-Length(@rightPart)),@rightPart)
            /*
if length(@rightPart)=1
select @rightPart='00'+@rightPart
if length(@rightPart)=2
select @rightPart='0'+@rightPart  */
            --- Make the New VoucherID
            select @voucherNo = @leftPart+@rightPart
          end
        --- Generate the New Transaction ID
        select @TrNo = @TrNo+1
        --- Insert a new Row in the Voucher Table
        insert into voucher
          select @voucherType,@TrNo,1,@voucherNo,@invoiceDate,@debitAccount,@Narration+convert(varchar(10),@documentno)+' '+@Remarks,
            @NetAmount,0,@userCode,'1',@invoiceNo,'SL',getdate(),@saleAccount,null,null
        ----- insert a new row for Sale
        insert into voucher
          select @voucherType,@TrNo,2,@voucherNo,@invoiceDate,@SaleAccount,@Narration+convert(varchar(10),@documentno)+' '+@Remarks,
            0,@NetAmount,@userCode,'1',@invoiceNo,'SL',getdate(),@debitAccount,null,null
      ---- insert a new row for Sales Tax Payable
