0,@saleTaxAmount,@userCode,'1',@invoiceNo,'SL',getdate(*),@debitAccount*/
      end
    if @status = '0'
      --- Delete the Enteries of Voucher 
      delete from voucher
        --vouchertype=@voucherType and
        where documentno = @invoiceNo
        and documentName = 'SL'
  end
