create trigger tr_purchase_update on
Saller.PurchaseHeader for update
as
if update(Status) begin
    declare @PInvoiceNo integer,
    @documentno integer,
    @InvoiceDate date,
    @PartyCode varchar(14),
    @PartyName varchar(128),
    @City varchar(32),
    @PurchaseType char(1),
    @DiscountAmount numeric(14,2),
    @NetAmount numeric(14,2),
    @Status char(1),
    @userCode varchar(10),
    @TrNo integer,
    @VrNo integer,
    @voucherNo varchar(10),
    @MonthNo tinyint,
    @YearNo smallint,
    @Month varchar(2),
    @Year varchar(2),
    @creditAccount varchar(14),
    @CashAccount varchar(14),
    @PurchaseAccount varchar(14),
    @leftPart varchar(4),
    @rightPart varchar(3),
    @Narration varchar(64),
    @voucherType char(3)
    /* Select the Values from the inserted */
    select @PinvoiceNo = PurchaseInvoiceCode,
      @documentno = documentno,
      @invoiceDate = PurchaseInvoiceDate,
      @PartyCode = PartyCode,
      @PartyName = Name,
      @city = city,
      @PurchaseType = PurchaseType,
      @DiscountAmount = isnull(DiscountAmount,0),
      @NetAmount = isnull(NetAmount,0),
      @status = Status,
      @userCode = userCode
      from inserted
    --- Get the Cash, Sale and Sales Tax Payble Account
    select @CashAccount = CashAccount,
      @PurchaseAccount = PurchaseAccountCode
      from ProductControl
    -- Select the VoucherType, Narration, creditAccount
    if @PurchaseType = '0'
      select @voucherType = 'CPV',@Narration = 'Purchase vide Invoice#',@creditAccount = @cashAccount
    else
      select @voucherType = 'JVR',@Narration = 'Credit Purchase vide Invoice#',@creditAccount = @PartyCode
    if @status = 1
      begin
        -- Get the Max Transaction ID and VoucherID
        select @TrNo = isnull(max(TransactionNo),0)
          from voucher
        --- Get the Maximum VoucherID of the Selected Voucher Type   
        select @VoucherNo = max(VoucherID)
          from voucher
          where vouchertype = @voucherType
          and dateformat(@invoicedate,'yymm') = "left"(VoucherID,4)
        --- Check to verify Whether to Create the a New VoucherID of Increment the Existing One
        if @VoucherNo is null
          begin
            select @MonthNo = Month(@invoiceDate),
              @YearNo = Year(@invoiceDate)
            if length(trim(convert(varchar(2),@MonthNo))) = 1
              select @Month = '0'+convert(varchar(1),@MonthNo)
            else
              select @Month = convert(varchar(2),@MonthNo)
            select @Year = "right"(convert(varchar(4),@YearNo),2)
            select @voucherNo = @Year+@Month+'001'
          end
        else
          begin
            --- Split the Voucher ID into Two Parts
            select @leftpart = "left"(@voucherNo,4)
            select @rightPart = "right"(@voucherNo,3)
            -- Incerment the right Part
            select @rightPart = convert(varchar(3),convert(integer,@rightPart)+1) --varchar(3)defult val
            -- Make Sure that Length of RightPart is of 3 Characters
            if length(@rightPart) = 1
              select @rightPart = '00'+@rightPart
            if length(@rightPart) = 2
              select @rightPart = '0'+@rightPart
            --if length(@rightPart)=3
            --select @rightPart='0'+@rightPart
            --- Make the New VoucherID
            select @voucherNo = @leftPart+@rightPart
          end
        --- Generate the New Transaction ID
        select @TrNo = @TrNo+1
        --- Insert a new Row in the Voucher Table
        insert into voucher
          select @voucherType,@TrNo,1,@voucherNo,@invoiceDate,@PurchaseAccount,@Narration
            +convert(varchar(10),@documentno),
            @NetAmount,0,@userCode,'1',@PinvoiceNo,'PU',getdate(),@creditAccount,null,null
        ----- insert a new row for Sale
        insert into voucher
          select @voucherType,@TrNo,2,@voucherNo,@invoiceDate,@creditAccount,@Narration
            +convert(varchar(10),@documentno),
            0,@NetAmount,@userCode,'1',@PinvoiceNo,'PU',getdate(),@PurchaseAccount,null,null
      ---- insert a new row for Sales Tax Payable
      /*if @saleTaxAmount<>0
insert into voucher
select @voucherType,@Trno,3,@voucherNo,@invoiceDate,@STAdvanceaccount,@Narration
+convert(varchar(10),@PinvoiceNo),
@saleTaxAmount,0,@userCode,'1',@PinvoiceNo,'PU',getdate(*),@creditAccount*/
      end
    if @status = '0'
      --- Delete the Enteries of Voucher 
      delete from voucher
        -- vouchertype=@voucherType and
        where documentno = @PinvoiceNo
        and documentName = 'PU'
  end
go

