create trigger saller.tr_update_voucher after update order 3 on
Saller.Voucher
referencing old as deleted new as inserted
for each row
begin
  if inserted.vouchertype in( 'CPV','BPV' ) and inserted.seqno = 1 and inserted.documentno is null then
    if update(accountcode)
      or update(narration)
      or update(debit) then
      update voucher
        set accountcode2 = inserted.accountcode,
        narration = inserted.narration,
        credit = inserted.debit
        where transactionno = inserted.transactionno
        and seqno = 2
    end if end if;
  if inserted.vouchertype in( 'CRV','BRV' ) and inserted.seqno = 1 and inserted.documentno is null then
    if update(accountcode)
      or update(narration)
      or update(credit) then
      update voucher
        set accountcode2 = inserted.accountcode,
        narration = inserted.narration,
        debit = inserted.credit
        where transactionno = inserted.transactionno
        and seqno = 2
    end if
  end if
end
