create trigger TR_SALE_DETAIL.TR_SALE_DETAIL on
saller.SALEINVOICEHEADER for delete
as
begin
  declare @DOCUMENT_NO T_DocumentNo,
  @SO_NO T_DocumentNo,
  @SO_QUANTITY T_Amount,
  @SL_QUANTITY T_Amount,
  @SO_STATUS T_Status
  /*Check whether the trigger is fired on insert or update operation or for Delete operation*/
  select @DOCUMENT_NO = SALEINVOICECODE,
    @SO_NO = SALEORDERNO
    from DELETED
  /*Getting the Quantity from SALE  */
  select @SL_QUANTITY = isNull(SUM(SD.QUANTITY),0) from SALEINVOICEDETAIL as SD
      join SALEINVOICEHEADER as SH
      on SH.SALEINVOICECODE = SD.SALEINVOICECODE
    where SH.SALEORDERNO = @SO_NO
  /*Getting the Quantity from SALEORDER */
  select @SO_QUANTITY = isNull(SUM(SOD.QUANTITY),0) from SALEORDERDETAIL as SOD
      join SAlEORDERHEADER as SOH
      on SOH.SALEORDERNO = SOD.SALEORDERNO
    where SOH.SALEORDERNO = @SO_NO
  print @SO_NO
  print @DOCUMENT_NO
  print @SO_QUANTITY
  print @SL_QUANTITY
  /* DETERMIN THE STATUS OF GRN*/
  if @SL_QUANTITY = 0
    select @SO_STATUS = 'N'
  else
    begin
      if @SL_QUANTITY < @SO_QUANTITY
        select @SO_STATUS = 'P'
      else
        select @SO_STATUS = 'F'
    end
  /*Update the Determined Status*/
  update SALEORDERHEADER
    set STATUS = @SO_STATUS
    where SALEORDERNO = @SO_NO
end
go

