  /*Getting the Quantity from SALE  */
  select @SL_QUANTITY=isNull(SUM(SD.QUANTITY),0) from SALEINVOICEDETAIL as SD join
    SALEINVOICEHEADER as SH on
    SH.SALEINVOICECODE=SD.SALEINVOICECODE where
