create trigger dpr_header_posting on
saller.Dprheader for update
as
begin
  declare @dpr_code numeric(10),
  @dpr_date date,
  @ShiftCode integer,
  @ShiftDesc varchar(256),
  @status varchar(1),
  @UserCode varchar(10),
  @DeptID varchar(10),
  @PartyCode varchar(14),
  @PartyName varchar(128),
  @NetAmount numeric(14,2),
  @TrNo integer,
  @VrNo integer,
  @voucherNo varchar(10),
  @MonthNo tinyint,
  @YearNo smallint,
  @Month varchar(2),
  @Year varchar(2),
  @creditAccount varchar(14),
  @PurchaseAccount varchar(14),
  @leftPart varchar(4),
  @rightPart varchar(3),
  @Narration varchar(64),
  @voucherType char(3)
  /*get values from the inserted */
  select @dpr_code = dprcode,
    @dpr_date = dprdate,
    @ShiftCode = ShiftCode,
    @ShiftDesc = ShiftDesc,
    @status = status,
    @UserCode = UserCode,
    @DeptID = DeptID,
    @PartyCode = AccountCode,
    @PartyName = AccountName
    from inserted
  -- Execute procedure for composition Note
  execute sp_post_dpr @dpr_code,@dpr_date,@status
  --- Get the Purchase Account from product control 
  select @PurchaseAccount = PurchaseAccountCode
    from ProductControl
  select @NetAmount = (select isnull(sum(amount),0) from dprdetail where dprcode = @dpr_code)
  select @voucherType = 'JVR',@Narration = 'Production Services Invoice#',@creditAccount = @PartyCode
  if @status = 1 and @NetAmount > 0 and @PartyCode is not null
    begin
      -- Get the Max Transaction ID and VoucherID
      select @TrNo = isnull(max(TransactionNo),0)
        from voucher
      --- Get the Maximum VoucherID of the Selected Voucher Type   
      select @VoucherNo = max(VoucherID)
        from voucher
        where vouchertype = @voucherType
        and dateformat(@dpr_date,'yymm') = "left"(VoucherID,4)
      --- Check to verify Whether to Create the a New VoucherID of Increment the Existing One
      if @VoucherNo is null
        begin
          select @MonthNo = Month(@dpr_date),
            @YearNo = Year(@dpr_date)
          if length(trim(convert(varchar(2),@MonthNo))) = 1
            select @Month = '0'+convert(varchar(1),@MonthNo)
          else
            select @Month = convert(varchar(2),@MonthNo)
          select @Year = "right"(convert(varchar(4),@YearNo),2)
          select @voucherNo = @Year+@Month+'001'
        end
      else
        begin
          --- Split the Voucher ID into Two Parts
          select @leftpart = "left"(@voucherNo,4)
          select @rightPart = "right"(@voucherNo,3)
          -- Incerment the right Part
          select @rightPart = convert(varchar(3),convert(integer,@rightPart)+1)
          -- Make Sure that Length of RightPart is of 3 Characters
          if length(@rightPart) = 1
            select @rightPart = '00'+@rightPart
          if length(@rightPart) = 2
            select @rightPart = '0'+@rightPart
          --- Make the New VoucherID
          select @voucherNo = @leftPart+@rightPart
        end
      --- Generate the New Transaction ID
      select @TrNo = @TrNo+1
      --- Insert a new Row in the Voucher Table
      insert into voucher
        select @voucherType,@TrNo,1,@voucherNo,@dpr_date,@PurchaseAccount,@Narration
          +convert(varchar(10),@dpr_code),
          @NetAmount,0,@userCode,'1',@dpr_code,'DPR',getdate(),@creditAccount,null,null
      ----- insert a new row for Sale
      insert into voucher
        select @voucherType,@TrNo,2,@voucherNo,@dpr_date,@creditAccount,@Narration
          +convert(varchar(10),@dpr_code),
          0,@NetAmount,@userCode,'1',@dpr_code,'DPR',getdate(),@PurchaseAccount,null,null
    end
  if @status = '0'
    --- Delete the Enteries of Voucher 
    delete from voucher
      -- vouchertype=@voucherType and
      where documentno = @dpr_code
      and documentName = 'DPR'
end
go

