CREATE EVENT "saller"."Ue_AutoBackup" TYPE "BackupEnd"  ENABLE AT ALL
HANDLER
begin
  /* Event:   ue_NightlyBackup 
* Purpose: Create automatic backup of database to the specified folder.
*/
  declare cmd long varchar;
  declare day_name char(20);
  set day_name = DATENAME(weekday,current date);
  set cmd = 'BACKUP DATABASE DIRECTORY '
     || '''C:\\Backup\\IFSbackup\\' || day_name || ''' ';
  print '<<< AUTO BACKUP PROCESS STARTED >>>';
  print 'BACKINGUP DATABASE TO DEFAULT AUTO BACKUPS FOLDER...';
  execute immediate with escapes off cmd;
  print '<<< AUTO BACKUP PROCESS ENDED >>>'
end
